public class Solution {
    public int numMagicSquaresInside(int[][] grid) {
        if (grid == null || grid.length < 3 || grid[0].length < 3) return 0;

        int count = 0;
        for (int i = 0; i <= grid.length - 3; i++) {
            for (int j = 0; j <= grid[0].length - 3; j++) {
                if (isMagic(grid, i, j)) count++;
            }
        }
        return count;
    }

    private boolean isMagic(int[][] grid, int row, int col) {
        Set<Integer> set = new HashSet<>();
        int sum = 0;

        // check the first row
        for (int i = 0; i < 3; i++) {
            if (!set.add(grid[row][col + i])) return false;
            sum += grid[row][col + i];
        }

        // check rows and columns
        for (int i = 1; i < 3; i++) {
            int rowSum = 0;
            int colSum = 0;
            for (int j = 0; j < 3; j++) {
                if (!set.add(grid[row + i][col + j])) return false;
                rowSum += grid[row + i][col + j];
                colSum += grid[row + j][col + i];
            }
            if (rowSum != sum || colSum != sum) return false;
        }

        // check diagonals
        int diagonal1 = 0, diagonal2 = 0;
        for (int i = 0; i < 3; i++) {
            diagonal1 += grid[row + i][col + i];
            diagonal2 += grid[row + i][col + 2 - i];
        }

        // check all numbers are between 1 and 9
        if (!set.containsAll(new HashSet<>(Set.of(1, 2, 3, 4, 5, 6, 7, 8, 9)))) return false;

        return diagonal1 == sum && diagonal2 == sum;
    }
}

