import java.util.Set;

public class Solution {
    public int numMagicSquaresInside(int[][] grid) {
        if (grid.length < 3 || grid[0].length < 3) return 0;

        int count = 0;
        for (int i = 0; i <= grid.length - 3; i++) {
            for (int j = 0; j <= grid[0].length - 3; j++) {

                if (isMagicSquare(grid, i, j)) {
                    count++;
                }
            }
        }

        return count;
    }

    private boolean isMagicSquare(int[][] grid, int row, int col) {
        Set<Integer> set = new HashSet<>();
        int sum = 0;

        for (int i = row; i < row + 3; i++) {
            for (int j = col; j < col + 3; j++) {
                if (grid[i][j] > 9 || grid[i][j] < 1) return false;
                set.add(grid[i][j]);
                sum += grid[i][j];
            }
        }

        if (set.size() != 9) return false;

        int targetSum = sum / 3;

        // check rows
        for (int i = row; i < row + 3; i++) {
            int rowSum = 0;
            for (int j = col; j < col + 3; j++) {
                rowSum += grid[i][j];
            }
            if (rowSum != targetSum) return false;
        }

        // check columns
        for (int i = col; i < col + 3; i++) {
            int columnSum = 0;
            for (int j = row; j < row + 3; j++) {
                columnSum += grid[j][i];
            }
            if (columnSum != targetSum) return false;
        }

        // check diagonals
        int diagonalSum1 = grid[row][col] + grid[row + 1][col + 1] + grid[row + 2][col + 2];
        int diagonalSum2 = grid[row][col + 2] + grid[row + 1][col + 1] + grid[row + 2][col];

        if (diagonalSum1 != targetSum || diagonalSum2 != targetSum) return false;

        return true;
    }
