import java.util.HashSet;

public class Solution {
    public int numMagicSquaresInside(int[][] grid) {
        int count = 0;
        for (int i = 0; i < grid.length - 2; i++) {
            for (int j = 0; j < grid[0].length - 2; j++) {
                if (isMagicSquare(grid, i, j)) {
                    count++;
                }
            }
        }
        return count;
    }

    private boolean isMagicSquare(int[][] grid, int row, int col) {
        int[] numbers = new int[9];
        int index = 0;
        for (int i = row; i < row + 3; i++) {
            for (int j = col; j < col + 3; j++) {
                if (grid[i][j] < 1 || grid[i][j] > 9) return false;
                numbers[index++] = grid[i][j];
            }
        }

        Set<Integer> set = new HashSet<>();
        for (int num : numbers) {
            if (!set.add(num)) return false;
        }

        int expectedSum = numbers[0] + numbers[1] + numbers[2];
        // Check rows
        for (int i = 3; i < 9; i += 3) {
            int sum = numbers[i] + numbers[i + 1] + numbers[i + 2];
            if (sum != expectedSum) return false;
        }

        // Check columns
        for (int i = 0; i < 3; i++) {
            int sum = numbers[i] + numbers[i + 3] + numbers[i + 6];
            if (sum != expectedSum) return false;
        }

        // Check diagonals
        int diagonal1 = numbers[0] + numbers[4] + numbers[8];
        int diagonal2 = numbers[2] + numbers[4] + numbers[6];

        return diagonal1 == expectedSum && diagonal2 == expectedSum;
    }
}

