// #2022_03_24_Time_1_ms_(68.54%)_Space_45_MB_(37.50%)
public class Solution {
    public int[][] flipAndInvertImage(int[][] image) {
        for (int[] row : image) {
            // Reverse each row
            reverse(row, 0, row.length - 1);
            // Invert the binary values in each row
            invertRow(row);
        }
        return image;
    }

    private void reverse(int[] array, int left, int right) {
        while (left < right) {
            int temp = array[left];
            array[left] = array[right];
            array[right] = temp;
            left++;
            right--;
        }
    }

    private void invertRow(int[] row) {
        for (int i = 0; i < row.length; i++) {
            // Invert the binary value: 1 becomes 0 and 0 becomes 1
            row[i] = row[i] == 0 ? 1 : 0;
        }
    }
}

