// #Hard #Array #Depth_First_Search #Breadth_First_Search #Matrix #Union_Find
// #2022_03_24_Time_147_ms_(74.37%)_Space_132.4_MB_(56.88%)
import java.util.HashMap;

public class Solution {
    private int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    public int largestIsland(int[][] grid) {
        if (grid == null || grid.length == 0) return 0;

        int n = grid.length;
        HashMap<Integer, Integer> sizeMap = new HashMap<>();
        int index = 2;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    dfs(grid, i, j, index, sizeMap);
                    index++;
                }
            }
        }

        int maxArea = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    Set<Integer> set = new HashSet<>();
                    for (int[] direction : directions) {
                        int x = i + direction[0];
                        int y = j + direction[1];
                        if (x >= 0 && x < n && y >= 0 && y < n && grid[x][y] > 1) {
                            set.add(grid[x][y]);
                        }
                    }
                    int area = 1;
                    for (int key : set) {
                        area += sizeMap.get(key);
                    }
                    maxArea = Math.max(maxArea, area);
                } else if (grid[i][j] == 1) {
                    maxArea = Math.max(maxArea, sizeMap.getOrDefault(grid[i][j], 0));
                }
            }
        }

        return maxArea;
    }

    private void dfs(int[][] grid, int i, int j, int index, HashMap<Integer, Integer> sizeMap) {
        if (i < 0 || j < 0 || i >= grid.length || j >= grid[0].length || grid[i][j] != 1) return;

        grid[i][j] = index;
        sizeMap.put(index, sizeMap.getOrDefault(index, 0) + 1);

        for (int[] direction : directions) {
            dfs(grid, i + direction[0], j + direction[1], index, sizeMap);
        }
    }
}

