import java.util.HashMap;
public class Solution {
    public int largestIsland(int[][] grid) {
        if (grid == null || grid.length == 0) return 0;

        HashMap<Integer, Integer> islandSize = new HashMap<>();
        int index = 2; // start from 2 because 0 and 1 are used in the grid
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == 1) {
                    islandSize.put(index, dfs(grid, i, j, index));
                    index++;
                }
            }
        }

        int maxIslandSize = 0;
        for (int[] row : grid) {
            for (int cell : row) {
                if (cell == 0) {
                    HashSet<Integer> neighbors = new HashSet<>();
                    if (i > 0 && grid[i - 1][j] > 1) neighbors.add(grid[i - 1][j]);
                    if (i < grid.length - 1 && grid[i + 1][j] > 1) neighbors.add(grid[i + 1][j]);
                    if (j > 0 && grid[i][j - 1] > 1) neighbors.add(grid[i][j - 1]);
                    if (j < grid[0].length - 1 && grid[i][j + 1] > 1) neighbors.add(grid[i][j + 1]);

                    int size = 1;
                    for (int neighbor : neighbors) {
                        size += islandSize.get(neighbor);
                    }
                    maxIslandSize = Math.max(maxIslandSize, size);
                }
            }
        }

        return maxIslandSize == 0 ? grid.length * grid[0].length : maxIslandSize;
    }

    private int dfs(int[][] grid, int i, int j, int index) {
        if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || grid[i][j] != 1) return 0;

        grid[i][j] = index;
        return 1 + dfs(grid, i - 1, j, index) + dfs(grid, i + 1, j, index) + dfs(grid, i, j - 1, index) + dfs(grid, i, j + 1, index);
    }
}

