import java.util.HashMap;
import java.util.*;

public class Solution {
    public int largestIsland(int[][] grid) {
        if (grid == null || grid.length == 0) return 0;

        HashMap<Integer, Integer> islandSize = new HashMap<>();
        int index = 2; // starting index for different islands

        // iterate through each cell in the grid
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == 1) {
                    // calculate size of current island and store it in hashmap
                    int size = dfs(grid, i, j, index);
                    islandSize.put(index, size);
                    index++;
                }
            }
        }

        int maxIslandSize = 0;
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == 0) {
                    // calculate size of new island when a '0' is changed to '1'
                    int newSize = getNewIslandSize(grid, i, j, islandSize);
                    maxIslandSize = Math.max(maxIslandSize, newSize);
                }
            }
        }

        // if no zeros are found in the grid, return size of largest island
        if (maxIslandSize == 0) {
            int maxSize = 0;
            for (int size : islandSize.values()) {
                maxSize = Math.max(maxSize, size);
            }
            return maxSize;
        }

        return maxIslandSize;
    }

    private int dfs(int[][] grid, int i, int j, int index) {
        if (i < 0 || j < 0 || i >= grid.length || j >= grid[0].length || grid[i][j] != 1) {
            return 0;
        }
        grid[i][j] = index; // mark current cell as visited and part of the current island
        int size = 1;

        // recursively visit all neighboring cells
        size += dfs(grid, i - 1, j, index);
        size += dfs(grid, i + 1, j, index);
        size += dfs(grid, i, j - 1, index);
        size += dfs(grid, i, j + 1, index);

        return size;
    }

    private int getNewIslandSize(int[][] grid, int i, int j, HashMap<Integer, Integer> islandSize) {
        Set<Integer> visited = new HashSet<>();
        int newSize = 1; // since we are changing a '0' to a '1'

        // check all neighboring cells and add size of connected islands
        if (i - 1 >= 0 && grid[i - 1][j] > 1) {
            if (!visited.contains(grid[i - 1][j])) {
                newSize += islandSize.get(grid[i - 1][j]);
                visited.add(grid[i - 1][j]);
            }
        }

        if (i + 1 < grid.length && grid[i + 1][j] > 1) {
            if (!visited.contains(grid[i + 1][j])) {
                newSize += islandSize.get(grid[i + 1][j]);
                visited.add(grid[i + 1][j]);
            }
        }

        if (j - 1 >= 0 && grid[i][j - 1] > 1) {
            if (!visited.contains(grid[i][j - 1])) {
                newSize += islandSize.get(grid[i][j - 1]);
                visited.add(grid[i][j - 1]);
            }
        }

        if (j + 1 < grid[0].length && grid[i][j + 1] > 1) {
            if (!visited.contains(grid[i][j + 1])) {
                newSize += islandSize.get(grid[i][j + 1]);
                visited.add(grid[i][j + 1]);
            }
        }

        return newSize;
    }
}

