import java.util.HashMap;
import java.util.HashSet;

public class Solution {
    public int largestIsland(int[][] grid) {
        int n = grid.length;
        if (n == 0) return 0;

        // Step 1: Give index to each island
        HashMap<Integer, Integer> islandIndex = new HashMap<>();
        int index = 2; // Start from 2 because we use 0 and 1 in the grid

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int size = dfs(grid, i, j, index);
                    islandIndex.put(index, size);
                    index++;
                }
            }
        }

        // Step 2: Iterate through all zeros and try to add them to each island
        int maxIslandSize = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    HashSet<Integer> islands = new HashSet<>();
                    int size = 1; // Size of the island after adding this zero

                    // Check all four directions
                    checkIsland(grid, i - 1, j, islands);
                    checkIsland(grid, i + 1, j, islands);
                    checkIsland(grid, i, j - 1, islands);
                    checkIsland(grid, i, j + 1, islands);

                    // Calculate the size of the new island
                    for (int idx : islands) {
                        size += islandIndex.get(idx);
                    }

                    maxIslandSize = Math.max(maxIslandSize, size);
                } else {
                    maxIslandSize = Math.max(maxIslandSize, islandIndex.get(grid[i][j]));
                }
            }
        }

        return maxIslandSize;
    }

    private int dfs(int[][] grid, int i, int j, int index) {
        if (i < 0 || j < 0 || i >= grid.length || j >= grid[0].length || grid[i][j] != 1) {
            return 0;
        }

        grid[i][j] = index; // Mark this cell as visited and assign the current island index
        int size = 1;

        size += dfs(grid, i - 1, j, index);
        size += dfs(grid, i + 1, j, index);
        size += dfs(grid, i, j - 1, index);
        size += dfs(grid, i, j + 1, index);

        return size;
    }

    private void checkIsland(int[][] grid, int i, int j, HashSet<Integer> islands) {
        if (i < 0 || j < 0 || i >= grid.length || j >= grid[0].length || grid[i][j] <= 1) {
            return;
        }

        if (!islands.contains(grid[i][j])) {
            islands.add(grid[i][j]);
        }
    }
}

