            return 0;
        }

        Car[] cars = new Car[position.length];
        for (int i = 0; i < position.length; i++) {
            cars[i] = new Car(position[i], speed[i]);
        }

        Arrays.sort(cars, Comparator.comparingInt(a -> a.position).reversed());

        int fleets = 1;
        double maxTimeToArrive = (double)(target - cars[0].position) / cars[0].speed;

        for (int i = 1; i < position.length; i++) {
            double timeToArrive = (double)(target - cars[i].position) / cars[i].speed;
            if (timeToArrive > maxTimeToArrive) {
                fleets++;
                maxTimeToArrive = timeToArrive;
            }
        }

        return fleets;
    }

    class Car {
        int position;
        int speed;

        public Car(int position, int speed) {
            this.position = position;
            this.speed = speed;
        }
    }
}

