import java.util.*;

public class Solution {
    public int carFleet(int target, int[] position, int[] speed) {
        List<int[]> cars = new ArrayList<>();

        for (int i = 0; i < position.length; i++) {
            cars.add(new int[] {position[i], speed[i]});
        }

        // Sort the cars by their positions in descending order
        Collections.sort(cars, Comparator.comparingInt(a -> a[0]).reversed());

        double maxTime = -1;
        int fleets = 0;

        for (int[] car : cars) {
            double time = (double)(target - car[0]) / car[1];

            // If the current car's arrival time is greater than the maximum time, 
            // it means this car will arrive at a later time and cannot catch up to any fleet
            if (time > maxTime) {
                fleets++;
                maxTime = time;
            }
        }

        return fleets;
    }
}

