import java.util.Arrays;

public class Solution {
    public int[] shortestToChar(String s, char c) {
        int n = s.length();
        int[] res = new int[n];

        // forward pass
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == c) {
                res[i] = 0;
            } else if (i > 0 && res[i - 1] != Integer.MAX_VALUE) {
                res[i] = res[i - 1] + 1;
            }
        }

        // backward pass
        for (int i = n - 2; i >= 0; i--) {
            if (s.charAt(i + 1) == c) {
                res[i] = Math.min(res[i], 1);
            } else if (res[i + 1] != Integer.MAX_VALUE && (res[i] == 0 || res[i] > res[i + 1] + 1)) {
                res[i] = res[i + 1] + 1;
            }
        }

        return res;
    }
}

