import java.util.Arrays;
public class Solution {
    public int[] shortestToChar(String s, char c) {
        int n = s.length();
        int[] res = new int[n];

        // Forward pass
        int prev = Integer.MIN_VALUE / 2;
        for (int i = 0; i < n; ++i) {
            if (s.charAt(i) == c) prev = i;
            res[i] = i - prev;
        }

        // Backward pass
        prev = Integer.MAX_VALUE / 2;
        for (int i = n - 1; i >= 0; --i) {
            if (s.charAt(i) == c) prev = i;
            res[i] = Math.min(res[i], prev - i);
        }

        return res;
    }
}

