public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int profitableSchemes(int n, int minProfit, int[] group, int[] profit) {
        int[][][] dp = new int[group.length + 1][n + 1][minProfit + 1];

        // Initialize the base case where no crimes are committed
        for (int i = 0; i <= n; i++) {
            dp[0][i][0] = 1;
        }

        for (int i = 1; i <= group.length; i++) {
            int members = group[i - 1];
            int currentProfit = profit[i - 1];

            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= minProfit; k++) {
                    dp[i][j][k] = dp[i - 1][j][k];

                    if (j >= members) {
                        int prevProfit = Math.max(0, k - currentProfit);
                        dp[i][j][k] += dp[i - 1][j - members][prevProfit];
                        dp[i][j][k] %= MOD;
                    }
                }
            }
        }

        int result = 0;
        for (int i = minProfit; i <= minProfit; i++) {
            result += dp[group.length][n][i];
            result %= MOD;
        }

        return result;
    }
}

