                    if (j >= currGroup) {
                        int prevProfit = Math.max(0, k - currProfit);
                        dp[i][j][k] += dp[i - 1][j - currGroup][prevProfit];
                        dp[i][j][k] %= MOD;
                    }
                }
            }
        }

        // Sum up all the schemes that generate at least minProfit profit
        int result = 0;
        for (int i = minProfit; i <= minProfit; i++) {
            result += dp[group.length][n][i];
            result %= MOD;
        }

        return result;
    }
}

