public class Solution {
    private static final int MOD = (int)1e9 + 7;

    public int profitableSchemes(int n, int minProfit, int[] group, int[] profit) {
        int length = group.length;
        int[][][] dp = new int[length + 1][n + 1][minProfit + 1];

        for (int i = 0; i <= length; i++) {
            dp[i][0][0] = 1;
        }

        for (int i = 1; i <= length; i++) {
            int members = group[i - 1];
            int profits = profit[i - 1];

            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= minProfit; k++) {
                    dp[i][j][k] += dp[i - 1][j][k];

                    if (j >= members) {
                        int newProfit = Math.min(minProfit, k + profits);
                        dp[i][j][newProfit] += dp[i - 1][j - members][k];
                        dp[i][j][newProfit] %= MOD;
                    }

                    dp[i][j][k] %= MOD;
                }
            }
        }

        int result = 0;

        for (int i = minProfit; i <= minProfit; i++) {
            result += dp[length][n][i];
        }

        return result % MOD;
    }
}

