public class Solution {
    public int maxDistToClosest(int[] seats) {
        int n = seats.length;
        int maxDistance = 0;

        // Calculate the distance from the first person to the leftmost seat
        int leftDistance = 0;
        while (leftDistance < n && seats[leftDistance] == 0) {
            leftDistance++;
        }
        maxDistance = Math.max(maxDistance, leftDistance);

        // Calculate the distance between people in the middle
        int prevPersonIndex = -1;
        for (int i = 0; i < n; i++) {
            if (seats[i] == 1) {
                if (prevPersonIndex != -1) {
                    maxDistance = Math.max(maxDistance, (i - prevPersonIndex) / 2);
                }
                prevPersonIndex = i;
            }
        }

        // Calculate the distance from the last person to the rightmost seat
        int rightDistance = 0;
        while (rightDistance < n && seats[n - 1 - rightDistance] == 0) {
            rightDistance++;
        }
        maxDistance = Math.max(maxDistance, rightDistance);

        return maxDistance;
    }
}

