public class Solution {
    private Map<String, Double> memo = new HashMap<>();

    public double soupServings(int n) {
        if (n >= 4800) return 1;
        return dfs(n / 25, n / 25);
    }

    private double dfs(int a, int b) {
        if (a <= 0 && b > 0) return 1;
        if (a <= 0 && b <= 0) return 0.5;
        if (b <= 0) return 0;

        String key = a + "," + b;
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        double res = 0.25 * dfs(a - 4, b)
                + 0.25 * dfs(a - 3, b - 1)
                + 0.25 * dfs(a - 2, b - 2)
                + 0.25 * dfs(a - 1, b - 3);

        memo.put(key, res);
        return res;
    }
}

