public class Solution {
    public double new21Game(int n, int k, int w) {
        if (k == 0 || n >= k + w) return 1;

        double[] dp = new double[n + 1];
        dp[k] = 1;

        double sum = 1.0;
        for (int i = k + 1; i <= n; i++) {
            dp[i] = sum / w;
            sum -= (i - w > k ? dp[i - w] : 0);
            if (i < k + w) sum += 1;
        }

        return dp[n];
    }
}

