public class Solution {
    public double new21Game(int n, int k, int w) {
        if (k == 0 || n >= k + w) return 1.0;

        double[] dp = new double[n + 1];
        dp[k] = 1.0;

        double sum = 1.0;

        for (int i = k + 1; i <= n; i++) {
            dp[i] = sum / w;
            sum -= dp[i - w];
            if (i - w >= k) {
                sum += dp[i - w];
            }
        }

        double res = 0.0;
        for (int i = 1; i <= n; i++) {
            res += dp[Math.min(n, i + k - 1)];
        }

        return res / w;
    }
}

