import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;

public class Solution {
    public List<String> findAndReplacePattern(String[] words, String pattern) {
        List<String> result = new ArrayList<>();

        for (String word : words) {
            if (isMatch(word, pattern)) {
                result.add(word);
            }
        }

        return result;
    }

    private boolean isMatch(String word, String pattern) {
        if (word.length() != pattern.length()) {
            return false;
        }

        HashMap<Character, Character> map = new HashMap<>();
        HashSet<Character> used = new HashSet<>();

        for (int i = 0; i < pattern.length(); i++) {
            char chPattern = pattern.charAt(i);
            char chWord = word.charAt(i);

            if (!map.containsKey(chPattern)) {
                if (!used.contains(chWord)) {
                    map.put(chPattern, chWord);
                    used.add(chWord);
                } else {
                    return false;
                }
            } else {
                if (map.get(chPattern) != chWord) {
                    return false;
                }
            }
        }

        return true;
    }
}

