import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public boolean isNStraightHand(int[] hand, int groupSize) {
        if (hand.length % groupSize != 0) return false;

        Arrays.sort(hand);

        Map<Integer, Integer> countMap = new HashMap<>();

        for (int num : hand) {
            countMap.put(num, countMap.getOrDefault(num, 0) + 1);
        }

        for (int num : hand) {
            if (countMap.get(num) > 0) {
                int consecutiveCount = 1;
                while (consecutiveCount < groupSize && countMap.containsKey(num + consecutiveCount) && countMap.get(num + consecutiveCount) > 0) {
                    consecutiveCount++;
                }
                for (int i = num; i < num + consecutiveCount; i++) {
                    if (!countMap.containsKey(i)) return false;
                    int newCount = countMap.get(i) - 1;
                    countMap.put(i, newCount);
                    if (newCount == 0) countMap.remove(i);
                }
            }
        }

        return true;
    }
}

