import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        s = s.substring(1, s.length() - 1);

        for (int i = 1; i < s.length(); i++) {
            String x = s.substring(0, i);
            String y = s.substring(i);

            if (canBeInterpreted(x) && canBeInterpreted(y)) {
                result.add("(" + getInterpretations(x).get(0) + ", " + getInterpretations(y).get(0) + ")");
            }
        }

        for (int i = 1; i < s.length(); i++) {
            String x = s.substring(0, i);
            String y = s.substring(i);

            if (canBeInterpreted(x)) {
                for (String yi : getInterpretations(y)) {
                    if (!yi.equals(getFirstElement(y))) {
                        result.add("(" + getFirstElement(x) + ", " + yi + ")");
                    }
                }
            }
        }

        for (int i = 1; i < s.length(); i++) {
            String x = s.substring(0, i);
            String y = s.substring(i);

            if (canBeInterpreted(y)) {
                for (String xi : getInterpretations(x)) {
                    if (!xi.equals(getFirstElement(x))) {
                        result.add("(" + xi + ", " + getFirstElement(y) + ")");
                    }
                }
            }
        }

        for (int i = 1; i < s.length(); i++) {
            String x = s.substring(0, i);
            String y = s.substring(i);

            if (!getInterpretations(x).isEmpty() && !getInterpretations(y).isEmpty()) {
                for (String xi : getInterpretations(x)) {
                    for (String yi : getInterpretations(y)) {
                        result.add("(" + xi + ", " + yi + ")");
                    }
                }
            }
        }

        return removeDuplicates(result);
    }

    private List<String> getFirstElements(List<String> list) {
        List<String> firstElements = new ArrayList<>();
        for (String element : list) {
            if (!element.equals(getFirstElement(list.get(0)))) {
                firstElements.add(element);
            }
        }
        return firstElements;
    }

    private String getFirstElement(String str) {
        String[] parts = str.split("");
        StringBuilder sb = new StringBuilder();
        for (String part : parts) {
            if (!part.equals("")) {
                sb.append(part);
                break;
            }
        }
        return sb.toString();
    }

    private List<String> getInterpretations(String s) {
        List<String> result = new ArrayList<>();

        if (!hasLeadingZero(s)) {
            result.add(s);
        }

        for (int i = 1; i < s.length(); i++) {
            String x = s.substring(0, i);
            String y = s.substring(i);

            if (!x.startsWith("0") || x.equals("0")) {
                if (!y.endsWith("0")) {
                    result.add(x + "." + y);
                }
            }
        }

        return result;
    }

    private List<String> removeDuplicates(List<String> list) {
        List<String> uniqueList = new ArrayList<>();
        for (String element : list) {
            if (!uniqueList.contains(element)) {
                uniqueList.add(element);
            }
        }
        return uniqueList;
    }

    private boolean canBeInterpreted(String s) {
        return !s.startsWith("0") || s.equals("0");
    }

    private boolean hasLeadingZero(String s) {
        return s.length() > 1 && s.startsWith("0");
    }
}

