// #Medium #String #Backtracking #2022_03_23_Time_4_ms_(98.95%)_Space_48.9_MB_(73.68%)
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        s = s.substring(1, s.length() - 1);
        backtrack(result, s, "");
        return result;
    }

    private void backtrack(List<String> result, String s, String current) {
        if (s.isEmpty()) {
            if (!current.isEmpty()) {
                result.add("(" + current.substring(0, current.indexOf(',')) + ", " + current.substring(current.indexOf(',') + 1) + ")");
            }
            return;
        }

        for (int i = 1; i <= s.length(); i++) {
            String part = s.substring(0, i);
            if ((part.startsWith("0") && part.length() > 1 && !part.contains(".")) || (part.contains(".") && part.endsWith("0"))) {
                continue;
            }

            if (!current.isEmpty()) {
                current += ",";
            }
            current += part;

            if (part.contains(".")) {
                backtrack(result, s.substring(i), current);
            } else {
                backtrack(result, s.substring(i), current);
                if (part.startsWith("0") && !part.equals("0")) {
                    continue;
                }
                String decimalPart = part + ".";
                for (int j = 1; j < 10 - decimalPart.length(); j++) {
                    StringBuilder sb = new StringBuilder(decimalPart);
                    while (j-- > 0) {
                        sb.append('9');
                    }
                    if (!current.isEmpty()) {
                        current += ",";
                    }
                    current += sb.toString();
                    backtrack(result, s.substring(i), current);
                    current = current.substring(0, current.lastIndexOf(','));
                }
            }

            if (!current.isEmpty()) {
                current = current.substring(0, current.lastIndexOf(','));
            } else {
                break;
            }
        }
    }
}

