// #Hard #Array #Matrix #Union_Find #2022_03_23_Time_12_ms_(94.92%)_Space_118.5_MB_(65.25%)
public class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int[] result = new int[hits.length];

        for (int i = 0; i < hits.length; i++) {
            if (grid[hits[i][0]][hits[i][1]] == 1) {
                dfs(grid, hits[i][0], hits[i][1]);
                result[i] = countBricks(grid);
                recoverGrid(grid, hits[i][0], hits[i][1]);
            }
        }

        return result;
    }

    private void dfs(int[][] grid, int x, int y) {
        if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || grid[x][y] == 0) {
            return;
        }

        grid[x][y] = 0;

        dfs(grid, x - 1, y);
        dfs(grid, x + 1, y);
        dfs(grid, x, y - 1);
        dfs(grid, x, y + 1);
    }

    private int countBricks(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        boolean[][] visited = new boolean[m][n];
        int count = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (!visited[i][j] && grid[i][j] == 1) {
                    boolean isStable = false;

                    for (int k = 0; k < 4; k++) {
                        int nx = i + dx[k];
                        int ny = j + dy[k];

                        if (nx >= 0 && nx < m && ny >= 0 && ny < n) {
                            if (grid[nx][ny] == -1 || (visited[nx][ny] && grid[nx][ny] == 1)) {
                                isStable = true;
                                break;
                            }
                        } else if (nx == -1) {
                            isStable = true;
                            break;
                        }
                    }

                    if (!isStable) {
                        dfs(grid, i, j);
                        count++;
                    } else {
                        visited[i][j] = true;
                    }
                }
            }
        }

        return count;
    }

    private void recoverGrid(int[][] grid, int x, int y) {
        grid[x][y] = 1;
    }
}

