// #Hard #Array #Matrix #Union_Find #2022_03_23_Time_12_ms_(94.92%)_Space_118.5_MB_(65.25%)
public class Solution {
    private static final int[][] DIRECTIONS = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int[] result = new int[hits.length];

        // mark the bricks that are going to be hit
        for (int i = 0; i < hits.length; i++) {
            int x = hits[i][0];
            int y = hits[i][1];
            if (grid[x][y] == 1) {
                grid[x][y] = -1;
            }
        }

        // drop the bricks
        for (int i = hits.length - 1; i >= 0; i--) {
            int x = hits[i][0];
            int y = hits[i][1];

            if (grid[x][y] == -1) { // only consider the brick that is going to be hit
                grid[x][y] = 1; // restore the brick

                // count the number of bricks that can fall after this brick is removed
                int count = countFallingBricks(grid, x, y);
                result[i] = count;

                // remove the brick and let other bricks fall
                grid[x][y] = 0;
            }
        }

        return result;
    }

    private int countFallingBricks(int[][] grid, int x, int y) {
        int m = grid.length;
        int n = grid[0].length;

        // count the number of bricks that can fall
        int count = 0;

        if (isStable(grid, x, y)) {
            count++;
            dfs(grid, x, y);
        }

        return count - 1; // subtract the brick we are checking itself
    }

    private boolean isStable(int[][] grid, int x, int y) {
        int m = grid.length;
        int n = grid[0].length;

