import java.util.*;

public class Solution {
    private int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;

        // mark the bricks that will be hit
        for (int i = 0; i < hits.length; i++) {
            int x = hits[i][0];
            int y = hits[i][1];
            if (grid[x][y] == 1) {
                grid[x][y] = -1;
            }
        }

        // union find
        UnionFind uf = new UnionFind(m * n + 1);

        // connect the top row to the dummy node
        for (int i = 0; i < n; i++) {
            if (grid[0][i] == 1) {
                uf.union(i, m * n);
            }
        }

        // connect the adjacent bricks
        for (int i = 0; i < m - 1; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    if (grid[i + 1][j] == 1) {
                        uf.union(i * n + j, (i + 1) * n + j);
                    }
                    if (j > 0 && grid[i][j - 1] == 1) {
                        uf.union(i * n + j, i * n + j - 1);
                    }
                }
            }
        }

        int[] res = new int[hits.length];

        // apply hits in reverse order
        for (int i = hits.length - 1; i >= 0; i--) {
            int x = hits[i][0];
            int y = hits[i][1];

            if (grid[x][y] == -1) {
                grid[x][y] = 1;

                // connect the current brick to its adjacent bricks
                for (int[] dir : directions) {
                    int nx = x + dir[0];
                    int ny = y + dir[1];

                    if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid[nx][ny] == 1) {
                        uf.union(x * n + y, nx * n + ny);
                    }
                }

                // count the number of bricks that are connected to the top row
                if (x > 0 && grid[x - 1][y] == 1) {
                    uf.union(x * n + y, (x - 1) * n + y);
                } else if (x == 0) {
                    uf.union(x * n + y, m * n);
                }

                res[i] = uf.getSize(m * n) - 1;
            } else {
                res[i] = 0;
            }
        }

        return res;
    }

    private class UnionFind {
        int[] parent;
        int[] size;

        public UnionFind(int n) {
            parent = new int[n];
            size = new int[n];

            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX == rootY) {
                return;
            }

            if (size[rootX] < size[rootY]) {
                parent[rootX] = rootY;
                size[rootY] += size[rootX];
            } else {
                parent[rootY] = rootX;
                size[rootX] += size[rootY];
            }
        }

        public int getSize(int x) {
            return size[find(x)];
        }
    }
}

