public class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int[] result = new int[hits.length];

        // Check if a cell is within the grid boundaries
        boolean isValid(int x, int y) {
            return x >= 0 && x < m && y >= 0 && y < n;
        }

        // Get all adjacent cells of a given cell
        int[][] getNeighbors(int x, int y) {
            int[][] neighbors = new int[4][2];
            int index = 0;
            if (isValid(x - 1, y)) {
                neighbors[index++] = new int[] {x - 1, y};
            }
            if (isValid(x + 1, y)) {
                neighbors[index++] = new int[] {x + 1, y};
            }
            if (isValid(x, y - 1)) {
                neighbors[index++] = new int[] {x, y - 1};
            }
            if (isValid(x, y + 1)) {
                neighbors[index++] = new int[] {x, y + 1};
            }

            // Trim the array to remove unused elements
            int[][] trimmedNeighbors = new int[index][2];
            System.arraycopy(neighbors, 0, trimmedNeighbors, 0, index);
            return trimmedNeighbors;
        }

        // Check if a cell is stable (i.e., connected to the top or has a stable neighbor)
        boolean isStable(int x, int y) {
            if (x == 0) {
                return true; // Top row
            }
            for (int[] neighbor : getNeighbors(x, y)) {
                if (grid[neighbor[0]][neighbor[1]] == 2) {
                    return true; // Stable neighbor
                }
            }
            return false;
        }

        // Mark cells as visited by setting their value to -1
        void dfs(int x, int y) {
            if (!isValid(x, y) || grid[x][y] != 1) {
                return;
            }
            grid[x][y] = -1;

            for (int[] neighbor : getNeighbors(x, y)) {
                dfs(neighbor[0], neighbor[1]);
            }
        }

        // Mark all unstable cells
        void markUnstableCells() {
            for (int i = 0; i < m; i++) {
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == -1) {
                        grid[i][j] = 0;
                    } else if (grid[i][j] == 1 && !isStable(i, j)) {
                        dfs(i, j);
                    }
                }
            }
        }

        // Count the number of cells that will fall after an erasure
        int countFallingCells(int x, int y) {
            int count = 0;
            for (int[] neighbor : getNeighbors(x, y)) {
                if (grid[neighbor[0]][neighbor[1]] == -1) {
                    dfs(neighbor[0], neighbor[1]);
                    count++;
                }
            }
            return count;
        }

        // Apply all erasures
        for (int i = hits.length - 1; i >= 0; i--) {
            int x = hits[i][0];
            int y = hits[i][1];

            if (grid[x][y] == 1) {
                grid[x][y] = -1;
                result[i] = countFallingCells(x, y);
            } else {
                result[i] = 0;
            }

            // Mark all unstable cells after the erasure
            markUnstableCells();
        }

        return result;
    }
}

