public class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int[] result = new int[hits.length];

        for (int i = 0; i < hits.length - 1; i++) {
            int x = hits[i][0], y = hits[i][1];
            if (grid[x][y] == 1) {
                grid[x][y] = 2;
            }
        }

        // Mark the bricks that are directly connected to the top of the grid as stable
        for (int j = 0; j < n; j++) {
            dfs(grid, m - 1, j);
        }

        int index = hits.length - 1;

        for (int i = hits.length - 1; i >= 0; i--) {
            int x = hits[i][0], y = hits[i][1];
            if (grid[x][y] == 2) {
                grid[x][y] = 1;
            } else if (grid[x][y] == 1) {
                result[index--] = dfs(grid, x, y) - 1;
            }
        }

        return result;
    }

    private int dfs(int[][] grid, int i, int j) {
        if (i < 0 || j < 0 || i >= grid.length || j >= grid[0].length || grid[i][j] != 1) {
            return 0;
        }

        grid[i][j] = -1;
        int count = 1;

        if (i == grid.length - 1 || (i + 1 < grid.length && grid[i + 1][j] > 0)) {
            count += dfs(grid, i - 1, j);
            count += dfs(grid, i + 1, j);
            count += dfs(grid, i, j - 1);
            count += dfs(grid, i, j + 1);
        } else {
            grid[i][j] = 0;
        }

        return count;
    }
}

