        if (leftMaxDepth == maxDepth && rightMaxDepth == maxDepth) {
            result = node;
        } else if (leftMaxDepth == maxDepth) {
            result = node.left;
        } else if (rightMaxDepth == maxDepth) {
            result = node.right;
        }

        return Math.max(leftMaxDepth, rightMaxDepth);
    }
}

