public class Solution {
    private int maxDepth;
    public TreeNode subtreeWithAllDeepest(TreeNode root) {
        maxDepth = 0;
        return dfs(root, 0).node;
    }

    private Result dfs(TreeNode node, int depth) {
        if (node == null) 
            return new Result(depth - 1);

        Result left = dfs(node.left, depth + 1);
        Result right = dfs(node.right, depth + 1);

        maxDepth = Math.max(maxDepth, Math.max(left.depth, right.depth));

        if (left.depth == right.depth) {
            return new Result(node, Math.max(left.depth, right.depth), left.count + right.count + (Math.max(left.depth, right.depth) == maxDepth ? 1 : 0));
        } else if (left.depth > right.depth) {
            return new Result(left.node, left.depth, left.count + (left.depth == maxDepth ? 1 : 0));
        } else {
            return new Result(right.node, right.depth, right.count + (right.depth == maxDepth ? 1 : 0));
        }
    }

    private class Result {
        TreeNode node;
        int depth;
        int count;

        public Result(int depth) {
            this(null, depth);
        }

        public Result(TreeNode node, int depth) {
            this.node = node;
            this.depth = depth;
            this.count = 0;
        }

        public Result(TreeNode node, int depth, int count) {
