// #2022_03_24_Time_21_ms_(73.78%)_Space_54.4_MB_(50.10%)
public class Solution {
    public String pushDominoes(String dominoes) {
        char[] res = ('.' + dominoes + '.').toCharArray();
        int left = 0;

        for (int right = 0; right < res.length; right++) {
            if (res[right] != '.') {
                // calculate the value between these two pointers
                if (left < right) {
                    char currLeft = res[left];
                    char currRight = res[right];

                    if (currLeft == currRight) {
                        for (int i = left + 1; i < right; i++) {
                            res[i] = currLeft;
                        }
                    } else if (currLeft == 'R' && currRight == 'L') {
                        int mid = (left + right) / 2;

                        for (int i = left + 1; i <= mid; i++) {
                            res[i] = currLeft;
                        }

                        for (int i = mid + 1; i < right; i++) {
                            res[i] = currRight;
                        }
                    }
                }

                // move both pointers
                left = right;
            }
        }

        return String.valueOf(res).substring(1, res.length - 1);
    }
}

