public class Solution {
    public String pushDominoes(String dominoes) {
        int n = dominoes.length();
        char[] res = new char[n];

        int left = -1;
        for (int i = 0; i < n; ) {
            int j = i;
            while (j < n && dominoes.charAt(j) == '.') {
                j++;
            }

            if (j == n) {
                fill(res, left + 1, n - 1, 'R');
                break;
            } else if (dominoes.charAt(j) == 'L') {
                fill(res, left + 1, j - 1, '.');
                res[j] = 'L';
                left = j;
                i = j + 1;
            } else {
                fill(res, left + 1, j - 1, 'R');
                res[j] = 'R';
                left = j;
                i = j + 1;
            }
        }

        return new String(res);
    }

    private void fill(char[] res, int start, int end, char c) {
        if (start > end || start < 0) {
            return;
        }
        for (int i = start; i <= end; i++) {
            res[i] = c;
        }
    }
}

