public class Solution {
    public int subarrayBitwiseORs(int[] arr) {
        Set<Integer> set = new HashSet<>();
        for (int i = 0; i < arr.length; i++) {
            set.add(arr[i]);
            int prev = 0;
            for (int j = i - 1; j >= 0; j--) {
                prev |= arr[j];
