import java.util.PriorityQueue;

public class Solution {
    public int minRefuelStops(int target, int startFuel, int[][] stations) {
        if (startFuel >= target) return 0;

        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        int currentFuel = startFuel;
        int result = 0;
        int prevPosition = 0;

        for (int[] station : stations) {
            int position = station[0];
            int fuel = station[1];

            while (!pq.isEmpty() && currentFuel < position - prevPosition) {
                currentFuel += pq.poll();
                result++;
            }

            if (currentFuel < position - prevPosition) return -1;

            pq.offer(fuel);
            prevPosition = position;
        }

        while (!pq.isEmpty() && currentFuel < target - prevPosition) {
            currentFuel += pq.poll();
            result++;
        }

        return currentFuel >= target - prevPosition ? result : -1;
    }
}

