// #2022_03_28_Time_3_ms_(88.52%)_Space_48.8_MB_(60.04%)
import java.util.PriorityQueue;

public class Solution {
    public int minRefuelStops(int target, int startFuel, int[][] stations) {
        int position = 0;
        int refuelingStops = 0;
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>((a, b) -> b - a);

        for (int i = 0; i <= stations.length; i++) {
            int currentDistance = startFuel + position;

            while (!maxHeap.isEmpty() && currentDistance < target) {
                startFuel += maxHeap.poll();
                refuelingStops++;
                currentDistance = startFuel + position;
            }

            if (currentDistance < target) {
                return -1;
            }

            if (i < stations.length) {
                position = stations[i][0];
                maxHeap.offer(stations[i][1]);
            } else {
                break;
            }
        }

        return refuelingStops;
    }
}

