        if (colors[node] != -1 && colors[node] != color) {
            return false;
        }

        // Color the node
        colors[node] = color;

        // Try to color all neighbors with a different color
        for (int neighbor : graph.get(node)) {
            if (!dfs(graph, colors, neighbor, 1 - color)) {
                return false;
            }
        }

        return true;
    }
