    private boolean dfsUtil(List<Integer>[] graph, int[] colors, int node) {
        for (int neighbor : graph[node]) {
            if (colors[neighbor] == -1) {
                colors[neighbor] = 1 - colors[node];
                if (!dfsUtil(graph, colors, neighbor)) {
                    return false;
                }
            } else if (colors[neighbor] == colors[node]) {
                return false;
            }
        }
        return true;
    }
}

