public class Solution {
    public int maxProfitAssignment(int[] difficulty, int[] profit, int[] worker) {
        int n = difficulty.length;
        int[][] jobs = new int[n][2];

        for (int i = 0; i < n; i++) {
            jobs[i] = new int[] {difficulty[i], profit[i]};
        }

        Arrays.sort(jobs, (a, b) -> a[0] - b[0]);

        int maxProfitSoFar = 0;
        int[] bestProfits = new int[n];

        for (int i = 0; i < n; i++) {
            bestProfits[i] = Math.max(jobs[i][1], maxProfitSoFar);
            maxProfitSoFar = bestProfits[i];
        }

        int res = 0;

        for (int skill : worker) {
            int index =binarySearch(jobs, skill);
            if(index != -1){
                res += bestProfits[index];
            }
        }

        return res;
    }

    private int binarySearch(int[][] jobs, int target){
        int left = 0;
        int right = jobs.length - 1;

        while(left <= right){
            int mid = (left + right)/2;

            if(jobs[mid][0] <= target){
                if(mid == jobs.length-1 || jobs[mid+1][0] > target){
                    return mid;
                }
                left = mid+1;
            }else{
                right = mid - 1;
            }
        }

        return -1;
    }
}

