            int index = jobIndex[i];
            bestProfitByDifficulty[i] = Math.max(profit[index], maxProfitSoFar);
            maxProfitSoFar = bestProfitByDifficulty[i];
        }

        Arrays.sort(worker);

        int result = 0;
        for (int ability : worker) {
            int low = 0, high = difficulty.length - 1;
            while (low <= high) {
                int mid = (low + high) / 2;
                if (difficulty[jobIndex[mid]] > ability) {
                    high = mid - 1;
                } else {
                    low = mid + 1;
                }
            }

            if (high >= 0) {
                result += bestProfitByDifficulty[high];
            }
        }

        return result;
