import java.util.Map;

public class Solution {
    public boolean reorderedPowerOf2(int n) {
        String original = Integer.toString(n);
        char[] chars = original.toCharArray();
        for (int i = 0; i < 30; i++) {
            int powerOfTwo = (1 << i);
            String str = Integer.toString(powerOfTwo);
            if (isSameDigits(chars, str)) {
                return true;
            }
        }
        return false;
    }

    private boolean isSameDigits(char[] chars, String target) {
        if (chars.length != target.length()) {
            return false;
        }

        int[] count = new int[10];
        for (char c : chars) {
            count[c - '0']++;
        }
        for (char c : target.toCharArray()) {
            count[c - '0']--;
            if (count[c - '0'] < 0) {
                return false;
            }
        }

        return true;
    }
}

