import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

public class Solution {
    public boolean reorderedPowerOf2(int n) {
        String str = Integer.toString(n);
        Map<Character, Integer> countMap = new HashMap<>();

        for (char c : str.toCharArray()) {
            countMap.put(c, countMap.getOrDefault(c, 0) + 1);
        }

        for (int i = 0; i <= 30; i++) {
            String pow2Str = Long.toString(1L << i);

            Map<Character, Integer> currentCountMap = new HashMap<>();

            for (char c : pow2Str.toCharArray()) {
                currentCountMap.put(c, currentCountMap.getOrDefault(c, 0) + 1);
            }

            if (countMap.equals(currentCountMap)) {
                return true;
            }
        }

        return false;
    }
}

