// #2022_03_24_Time_15_ms_(80.39%)_Space_43.8_MB_(42.95%)
import java.util.*;

public class Solution {
    public int numSimilarGroups(String[] strs) {
        int n = strs.length;
        boolean[][] similar = new boolean[n][n];

        for (int i = 0; i < n - 1; i++) {
            for (int j = i + 1; j < n; j++) {
                if (isSimilar(strs[i], strs[j])) {
                    similar[i][j] = similar[j][i] = true;
                }
            }
        }

        int[] parent = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }

        for (int i = 0; i < n - 1; i++) {
            for (int j = i + 1; j < n; j++) {
                if (similar[i][j]) {
                    union(parent, i, j);
                }
            }
        }

        Set<Integer> groups = new HashSet<>();
        for (int i = 0; i < n; i++) {
            int group = find(parent, i);
            groups.add(group);
        }

        return groups.size();
    }

    private boolean isSimilar(String s1, String s2) {
        if (s1.equals(s2)) {
            return true;
        }
        int diffCount = 0;
        for (int i = 0; i < s1.length(); i++) {
            if (s1.charAt(i) != s2.charAt(i)) {
                diffCount++;
            }
            if (diffCount > 2) {
                return false;
            }
        }
        return diffCount == 2 && canSwap(s1, s2);
    }

    private boolean canSwap(String s1, String s2) {
        char[] arr = s1.toCharArray();
        for (int i = 0; i < s1.length(); i++) {
            for (int j = i + 1; j < s1.length(); j++) {
                swap(arr, i, j);
                if (new String(arr).equals(s2)) {
                    return true;
                }
                swap(arr, i, j); // backtrack
            }
        }
        return false;
    }

    private void swap(char[] arr, int i, int j) {
        char temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    private int find(int[] parent, int x) {
        if (parent[x] != x) {
            parent[x] = find(parent, parent[x]);
        }
        return parent[x];
    }

    private void union(int[] parent, int x, int y) {
        int rootX = find(parent, x);
        int rootY = find(parent, y);
        if (rootX != rootY) {
            parent[rootX] = rootY;
        }
    }
}

