public class Solution {
    public int uniqueLetterString(String s) {
        int res = 0;
        int[] lastSeenIdx = new int[26];
        int[] prevLastSeenIdx = new int[26];

        Arrays.fill(lastSeenIdx, -1);
        Arrays.fill(prevLastSeenIdx, -1);

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            int idx = ch - 'A';

            if (lastSeenIdx[idx] != -1) {
                prevLastSeenIdx[idx] = lastSeenIdx[idx];
            }

            lastSeenIdx[idx] = i;

            res += countUniqueChars(s, i + 1, prevLastSeenIdx, lastSeenIdx);
        }

        return res;
    }

    private int countUniqueChars(String s, int len, int[] prevLastSeenIdx, int[] lastSeenIdx) {
        int count = 0;
        for (int j = 0; j < 26; j++) {
            if (lastSeenIdx[j] == -1 || lastSeenIdx[j] >= s.length() - len + 1) continue;

            if (prevLastSeenIdx[j] == -1 || prevLastSeenIdx[j] < s.length() - len + 1) count++;
        }
        return count;
    }
}

