            int eIndex = 0, oIndex = 0;
            for (int i = 0; i < word.length(); i++) {
                if (i % 2 == 0) {
                    even[eIndex++] = word.charAt(i);
                } else {
                    odd[oIndex++] = word.charAt(i);
                }
            }

            java.util.Arrays.sort(even);
            java.util.Arrays.sort(odd);

            set.add(new String(even) + new String(odd));
        }

        return set.size();
    }
}

