        int m = grid.length;
        int n = grid[0].length;

        // Ensure the first column has as many 1s as possible
        for (int i = 0; i < m; i++) {
            if (grid[i][0] == 0) {
                flipRow(grid, i);
            }
        }

        // For each remaining column, ensure it has as many 1s as possible
        for (int j = 1; j < n; j++) {
            int countOnes = 0;
            int countZeros = 0;

            for (int i = 0; i < m; i++) {
                if (grid[i][j] == 1) {
                    countOnes++;
                } else {
                    countZeros++;
                }
            }

            // If the number of zeros is more than the number of ones, flip this column
            if (countZeros > countOnes) {
                flipColumn(grid, j);
            }
        }

        int score = 0;
        for (int i = 0; i < m; i++) {
            score += binaryToDecimal(grid[i]);
        }

        return score;
    }

    private void flipRow(int[][] grid, int row) {
        for (int j = 0; j < grid[0].length; j++) {
            grid[row][j] ^= 1; // XOR to flip the bit
        }
    }

    private void flipColumn(int[][] grid, int column) {
        for (int i = 0; i < grid.length; i++) {
            grid[i][column] ^= 1; // XOR to flip the bit
        }
