import java.util.*;

public class Solution {
    public int[] sumOfDistancesInTree(int n, int[][] edges) {
        List<List<Integer>> adjacencyList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adjacencyList.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            adjacencyList.get(edge[0]).add(edge[1]);
            adjacencyList.get(edge[1]).add(edge[0]);
        }

        int[] count = new int[n];
        Arrays.fill(count, 1);

        int[] answer = new int[n];

        dfs(0, -1, adjacencyList, count, answer);

        for (int i = 0; i < n; i++) {
            answer[i] = sumOfDistances(adjacencyList, count, i);
        }

        return answer;
    }

    private void dfs(int node, int parent, List<List<Integer>> adjacencyList, int[] count, int[] res) {
        for (int child : adjacencyList.get(node)) {
            if (child == parent) continue;
            dfs(child, node, adjacencyList, count, res);
            count[node] += count[child];
        }
    }

    private int sumOfDistances(List<List<Integer>> adjacencyList, int[] count, int node) {
        int n = count.length;
        return n - 1 - (count[node] - 1) + sumOfChildren(adjacencyList, count, node);
    }

    private int sumOfChildren(List<List<Integer>> adjacencyList, int[] count, int node) {
        int res = 0;
        for (int child : adjacencyList.get(node)) {
            if (child != -1) {
                res += count[child];
            }
        }
        return res;
    }
}

