    private void addOrMergeInterval(Event event, List<Interval> intervals) {
        Interval newInterval = new Interval(event.startX, event.endX);
        int index = Collections.binarySearch(intervals, newInterval);
        if (index < 0) {
            index = -index - 1;
            intervals.add(index, newInterval);
        }
    }

    private void removeInterval(Event event, List<Interval> intervals) {
        Interval target = new Interval(event.startX, event.endX);
        int index = Collections.binarySearch(intervals, target);
        if (index >= 0) {
            intervals.remove(index);
        }
    }

    private long calcArea(List<Interval> intervals, int startY, int endY) {
        long area = 0;
        for (Interval interval : intervals) {
            area += (interval.endX - interval.startX) * (endY - startY);
        }
        return area;
    }

    static class Interval implements Comparable<Interval> {
        int startX;
        int endX;

        public Interval(int startX, int endX) {
            this.startX = startX;
            this.endX = endX;
        }

        @Override
        public int compareTo(Interval other) {
            return Integer.compare(this.startX, other.startX);
        }
    }

    static class Event implements Comparable<Event> {
