public class Solution {
    public int rectangleArea(int[][] rectangles) {
        long MOD = (long)(1e9 + 7);
        Set<Integer> xCoords = new TreeSet<>();

        // Extract all unique x coordinates
        for (int[] rectangle : rectangles) {
            xCoords.add(rectangle[0]);
            xCoords.add(rectangle[2]);
        }

        List<Integer> xs = new ArrayList<>(xCoords);

        // Sort the list of unique x coordinates
        Collections.sort(xs);

        int n = xs.size();
        long[] widths = new long[n - 1];

        for (int i = 0; i < n - 1; i++) {
            widths[i] = xs.get(i + 1) - xs.get(i);
        }

        List<List<Integer>> sweepLines = new ArrayList<>();
        Set<Integer> yCoords = new TreeSet<>();

        // Organize the input rectangles by their x coordinates
        for (int[] rectangle : rectangles) {
            if (!sweepLines.isEmpty() && sweepLines.get(sweepLines.size() - 1).get(0) == rectangle[0]) {
                List<Integer> lastSweepLine = sweepLines.get(sweepLines.size() - 1);
                lastSweepLine.add(rectangle[1]);
                lastSweepLine.add(rectangle[3]);
            } else {
                List<Integer> newSweepLine = new ArrayList<>();
                newSweepLine.add(rectangle[0]);
                newSweepLine.add(rectangle[1]);
                newSweepLine.add(rectangle[3]);
                sweepLines.add(newSweepLine);
            }
        }

        long area = 0;
        for (int i = 0; i < n - 1; i++) {
            List<Integer> currentSweepLine = sweepLines.get(i);
            int xCoord = currentSweepLine.get(0);

            // Sort the y coordinates of all rectangles at this sweep line
            Collections.sort(currentSweepLine.subList(1, currentSweepLine.size()));

            int numRectangles = (currentSweepLine.size() - 1) / 2;
            long[] heightDiffs = new long[numRectangles];
            for (int j = 0; j < numRectangles; j++) {
                heightDiffs[j] = currentSweepLine.get(2 * j + 2) - currentSweepLine.get(2 * j + 1);
            }

            // Update the area
            long totalHeight = 0;
            for (long diff : heightDiffs) {
                totalHeight += diff;
            }
            area += (totalHeight % MOD) * widths[i];
        }

        return (int)(area % MOD);
    }
}

