// #2022_03_24_Time_4_ms_(97.00%)_Space_43.2_MB_(41.20%)
import java.util.*;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int rectangleArea(int[][] rectangles) {
        List<Integer> xCoords = new ArrayList<>();
        List<int[]> sweepLineEvents = new ArrayList<>();

        for (int[] rect : rectangles) {
            xCoords.add(rect[0]);
            xCoords.add(rect[2]);

            // Event format: [type, x1, y1, x2]
            // Type 0: open event
            // Type 1: close event
            sweepLineEvents.add(new int[]{0, rect[1], rect[3], rect[0]});
            sweepLineEvents.add(new int[]{1, rect[1], rect[3], rect[2]});
        }

        Collections.sort(xCoords);
        Collections.sort(sweepLineEvents, (a, b) -> a[3] - b[3]);

        Set<Integer> openYs = new TreeSet<>();
        long area = 0;

        for (int i = 0; i < sweepLineEvents.size(); ) {
            int[] event = sweepLineEvents.get(i);
            int type = event[0];
            int y1 = event[1];
            int y2 = event[2];

            if (type == 0) {
                openYs.add(y1);
                openYs.add(y2);
            } else {
                openYs.remove(y1);
                openYs.remove(y2);
            }

            long width = xCoords.get(Collections.binarySearch(xCoords, event[3]) + 1) - event[3];

            List<Integer> sortedOpenYs = new ArrayList<>(openYs);

            for (int j = 0; j < sortedOpenYs.size() - 1; j++) {
                int top = sortedOpenYs.get(j);
                int bottom = sortedOpenYs.get(j + 1);

                area += ((long) width * (bottom - top));
                area %= MOD;
            }

            while (i < sweepLineEvents.size() && sweepLineEvents.get(i)[3] == event[3]) {
                i++;
            }
        }

        return (int) (area % MOD);
    }
}

