import java.util.*;

public class Solution {
    private static final int MOD = 1000000007;

    public int rectangleArea(int[][] rectangles) {
        Set<Integer> xSet = new HashSet<>();
        List<int[]> events = new ArrayList<>();

        for (int[] rect : rectangles) {
            xSet.add(rect[0]);
            xSet.add(rect[2]);
            events.add(new int[]{rect[1], -rect[0]});
            events.add(new int[]{rect[3], rect[0]});
        }

        List<Integer> xs = new ArrayList<>(xSet);
        Collections.sort(xs);

        Map<Integer, Integer> mapXToIndex = new HashMap<>();
        for (int i = 0; i < xs.size(); i++) {
            mapXToIndex.put(xs.get(i), i);
        }

        int[][] array = new int[events.size()][2];
        for (int i = 0; i < events.size(); i++) {
            array[i] = events.get(i);
        }

        Arrays.sort(array, (a, b) -> a[0] - b[0]);

        long res = 0;
        int[] active = new int[xs.size()];

        for (int i = 0; i < array.length;) {
            int y = array[i][0];

            while (i < array.length && array[i][0] == y) {
                if (array[i][1] < 0) {
                    active[mapXToIndex.get(-array[i][1])] = 1;
                } else {
                    active[mapXToIndex.get(array[i][1])] = 0;
                }
                i++;
            }

            int count = 0, pre = -1;
            for (int j = 0; j < xs.size(); j++) {
                if (active[j] == 1) {
                    if (pre == -1) {
                        pre = j;
                    }
                    count += xs.get(j + 1) - xs.get(j);
                } else {
                    if (pre != -1) {
                        res = (res + (long)count * (array[i - 1][0] - y)) % MOD;
                        pre = -1;
                    }
                }
            }
        }

        return (int)(res % MOD);
    }
}

