public class Solution {
    public boolean buddyStrings(String s, String goal) {
        int n = s.length(), m = goal.length();

        // If lengths are different, we cannot make the strings equal by swapping two characters.
        if (n != m) 
            return false;

        // Initialize variables to store the indices of the first and second differences found in the strings.
        int firstDiff = -1, secondDiff = -1;

        // Traverse both strings from left to right.
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) != goal.charAt(i)) {
                // If this is the first difference found, store its index and move on to find the second difference.
                if (firstDiff == -1) 
                    firstDiff = i;
                // If we've already found a first difference and now we're finding another one, store its index as well.
                else if (secondDiff == -1) 
                    secondDiff = i;
                // If there are more than two differences between the strings, it's impossible to make them equal by swapping just two characters.
                else 
                    return false;
            }
        }

        // If we found exactly one difference or no differences at all (which means the original string was already equal to the goal), 
        // then swapping cannot help us achieve equality. Unless, of course, there are repeating characters in the original string and it's not equal to the goal.
        if (firstDiff == -1) {
            boolean hasDuplicates = false;
            for (char c : s.toCharArray()) {
                if (s.indexOf(c) != s.lastIndexOf(c)) {
                    hasDuplicates = true;
                    break;
                }
            }
            return hasDuplicates && !s.equals(goal);
        } 
        // If we found exactly two differences, check whether swapping these characters would make the strings equal.
        else if (secondDiff == -1) 
            return false;
        else
            return s.charAt(firstDiff) == goal.charAt(secondDiff) && s.charAt(secondDiff) == goal.charAt(firstDiff);
    }
}

