public class Solution {
    private static final int MOD = (int) 1e9 + 7;
    private static final int[][] GCD = new int[7][7];

    static {
        for (int i = 1; i <= 6; i++) {
            for (int j = 1; j <= 6; j++) {
                GCD[i][j] = gcd(i, j);
            }
        }
    }

    public int distinctSequences(int n) {
        long[][] dp = new long[n + 1][7];
        for (int i = 1; i <= 6; i++) {
            dp[1][i] = 1;
        }
        for (int i = 2; i <= n; i++) {
            for (int j = 1; j <= 6; j++) {
                for (int k = 1; k <= 6; k++) {
                    if ((GCD[j][k] == 1) && (i - 2 < 0 || dp[i - 2][j] == 0)) {
                        dp[i][k] += dp[i - 1][j];
                        dp[i][k] %= MOD;
                    }
                }
            }
        }
        long sum = 0;
        for (int i = 1; i <= 6; i++) {
            sum += dp[n][i];
            sum %= MOD;
        }
        return (int) sum;
    }

    private int gcd(int a, int b) {
        if (b == 0) {
            return a;
        } else {
            return gcd(b, a % b);
        }
    }
}

