// #Hard #Dynamic_Programming #Memoization #2022_06_26_Time_254_ms_(91.67%)_Space_51.6_MB_(58.33%)
public class Solution {
    private static final int MOD = 1000000007;
    private Integer[][][] memo;

    public int distinctSequences(int n) {
        memo = new Integer[n + 1][7][n + 1];
        return dfs(n, 0, -1);
    }

    private int dfs(int n, int prev, int secondPrev) {
        if (n == 0) return 1;
        if (memo[6][prev][secondPrev] != null) return memo[6][prev][secondPrev];

        long res = 0;
        for (int i = 1; i <= 6; i++) {
            if ((i == prev && secondPrev == -1) || 
                (i == prev && n > 3 && gcd(secondPrev, i) != 1)) continue;

            if (n > 2 && i == secondPrev && prev != -1 && gcd(prev, i) != 1) {
                continue;
            }

            res = (res + dfs(n - 1, i, prev)) % MOD;
        }
        memo[6][prev][secondPrev] = (int) res;
        return memo[6][prev][secondPrev];
    }

    private int gcd(int a, int b) {
        if (b == 0) return a;
        return gcd(b, a % b);
    }
}

