// #Medium #Dynamic_Programming #Math #Combinatorics
// #2022_09_19_Time_1_ms_(99.66%)_Space_41.7_MB_(91.83%)
public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numberOfWays(int startPos, int endPos, int k) {
        int diff = Math.abs(endPos - startPos);

        if ((diff + k) % 2 == 1 || diff > k) {
            return 0;
        }

        return (int) ncr(k, (k + diff) / 2).mod(BigInteger.valueOf(MOD)).longValue();
    }

    private BigInteger ncr(int n, int r) {
        if (r > n - r) {
            return ncr(n, n - r);
        }

        BigInteger result = BigInteger.ONE;
        for (int i = r + 1; i <= n; i++) {
            result = result.multiply(BigInteger.valueOf(i));
        }

        for (int i = 2; i <= n - r; i++) {
            result = result.divide(BigInteger.valueOf(i));
        }

        return result;
    }
}

