// #2022_09_19_Time_1_ms_(99.66%)_Space_41.7_MB_(91.83%)
public class Solution {
    private static final int MOD = 1000000007;

    public int numberOfWays(int startPos, int endPos, int k) {
        int distance = Math.abs(startPos - endPos);

        if (distance > k || (k - distance) % 2 == 1) {
            return 0;
        }

        int stepsToReachEndPos = (k + distance) / 2;
        long result = nCr(k, stepsToReachEndPos);

        return (int)(result % MOD);
    }

    private long nCr(int n, int r) {
        if (r > n - r) {
            r = n - r;
        }

        long res = 1L;

        for (int i = 0; i < r; i++) {
            res = res * (n - i);
            res %= MOD;
            res *= modInverse(i + 1, MOD);
            res %= MOD;
        }

        return res;
    }

    private long modInverse(long a, int m) {
        long m0 = m;
        long y = 0, x = 1;

        if (m == 1)
            return 0;

        while (a > 1) {
            long q = a / m;
            long t = m;

            m = a % m;
            a = t;
            t = y;

            y = x - q * y;
            x = t;
        }

        if (x < 0)
            x += m0;

        return x;
    }
}

