public class Solution {
    public long taskSchedulerII(int[] tasks, int space) {
        HashMap<Integer, Long> lastTaskTime = new HashMap<>();
        long currentTime = 0;

        for (int task : tasks) {
            if (lastTaskTime.containsKey(task)) {
                long timeSinceLastTask = currentTime - lastTaskTime.get(task);
