import java.util.HashMap;

public class Solution {
    public long taskSchedulerII(int[] tasks, int space) {
        HashMap<Integer, Long> lastCompleted = new HashMap<>();
        long days = 0;

        for (int task : tasks) {
            if (lastCompleted.containsKey(task)) {
                long gapNeeded = space + 1; // minimum number of days to pass after a task
                long timeSinceLastTask = days - lastCompleted.get(task);

                if (timeSinceLastTask < gapNeeded) {
                    // if the gap needed is larger than the current time since last task,
                    // we need to wait until the gap needed is met
                    days += gapNeeded - timeSinceLastTask;
                }
            }

            // update the last completed day for this task type
            lastCompleted.put(task, days);
            days++;
        }

        return days;
    }
}

