import java.util.HashMap;
import java.util.Map;

/**
 * This public class Solution a solution for the task scheduler problem.
 */
public class Solution {
    /**
     * This method returns the minimum number of days required to complete all tasks.
     * 
     * @param tasks an array of positive integers representing tasks that need to be completed in order
     * @param space a positive integer representing the minimum number of days that must pass after the completion of a task before another task of the same type can be performed
     * @return the minimum number of days needed to complete all tasks
     */
    public long taskSchedulerII(int[] tasks, int space) {
        Map<Integer, Long> lastDone = new HashMap<>();
        long day = 0;

        for (int task : tasks) {
            if (lastDone.containsKey(task)) {
                day = Math.max(day + 1, lastDone.get(task) + space);
            }
            lastDone.put(task, day);
            day++;
        }

        return day;
    }
}

