public class Solution {
    public int minPathCost(int[][] grid, int[][] moveCost) {
        int m = grid.length;
        int n = grid[0].length;

        // Create a 2D array to store the minimum cost of reaching each cell
        int[][] dp = new int[m][n];

        // Initialize the first row of dp with the values from the grid
        for (int j = 0; j < n; j++) {
            dp[0][j] = grid[0][j];
        }

        // Iterate over each row in the grid
        for (int i = 1; i < m; i++) {
            // Iterate over each column in the current row
            for (int j = 0; j < n; j++) {
                int minCost = Integer.MAX_VALUE;

                // For each cell in the previous row, calculate the cost of moving to the current cell
                for (int k = 0; k < n; k++) {
                    int cost = dp[i - 1][k] + moveCost[grid[i - 1][k]][j] + grid[i][j];
                    minCost = Math.min(minCost, cost);
                }

                // Update the minimum cost of reaching the current cell
                dp[i][j] = minCost;
            }
        }

        // Return the minimum cost of reaching any cell in the last row
        int minPathCost = Integer.MAX_VALUE;
        for (int j = 0; j < n; j++) {
            minPathCost = Math.min(minPathCost, dp[m - 1][j]);
        }

        return minPathCost;
    }
}

