            int difference = nums[i] - i;

            // Check if the difference is already in the map
            if (frequencyMap.containsKey(difference)) {
                // If it exists, add the frequency to the bad pair count
                badPairCount += frequencyMap.get(difference);
            }

            // Update the frequency of the current difference
            frequencyMap.put(difference, frequencyMap.getOrDefault(difference, 0) + 1);
        }

        // Calculate the total number of pairs and subtract the good pairs to get the bad pairs
        long totalPairs = ((long) nums.length * (nums.length - 1)) / 2;
        return totalPairs - badPairCount;
    }
}

