// #2022_08_25_Time_20_ms_(100.00%)_Space_111.7_MB_(100.00%)
import com_github_leetcode.TreeNode;

public class Solution {
    int maxTime = 0;

    public int amountOfTime(TreeNode root, int start) {
        dfs(root, start);
        return maxTime;
    }

    private Pair dfs(TreeNode node, int start) {
        if (node == null) {
            return new Pair(0, false);
        }

        Pair left = dfs(node.left, start);
        Pair right = dfs(node.right, start);

        boolean currentInfected = node.val == start;

        // If the current node or one of its children is infected
        if (currentInfected || left.infected || right.infected) {
            int currentTime = 1 + Math.max(left.time, right.time);
            maxTime = Math.max(maxTime, currentTime);

            return new Pair(currentTime, true);
        }

        // If none of the current node or its children is infected
        return new Pair(0, false);
    }

    private static class Pair {
        int time;
        boolean infected;

        public Pair(int time, boolean infected) {
            this.time = time;
            this.infected = infected;
        }
    }
}

