// #2022_08_25_Time_20_ms_(100.00%)_Space_111.7_MB_(100.00%)
import com_github_leetcode.TreeNode;
import java.util.*;

public class Solution {
    private int maxTime = 0;

    public int amountOfTime(TreeNode root, int start) {
        Map<TreeNode, TreeNode> parentMap = new HashMap<>();
        buildParentMap(root, null, parentMap);

        Queue<TreeNode> queue = new LinkedList<>();
        Set<TreeNode> visited = new HashSet<>();
        queue.offer(getNode(root, start));
        visited.add(getNode(root, start));

        int time = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();

                if (node.left != null && !visited.contains(node.left)) {
                    queue.offer(node.left);
                    visited.add(node.left);
                }
                if (node.right != null && !visited.contains(node.right)) {
                    queue.offer(node.right);
                    visited.add(node.right);
                }
                if (parentMap.containsKey(node) && !visited.contains(parentMap.get(node))) {
                    queue.offer(parentMap.get(node));
                    visited.add(parentMap.get(node));
                }
            }
            time++;
        }

        return time - 1;
    }

    private void buildParentMap(TreeNode node, TreeNode parent, Map<TreeNode, TreeNode> parentMap) {
        if (node != null) {
            parentMap.put(node, parent);
            buildParentMap(node.left, node, parentMap);
            buildParentMap(node.right, node, parentMap);
        }
    }

    private TreeNode getNode(TreeNode root, int val) {
        if (root == null) return null;
        if (root.val == val) return root;

        TreeNode left = getNode(root.left, val);
        if (left != null) return left;

        return getNode(root.right, val);
    }
}

