// #2022_08_25_Time_20_ms_(100.00%)_Space_111.7_MB_(100.00%)
import com.github.leetcode.TreeNode;

public class Solution {
    private int maxTime = 0;

    public int amountOfTime(TreeNode root, int start) {
        dfs(root, new boolean[500], 0, start);
        return maxTime;
    }

    private int dfs(TreeNode node, boolean[] visited, int time, int start) {
        if (node == null || visited[node.val]) {
            return -1;
        }

        if (time > maxTime) {
            maxTime = time;
        }

        visited[node.val] = true;

        int left = dfs(node.left, visited, time + 1, start);
        int right = dfs(node.right, visited, time + 1, start);

        // backtrack
        if (node.val == start || time > 0) {
            return Math.max(time, Math.max(left, right)) - time;
        } else {
            return -1;
        }
    }
}

