import java.util.*;

public class Solution {
    public long countPairs(int n, int[][] edges) {
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }

        int[] size = new int[n];
        Arrays.fill(size, 1);

        for (int[] edge : edges) {
            union(parent, size, edge[0], edge[1]);
        }

        long totalPairs = 0;
        Map<Integer, Integer> groupCounts = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int groupId = find(parent, i);
            groupCounts.put(groupId, groupCounts.getOrDefault(groupId, 0) + 1);
        }

        long sumOfGroups = 0;
        for (int count : groupCounts.values()) {
            totalPairs += count * (n - count);
            sumOfGroups += count;
        }

        return totalPairs / 2;
    }

    private int find(int[] parent, int node) {
        if (parent[node] != node) {
            parent[node] = find(parent, parent[node]);
        }
        return parent[node];
    }

    private void union(int[] parent, int[] size, int node1, int node2) {
        int groupId1 = find(parent, node1);
        int groupId2 = find(parent, node2);

        if (groupId1 != groupId2) {
            if (size[groupId1] < size[groupId2]) {
                parent[groupId1] = groupId2;
                size[groupId2] += size[groupId1];
            } else {
                parent[groupId2] = groupId1;
                size[groupId1] += size[groupId2];
            }
        }
    }
}

