import java.util.*;

public class Solution {
    public long countPairs(int n, int[][] edges) {
        UnionFind uf = new UnionFind(n);

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            uf.union(u, v);
        }

        long[] count = new long[n];

        for (int i = 0; i < n; i++) {
            int root = uf.find(i);
            count[root]++;
        }

        long total = 0;

        for (long c : count) {
            if (c > 0) {
                total += (n - c) * c;
            }
        }

        return total / 2;
    }

    private class UnionFind {
        int[] parent;

        public UnionFind(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public void union(int u, int v) {
            int rootU = find(u);
            int rootV = find(v);

            if (rootU != rootV) {
                parent[rootV] = rootU;
            }
        }

        public int find(int x) {
            if (parent[x] == x) {
                return x;
            }

            parent[x] = find(parent[x]);
            return parent[x];
        }
    }
}

