// #2022_06_26_Time_32_ms_(100.00%)_Space_108.9_MB_(100.00%)
import java.util.*;

public class Solution {
    public long countPairs(int n, int[][] edges) {
        UnionFind uf = new UnionFind(n);

        // Connect nodes based on the given edges
        for (int[] edge : edges) {
            uf.union(edge[0], edge[1]);
        }

        // Count the number of nodes in each connected component
        HashMap<Integer, Integer> countMap = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int parent = uf.find(i);
            countMap.put(parent, countMap.getOrDefault(parent, 0) + 1);
        }

        // Calculate the total number of unreachable pairs
        long totalUnreachable = 0;
        for (int size : countMap.values()) {
            long otherNodes = n - size;
            totalUnreachable += size * otherNodes;
        }

        return totalUnreachable / 2; // Divide by 2 to avoid counting each pair twice
    }

    private class UnionFind {
        int[] parent;

        public UnionFind(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX != rootY) {
                parent[rootY] = rootX;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }
    }
}

