import java.util.*;

public class Solution {
    public int shortestSequence(int[] rolls, int k) {
        Set<Integer> set = new HashSet<>();
        BitSet bitSet = new BitSet(k + 1);

        for (int roll : rolls) {
            if (!set.contains(roll)) {
                set.add(roll);
            }

            if (bitSet.get(roll - 1)) {
                bitSet.clear();
                bitSet.set(roll);
            } else {
                bitSet.set(roll);
            }

            if (bitSet.cardinality() == k) {
                return k;
            }
        }

        int res = set.size();
        for (int i = 1; i <= k && res < k; i++) {
            if (!set.contains(i)) {
                break;
            }
            res++;
        }

        return res + 1;
    }
}

