    public int shortestSequence(int[] rolls, int k) {
        Set<Integer> set = new HashSet<>();
        for (int roll : rolls) {
            set.add(roll);
        }

        if(set.size() < k){
            return Math.min(k, rolls.length+1);
        }

        boolean foundAll = true;
        for(int i = 1; i <= k; i++){
            if(!set.contains(i)){
                foundAll = false;
                break;
            }
        }

        int left = 0;
        int minLength = Integer.MAX_VALUE;

        if (foundAll) {
            Set<Integer> windowSet = new HashSet<>();
            for (int right = 0; right < rolls.length; right++) {
                windowSet.add(rolls[right]);

                while (windowSet.size() == k) {
                    minLength = Math.min(minLength, right - left + 1);
                    windowSet.remove(rolls[left]);
                    left++;
                }
            }
        }

        if(minLength != Integer.MAX_VALUE){
            return minLength+1;
        }else{
            return k;
        }
    }
}

