public class Solution {
    public int maximumRobots(int[] chargeTimes, int[] runningCosts, long budget) {
        int n = chargeTimes.length;
        int left = 0;
        int maxRobots = 0;
        long sumRunningCosts = 0;
        long maxChargeTime = Long.MIN_VALUE;

        for (int right = 0; right < n; right++) {
            // Update sliding window sum and max
            sumRunningCosts += runningCosts[right];
            maxChargeTime = Math.max(maxChargeTime, chargeTimes[right]);

            // Shrink the window if condition is not met
            while (left <= right && maxChargeTime + (right - left + 1) * sumRunningCosts / (right - left + 1) > budget) {
                sumRunningCosts -= runningCosts[left];
                if (chargeTimes[left] == maxChargeTime) {
                    // Update max charge time
                    maxChargeTime = Long.MIN_VALUE;
                    for (int i = left + 1; i <= right; i++) {
                        maxChargeTime = Math.max(maxChargeTime, chargeTimes[i]);
                    }
                }
                left++;
            }

            // Update maximum number of robots
            maxRobots = Math.max(maxRobots, right - left + 1);
        }

        return maxRobots;
    }
}

