public class Solution {
    public int closestMeetingNode(int[] edges, int node1, int node2) {
        int n = edges.length;

        // Function to perform DFS from a given node and return the distance to each reachable node
        int[] dfs(int start) {
            boolean[] visited = new boolean[n];
            int[] dist = new int[n];
            Arrays.fill(dist, -1);

            Stack<int[]> stack = new Stack<>();
            stack.push(new int[]{start, 0});
            while (!stack.isEmpty()) {
                int[] curr = stack.pop();
                if (visited[curr[0]]) continue;

                visited[curr[0]] = true;
                dist[curr[0]] = curr[1];

                if (edges[curr[0]] != -1) {
                    stack.push(new int[]{edges[curr[0]], curr[1] + 1});
                }
            }

            return dist;
        }

        // Perform DFS from node1 and node2
        int[] distFromNode1 = dfs(node1);
        int[] distFromNode2 = dfs(node2);

        // Initialize the minimum maximum distance and the result node
        int minMaxDist = Integer.MAX_VALUE;
        int res = -1;

        // Iterate over all nodes to find the one with the minimum maximum distance
        for (int i = 0; i < n; i++) {
            if (distFromNode1[i] != -1 && distFromNode2[i] != -1) {
                int maxDist = Math.max(distFromNode1[i], distFromNode2[i]);
                if (maxDist < minMaxDist || (maxDist == minMaxDist && (res == -1 || i < res))) {
                    minMaxDist = maxDist;
                    res = i;
                }
            }
        }

        return res;
    }
}

