// #Medium #Depth_First_Search #Graph #2022_08_14_Time_18_ms_(89.33%)_Space_112.3_MB_(69.17%)
public class Solution {
    public int closestMeetingNode(int[] edges, int node1, int node2) {
        boolean[] visited = new boolean[edges.length];
        int minDistance = Integer.MAX_VALUE;
        int result = -1;

        for (int i = 0; i < edges.length; i++) {
            if (!visited[i]) {
                dfs(edges, node1, i, 0, visited, true);
                dfs(edges, node2, i, 0, visited, false);

                if (minDistance > getMinDistance(visited)) {
                    minDistance = getMinDistance(visited);
                    result = i;
                } else if (minDistance == getMinDistance(visited) && i < result) {
                    result = i;
                }

                resetVisited(visited);
            }
        }

        return result;
    }

    private void dfs(int[] edges, int node, int targetNode, int distance, boolean[] visited, boolean isFromNode1) {
        if (node == targetNode || visited[node]) {
            visited[node] = true;
            return;
        }

        visited[node] = true;

        if (edges[node] != -1) {
            dfs(edges, edges[node], targetNode, distance + 1, visited, isFromNode1);
        }
    }

    private int getMinDistance(boolean[] visited) {
        int minDistance = Integer.MAX_VALUE;
        for (int i = 0; i < visited.length; i++) {
            if (visited[i]) {
                minDistance = Math.min(minDistance, countSteps(visited, i));
            }
        }

        return minDistance;
    }

    private void resetVisited(boolean[] visited) {
        for (int i = 0; i < visited.length; i++) {
            visited[i] = false;
        }
    }

    private int countSteps(boolean[] visited, int node) {
        int steps = 0;

        while (!visited[node]) {
            steps++;
            if (node == -1 || !visited[node]) return Integer.MAX_VALUE;
            node--;
        }

        return steps;
    }
}

