public class Solution {
    public int closestMeetingNode(int[] edges, int node1, int node2) {
        int n = edges.length;
        Map<Integer, Integer> distanceFromNode1 = new HashMap<>();
        Map<Integer, Integer> distanceFromNode2 = new HashMap<>();

        calculateDistance(edges, node1, distanceFromNode1);
        calculateDistance(edges, node2, distanceFromNode2);

        int minMaxDistance = Integer.MAX_VALUE;
        int result = -1;

        for (int i = 0; i < n; i++) {
            if (distanceFromNode1.containsKey(i) && distanceFromNode2.containsKey(i)) {
                int maxDistance = Math.max(distanceFromNode1.get(i), distanceFromNode2.get(i));
                if (maxDistance < minMaxDistance) {
                    minMaxDistance = maxDistance;
                    result = i;
                } else if (maxDistance == minMaxDistance && (result == -1 || i < result)) {
                    result = i;
                }
            }
        }

        return result;
    }

    private void calculateDistance(int[] edges, int startNode, Map<Integer, Integer> distance) {
        Set<Integer> visited = new HashSet<>();
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{startNode, 0});
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            if (visited.contains(current[0])) {
                continue;
            }
            visited.add(current[0]);
            distance.put(current[0], current[1]);

            int nextNode = edges[current[0]];
            if (nextNode != -1) {
                queue.offer(new int[]{nextNode, current[1] + 1});
            }
        }
    }
}

