// #Medium #Depth_First_Search #Graph #2022_08_14_Time_18_ms_(89.33%)_Space_112.3_MB_(69.17%)
public class Solution {
    public int closestMeetingNode(int[] edges, int node1, int node2) {
        int n = edges.length;
        boolean[] vis1 = new boolean[n];
        boolean[] vis2 = new boolean[n];

        dfs(edges, node1, vis1);
        dfs(edges, node2, vis2);

        int res = -1;
        for (int i = 0; i < n; ++i) {
            if (vis1[i] && vis2[i]) {
                if (res == -1 || dis(node1, i, edges) + dis(node2, i, edges) < dis(node1, res, edges) + dis(node2, res, edges)
                        || (dis(node1, i, edges) + dis(node2, i, edges) == dis(node1, res, edges) + dis(node2, res, edges) && i < res)) {
                    res = i;
                }
            }
        }

        return res;
    }

    private int dis(int start, int end, int[] edges) {
        if (start == end)
            return 0;

        boolean[] vis = new boolean[edges.length];
        vis[start] = true;

        int d = 0;
        while (true) {
            d++;
            int next = -1;
            for (int i = 0; i < edges.length; ++i) {
                if (!vis[i])
                    continue;
                if (edges[i] == end)
                    return d;
                else if (edges[i] != -1 && !vis[edges[i]]) {
                    vis[edges[i]] = true;
                    next = edges[i];
                }
            }

            if (next == -1)
                break;

            start = next;
        }

        return Integer.MAX_VALUE;
    }

    private void dfs(int[] edges, int node, boolean[] visited) {
        while (!visited[node] && node != -1) {
            visited[node] = true;
            node = edges[node];
        }
    }
}

