public class Solution {
    public boolean matchReplacement(String s, String sub, char[][] mappings) {
        Set<Character>[] replacements = new HashSet[128];
        for (char i = 'a'; i <= 'z'; i++) {
            replacements[i] = new HashSet<>();
            replacements[i].add(i);
        }

        for (char[] mapping : mappings) {
            char oldChar = mapping[0], newChar = mapping[1];
            replacements[newChar].addAll(replacements[oldChar]);
            replacements[oldChar].add(newChar);
        }

        int lenS = s.length(), lenSub = sub.length();
        for (int i = 0; i <= lenS - lenSub; i++) {
            boolean match = true;
            for (int j = 0; j < lenSub; j++) {
                if (!replacements[sub.charAt(j)].contains(s.charAt(i + j))) {
                    match = false;
                    break;
                }
            }
            if (match) return true;
        }

        return false;
    }
}

