public class Solution {
    public boolean matchReplacement(String s, String sub, char[][] mappings) {
        Set<Character>[] graph = new Set[26];
        for (int i = 0; i < 26; i++) {
            graph[i] = new HashSet<>();
        }

        // Build the mapping graph
        for (char[] mapping : mappings) {
            char oldChar = mapping[0];
            char newChar = mapping[1];
            graph[oldChar - 'a'].add(newChar);
        }

        int n = s.length();
        int m = sub.length();

        for (int i = 0; i <= n - m; i++) {
            // Check if the substring can be matched at this position
            boolean match = true;
            Set<Character> used = new HashSet<>();
            for (int j = 0; j < m && match; j++) {
                char targetChar = sub.charAt(j);
                char currentChar = s.charAt(i + j);

                // If the character in 's' is not a replacement of the character in 'sub', set match to false
                if (currentChar != targetChar) {
                    boolean replaced = false;
                    for (char c : graph[targetChar - 'a']) {
                        if (c == currentChar && !used.contains(targetChar)) {
                            used.add(targetChar);
                            replaced = true;
                            break;
                        }
                    }
                    match = replaced;
                }

                // If the character in 's' does not match and cannot be replaced, set match to false
                if (!match) {
                    break;
                }
            }

            // If a match is found, return true
            if (match) {
