        int m = sub.length();

        // Create a set to store the character replacement rules
        Map<Character, Set<Character>> replacements = new HashMap<>();
        for (char[] mapping : mappings) {
            if (!replacements.containsKey(mapping[0])) {
                replacements.put(mapping[0], new HashSet<>());
            }
            replacements.get(mapping[0]).add(mapping[1]);
        }

        // Iterate over all possible substrings of s with the same length as sub
        for (int i = 0; i <= n - m; i++) {
            boolean match = true;
