                // If there's a replacement rule for c2 that includes c1, continue to the next character
                if (replacements.containsKey(c2) && replacements.get(c2).contains(c1)) {
                    continue;
                }

                // If no match is found, break the loop and check the next substring of s
                match = false;
                break;
            }

            // If a match is found, return true
            if (match) {
                return true;
            }
        }

        // If no match is found after checking all substrings of s, return false
