        long[] dp = new long[n + 2];

        // On day 1, one person discovers the secret
        dp[1] = 1;

        for (int i = 2; i <= n; i++) {
            // People who start sharing on this day are those who discovered it 'delay' days ago
            long newcomers = dp[i - delay];

            // People who forget on this day are those who discovered it 'forget' days ago
            if (i >= forget + 1) {
                long peopleWhoForget = dp[i - forget];

                // Total people who know the secret today is the sum of previous people minus those who forgot
