public class Solution {
    public int distributeCookies(int[] cookies, int k) {
        int n = cookies.length;
        boolean[] visited = new boolean[n];
        int[] totalAssigned = new int[k];

        return backtrack(cookies, 0, k, visited, totalAssigned);
    }

    private int backtrack(int[] cookies, int index, int k, boolean[] visited, int[] totalAssigned) {
        if (index == cookies.length) {
            int max = Integer.MIN_VALUE;
            for (int val : totalAssigned) {
                max = Math.max(max, val);
            }
            return max;
        }

        int minUnfairness = Integer.MAX_VALUE;

        for (int i = 0; i < k; i++) {
            if (i > 0 && totalAssigned[i - 1] == totalAssigned[i]) continue;

            totalAssigned[i] += cookies[index];
            minUnfairness = Math.min(minUnfairness, backtrack(cookies, index + 1, k, visited, totalAssigned));
            totalAssigned[i] -= cookies[index];

        }

        return minUnfairness;
    }
}

