// #Medium #Array #Dynamic_Programming #Bit_Manipulation #Backtracking #Bitmask
// #2022_06_16_Time_14_ms_(84.35%)_Space_39.6_MB_(92.46%)
public class Solution {
    public int distributeCookies(int[] cookies, int k) {
        Arrays.sort(cookies);
        int n = cookies.length;
        boolean[][] dp = new boolean[k][1 + (n - 1) * (cookies[n - 1] - cookies[0])];

        for (int i = 0; i <= n - 1; i++) {
            for (int j = 0; j < k; j++) {
                dp[j][i] = true;
            }
        }

        int[] sums = new int[k];

        for (int i = n - 2; i >= 0; i--) {
            boolean[][] ndp = new boolean[k][1 + (n - 1) * (cookies[n - 1] - cookies[0])];
            Arrays.fill(sums, 0);

            for (int j = 0; j < k; j++) {
                for (int s = 0; s <= n - 1; s++) {
                    if (!dp[j][s]) continue;
                    sums[j] += cookies[i + 1];

                    int psum = sums[j];
                    ndp[(j + 1) % k][(psum - (n - 2)) / (cookies[n - 1] - cookies[0])] = true;
                }
            }

            for (int j = 0; j < k; j++) {
                boolean[] row = new boolean[dp[j].length];

                System.arraycopy(ndp[j], 0, row, 0, ndp[j].length);

                dp[j] = row;
            }
        }

        int unfairness = Integer.MAX_VALUE;

        for (int i = 0; i <= n - 1; i++) {
            if (dp[0][i]) {
                unfairness = Math.min(unfairness, cookies[n - 1] + (cookies[n - 1] - cookies[0]) * i);
            }
        }

        return unfairness;
    }
}

