// #Medium #Array #Dynamic_Programming #Bit_Manipulation #Backtracking #Bitmask
// #2022_06_16_Time_14_ms_(84.35%)_Space_39.6_MB_(92.46%)
public class Solution {
    private int min = Integer.MAX_VALUE;

    public int distributeCookies(int[] cookies, int k) {
        Arrays.sort(cookies);
        backtrack(new int[k], cookies.length - 1, cookies);
        return min;
    }

    private void backtrack(int[] groups, int index, int[] cookies) {
        if (index < 0) {
            updateMin(groups);
            return;
        }

        for (int i = 0; i < groups.length; i++) {
            groups[i] += cookies[index];
            if (groups[i] >= min) break;
            backtrack(groups, index - 1, cookies);
            groups[i] -= cookies[index];
        }
    }

    private void updateMin(int[] groups) {
        int max = Integer.MIN_VALUE;
        for (int value : groups) {
            max = Math.max(max, value);
        }
        min = Math.min(min, max);
    }
}

