        int metalLastIndex = -1;
        int paperLastIndex = -1;
        int glassLastIndex = -1;

        for (int i = 0; i < garbage.length; i++) {
            char[] chars = garbage[i].toCharArray();
            boolean hasMetal = false;
            boolean hasPaper = false;
            boolean hasGlass = false;

            for (char c : chars) {
                if (c == 'M') hasMetal = true;
                else if (c == 'P') hasPaper = true;
                else hasGlass = true;
            }

            if (hasMetal) metalLastIndex = i;
            if (hasPaper) paperLastIndex = i;
            if (hasGlass) glassLastIndex = i;
        }

        int totalTravelTime = 0;

        for (int i = 1; i < garbage.length; i++) {
            totalTravelTime += travel[i - 1];
        }

        int metalTravelTime = 0;
        for (int i = 1; i <= metalLastIndex; i++) {
            if (i == metalLastIndex) break;
            metalTravelTime += travel[i - 1];
        }

        int paperTravelTime = 0;
        for (int i = 1; i <= paperLastIndex; i++) {
            if (i == paperLastIndex) break;
            paperTravelTime += travel[i - 1];
        }

        int glassTravelTime = 0;
        for (int i = 1; i <= glassLastIndex; i++) {
            if (i == glassLastIndex) break;
            glassTravelTime += travel[i - 1];
        }

        return metal + paper + glass + totalTravelTime - Math.max(metalTravelTime, Math.max(paperTravelTime, glassTravelTime));
    }
}

