public class Solution {
    public int garbageCollection(String[] garbage, int[] travel) {
        int metal = 0;
        int paper = 0;
        int glass = 0;

        for (int i = 0; i < garbage.length; i++) {
            String g = garbage[i];
            for (char c : g.toCharArray()) {
                if (c == 'M') metal++;
                else if (c == 'P') paper++;
                else if (c == 'G') glass++;
            }
        }

        int[] prefixTravel = new int[travel.length + 1];
        for (int i = 0; i < travel.length; i++) {
            prefixTravel[i + 1] = prefixTravel[i] + travel[i];
        }

        return collectGarbage(garbage, 'M', metal, prefixTravel) +
               collectGarbage(garbage, 'P', paper, prefixTravel) +
               collectGarbage(garbage, 'G', glass, prefixTravel);
    }

    private int collectGarbage(String[] garbage, char type, int count, int[] travel) {
        if (count == 0) return 0;

        int time = 0;
        for (int i = 0; i < garbage.length; i++) {
            String g = garbage[i];
            boolean hasType = false;
            for (char c : g.toCharArray()) {
                if (c == type) {
                    hasType = true;
                    break;
                }
            }

            if (hasType) {
                time += travel[i];
                for (char c : g.toCharArray()) {
                    if (c == type) {
                        time++;
                    }
                }
            }
        }

        return time;
    }
}

