public class Solution {
    public long zeroFilledSubarray(int[] nums) {
        long count = 0;
        int currentZeroCount = 0;

        for (int num : nums) {
            if (num == 0) {
                currentZeroCount++;
            } else {
                // Calculate the number of subarrays with zeros
                count += calculateSubarrayCount(currentZeroCount);
                currentZeroCount = 0;
            }
        }

        // Handle the case when the array ends with zero or more zeros
        count += calculateSubarrayCount(currentZeroCount);

        return count;
    }

    private long calculateSubarrayCount(int n) {
        if (n == 0) {
            return 0;
        } else {
            // Calculate the number of subarrays using the formula: (1 + 2 + ... + n) = n * (n + 1) / 2
            return (long) n * (n + 1) / 2;
        }
    }
