import java.util.*;

public class Solution {
    public long kSum(int[] nums, int k) {
        Arrays.sort(nums);
        PriorityQueue<Long> maxHeap = new PriorityQueue<>((a, b) -> Long.compare(b, a));

        // Initialize the maxHeap with sums of subsets containing only one element
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] > 0) {
                maxHeap.offer((long) nums[i]);
            }
        }

        long result = 0;
        while (!maxHeap.isEmpty() && k-- > 0) {
            result = maxHeap.poll();

            // Add sums of subsets containing one more element to the maxHeap
            for (int i = 0; i < nums.length; i++) {
                if (nums[i] <= 0) {
                    break;
                }
                long temp = result - nums[i];
                if (temp > 0 && !maxHeap.contains(temp)) {
                    maxHeap.offer(temp);
                }
            }
        }

        return result;
    }
}

