    public long kSum(int[] nums, int k) {
        PriorityQueue<Long> pq = new PriorityQueue<>((a, b) -> Long.compare(b, a));
        Set<List<Integer>> set = new HashSet<>();

        set.add(new ArrayList<>());

        for (int i = 0; i < k; i++) {
            PriorityQueue<Long> tempPq = new PriorityQueue<>((a, b) -> Long.compare(b, a));

            while (!pq.isEmpty() && pq.size() <= k - i) {
                long sum = pq.poll();

                List<Integer> list = null;
                for (List<Integer> l : set) {
                    if (getSum(l, nums) == sum) {
                        list = l;
                        break;
                    }
                }

                for (int j = 0; j < nums.length; j++) {
                    if (!list.contains(j)) {
                        List<Integer> newList = new ArrayList<>(list);
                        newList.add(j);
                        set.add(newList);

                        tempPq.offer(getSum(newList, nums));
                    }
                }
            }

            pq = tempPq;
        }

        return getSum(Collections.max(set, Comparator.comparingLong(o -> getSum(o, nums))), nums);
    }

    private long getSum(List<Integer> list, int[] nums) {
        long sum = 0;
        for (int i : list) {
            sum += nums[i];
        }
        return sum;
    }
