    public int countSpecialNumbers(int n) {
        char[] str = Integer.toString(n).toCharArray();
        int len = str.length;
        int res = 0;

        // for numbers with length less than len
        for (int i = 1; i < len; i++) {
            res += 9 * permutation(9, i - 1);
        }

        boolean[] visited = new boolean[10];
        dfs(str, 0, visited, n, len, res);

        return res;
