    private void dfs(char[] str, int index, boolean[] visited, int n, int len, int res) {
        if (index == len) {
            res++;
            return;
        }

        for (int i = 0; i < 10; i++) {
            if ((i == 0 && index == 0) || visited[i]) continue;

            if (i > str[index] - '0') break;

            if (i == str[index] - '0') {
                dfs(str, index + 1, visited, n, len, res);
            } else {
                boolean[] temp = new boolean[10];
                System.arraycopy(visited, 0, temp, 0, 10);
                temp[i] = true;
                dfs(str, index + 1, temp, n, len, res);
            }
        }
    }

    private int permutation(int m, int n) {
        int res = 1;

        for (int i = m; i > m - n; i--) {
            res *= i;
        }

        return res;
    }
}

