public class Solution {
    // number n as an array, splitted by each digit
    public int countSpecialNumbers(int n) {
        char[] nums = String.valueOf(n).toCharArray();
        int len = nums.length;
        int res = 0;

        for (int i = 1; i < len; i++) {
            res += 9 * factorial(9, i - 1);
        }

        boolean[] visited = new boolean[10];
        dfs(nums, 0, visited, n, len);

        return res;
    }

    private int dfs(char[] nums, int index, boolean[] visited, int n, int len) {
        if (index == len) return 1;
        int res = 0;

        for (int i = (index == 0 ? 1 : 0); i <= (nums[index] - '0'); i++) {
            if (visited[i]) continue;
            visited[i] = true;
            if (i < nums[index] - '0') {
                res += dfs(nums, index + 1, visited, n, len);
            } else if (i == nums[index] - '0') {
                res += dfs(nums, index + 1, visited, n, len);
            }
            visited[i] = false;
        }

        return res;
    }

    private int factorial(int a, int b) {
        int res = 1;
        for (int i = a; i > a - b; i--) {
            res *= i;
        }
        return res;
    }
}

