import java.util.PriorityQueue;

public class Solution {
    public int minimumOperations(int[] nums) {
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);

        for (int num : nums) {
            if (num > 0) {
                pq.offer(num);
            }
        }

        int operations = 0;

        while (!pq.isEmpty()) {
            int smallestNonZero = pq.poll();

            if (smallestNonZero == 0) {
                break;
            }

            for (int i = nums.length - 1; i >= 0; i--) {
                if (nums[i] > 0) {
                    nums[i] -= smallestNonZero;

                    if (nums[i] > 0) {
                        pq.offer(nums[i]);
                    } else {
                        pq.remove(nums[i]);
                    }
                }
            }

            operations++;
        }

        return operations;
    }
}

