// #Hard #Array #Math #Sorting #Heap_Priority_Queue #Number_Theory
// #2022_07_19_Time_13_ms_(88.89%)_Space_77.2_MB_(77.78%)
public class Solution {
    public int minOperations(int[] nums, int[] numsDivide) {
        Arrays.sort(nums);
        for (int i = 0; i < nums.length; i++) {
            Set<Integer> set = new HashSet<>();
            for (int j = 0; j < nums.length; j++) {
                if (j == i) continue;
                set.add(nums[j]);
            }
            boolean flag = true;
            for (int num : numsDivide) {
                if (num % nums[i] != 0) {
                    flag = false;
                    break;
                }
            }
            if (flag && set.size() < nums.length) return nums.length - set.size();
        }
        int min = Integer.MAX_VALUE;
        for (int num : numsDivide) {
            boolean found = false;
            for (int n : nums) {
                if (num % n == 0) {
                    found = true;
                    break;
                }
            }
            if (!found) return -1;
            int gcd = num;
            for (int n : nums) {
                if (n < gcd && gcd % n == 0 && canDivide(n, numsDivide)) {
                    min = Math.min(min, count(nums, n));
                } else if (gcd % n == 0 && canDivide(gcd, numsDivide)) {
                    min = Math.min(min, count(nums, gcd));
                }
            }
        }
        return min;
    }

    public boolean canDivide(int num, int[] numsDivide) {
        for (int n : numsDivide) {
            if (n % num != 0) return false;
        }
        return true;
    }

    public int count(int[] nums, int target) {
        int count = 0;
        for (int num : nums) {
            if (num == target) count++;
        }
        return count;
    }
}

