    public int minimumScore(int[] nums, int[][] edges) {
        int n = nums.length;
        ArrayList<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        int totalXor = 0;
        for (int num : nums) {
            totalXor ^= num;
        }

        boolean[] visited = new boolean[n];
        dfs(0, -1, graph, nums, visited);

        return minScore;
    }

    private void dfs(int src, int parent, ArrayList<Integer>[] graph, int[] nums, boolean[] visited) {
        int xor = 0;
        for (int nbr : graph[src]) {
            if (nbr != parent) {
                dfs(nbr, src, graph, nums, visited);
            }
        }

        for (int i = 0; i < graph.length; i++) {
            if (!visited[i] && i != src) {
                boolean[] tempVisited = new boolean[graph.length];
                int xor1 = getSubtreeXor(i, -1, graph, nums, tempVisited);
                int xor2 = totalXOROfOtherComponents(tempVisited, nums);

                minScore = Math.min(minScore, Math.abs(xor1 ^ xor2));
            }
        }

        visited[src] = true;
    }

    private int getSubtreeXor(int src, int parent, ArrayList<Integer>[] graph, int[] nums, boolean[] visited) {
        if (visited[src]) return 0;

        int xor = nums[src];
        for (int nbr : graph[src]) {
            if (!visited[nbr] && nbr != parent) {
                xor ^= getSubtreeXor(nbr, src, graph, nums, visited);
            }
        }

        return xor;
    }

    private int totalXOROfOtherComponents(boolean[] visited, int[] nums) {
        int xor = 0;
        for (int i = 0; i < visited.length; i++) {
            if (!visited[i]) {
                xor ^= nums[i];
            }
        }

        return xor;
    }
}

