        dfs(0, -1, graph, nums);

        return minScore;
    }

    private void dfs(int src, int parent, ArrayList<ArrayList<Integer>> graph, int[] nums) {
        int xor = 0;

        for (int nbr : graph.get(src)) {
            if (nbr != parent) {
                // After selecting 'src <----> nbr' as the first edge, we block 'nbr' node and then
                // make a call to try all the second edges
                dfsSecond(nbr, src, src, graph, nums);
                int xorNbr = dfs(nbr, src, graph, nums);
                // Including the neighbour subtree's XOR value in the XOR value of the subtree
                // rooted at src node
                xor ^= xorNbr;
            }
        }

        if (parent != -1) {
            xor ^= nums[src];
        }
    }

    private void dfsSecond(int src, int blocked, int parent, ArrayList<ArrayList<Integer>> graph, int[] nums) {
        int xor = 0;

        for (int nbr : graph.get(src)) {
            // If the current nbr is niether the parent of this node nor the blocked node  , then
            // only we'll proceed
            if (nbr != parent && nbr != blocked) {
                // 'src <----> nbr' is the second edge to be removed
                int xorNbr = dfs(nbr, src, graph, nums);
                // Getting the XOR value of the current neighbor
                int comp1 = xorNbr;
                // The XOR of the remaining component
                int comp2 = 0;
                for (int num : nums) {
                    comp2 ^= num;
                }
                comp2 ^= xor;
                comp2 ^= comp1;

                // Getting the minimum of the three values
                int minVal = Math.min(xor, Math.min(comp1, comp2));
                // Getting the maximum of the three value
                int maxVal = Math.max(xor, Math.max(comp1, comp2));

                // Updating the minimum score
                minScore = Math.min(minScore, maxVal - minVal);

                // Including the neighbour subtree's XOR value in the XOR value of the subtree
                // rooted at src node
                xor ^= xorNbr;
            }
        }

        if (parent != -1) {
            xor ^= nums[src];
        }
    }

    private int dfs(int src, int parent, ArrayList<ArrayList<Integer>> graph, int[] nums) {
        int xor = 0;

        for (int nbr : graph.get(src)) {
            // If the current nbr is not the parent of this node, then only we'll proceed
            if (nbr != parent) {
                int xorNbr = dfs(nbr, src, graph, nums);
                // Including the neighbour subtree's XOR value in the XOR value of the subtree
                // rooted at src node
                xor ^= xorNbr;
            }
        }

        if (parent != -1) {
            xor ^= nums[src];
        }

        return xor;
    }
}

