import java.util.*;

public class Solution {
    private int ans = Integer.MAX_VALUE;

    public int minimumScore(int[] nums, int[][] edges) {
        int n = nums.length;
        ArrayList<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        int totalXor = 0;
        for (int num : nums) {
            totalXor ^= num;
        }

        dfs(0, -1, graph, new boolean[n], nums);
        return ans;
    }

    private int dfs(int src, int parent, ArrayList<Integer>[] graph, boolean[] blocked, int[] nums) {
        int xor = 0;
        for (int nbr : graph[src]) {
            if (nbr != parent && !blocked[nbr]) {
                dfs(nbr, src, graph, blocked, nums);
                // Calculate the second edge to be removed
                for (int nextNbr : graph[nbr]) {
                    if (nextNbr != parent && nextNbr != src) {
                        int xor1 = 0;
                        int xor2 = dfsForSecondEdge(nextNbr, nbr, graph, new boolean[nums.length], nums);
                        int xor3 = totalXor ^ xor1 ^ xor2;
                        ans = Math.min(ans, Math.max(xor1, Math.max(xor2, xor3)) - Math.min(xor1, Math.min(xor2, xor3)));
                    }
                }
            }
        }

        return nums[src];
    }

    private int dfsForSecondEdge(int src, int parent, ArrayList<Integer>[] graph, boolean[] blocked, int[] nums) {
        int xor = 0;
        for (int nbr : graph[src]) {
            if (nbr != parent && !blocked[nbr]) {
                dfsForSecondEdge(nbr, src, graph, blocked, nums);
                // Including the neighbour subtree's XOR value in the XOR value of the subtree
                // rooted at src node
                xor ^= nums[nbr];
            }
        }

        return nums[src] ^ xor;
    }
}

