public class Solution {
    public String largestPalindromic(String num) {
        int[] count = new int[10];

        // Count occurrences of each digit
        for (char c : num.toCharArray()) {
            count[c - '0']++;
        }

        // Find the first digit that appears an odd number of times
        int mid = 0;
        StringBuilder sb = new StringBuilder();
        boolean hasOdd = false;

        for (int i = 9; i > 0; --i) {
            if (count[i] % 2 == 1 && !hasOdd) {
                mid = i;
                count[i]--;
                hasOdd = true;
            }
            while (count[i] >= 2) {
                sb.append(i);
                count[i] -= 2;
            }
        }

        String firstHalf = sb.toString();
        String secondHalf = sb.reverse().toString();

        // If there's a middle digit, add it to the result
        if (hasOdd) {
            return firstHalf + mid + secondHalf;
        } else {
            // Check if we have any digits in the first half
            if (!firstHalf.isEmpty()) {
                return firstHalf + secondHalf;
            }
            // If not, try to construct a single-digit palindrome
            for (int i = 9; i >= 1; --i) {
                if (count[i] > 0) {
                    return String.valueOf(i);
                }
            }
        }

        return "0";
    }
}

