// #Medium #String #Hash_Table #Greedy #2022_08_25_Time_26_ms_(100.00%)_Space_54.8_MB_(100.00%)
public class Solution {
    public String largestPalindromic(String num) {
        char[] chars = num.toCharArray();
        Arrays.sort(chars);

        int n = chars.length;
        StringBuilder firstHalf = new StringBuilder();
        boolean hasOdd = false;
        Map<Character, Integer> map = new HashMap<>();

        for (char c : chars) {
            map.put(c, map.getOrDefault(c, 0) + 1);
        }

        for (int i = n - 1; i >= 0; i--) {
            char currentChar = chars[i];
            int count = map.get(currentChar);

            if (!hasOdd && count % 2 != 0) {
                hasOdd = true;
            } else if (count % 2 == 0) {
                firstHalf.append(String.valueOf(currentChar).repeat(count / 2));
                map.put(currentChar, 0);
            }
        }

        StringBuilder result = firstHalf;
        String reversedFirstHalf = firstHalf.reverse().toString();

        if (hasOdd) {
            for (char c : map.keySet()) {
                int count = map.get(c);
                if (count % 2 != 0 && c > '0') {
                    return result.append(c).append(reversedFirstHalf).toString();
                }
            }

            // No single digit available to form a palindrome
            for (char c : map.keySet()) {
                int count = map.get(c);
                if (count % 2 != 0) {
                    return result.append('0').append(reversedFirstHalf).toString();
                }
            }
        } else {
            // If no single digit is available to form a palindrome, just append '0'
            if (firstHalf.length() == 0) {
                return "0";
            }
        }

        return firstHalf.append(reversedFirstHalf).toString();
    }
}

