        boolean[] removed = new boolean[nums.length];
        long[] sum = new long[nums.length + 1];
        for (int i = 0; i < nums.length; i++) {
            sum[i + 1] = sum[i] + nums[i];
        }
        int n = nums.length;
        long[] maxSum = new long[n];

        for (int i = n - 1; i >= 0; i--) {
