                maxCurr = nums[removeQueries[i]];
            }

            int left = removeQueries[i];
            while (left > 0 && !removed[left - 1]) {
                left--;
            }
            long sumLeft = sum[left] - sum[uf.find(left)];

            int right = removeQueries[i];
            while (right < n - 1 && !removed[right + 1]) {
                right++;
            }
            long sumRight = sum[right + 1] - sum[uf.find(right + 1)];

            maxCurr = Math.max(maxCurr, sumLeft);
            maxCurr = Math.max(maxCurr, sumRight);

            if (sumLeft > 0 && sumRight > 0) {
                uf.union(uf.find(left), removeQueries[i]);
            }
            maxSum[i] = maxCurr;
        }

        return Arrays.stream(maxSum).mapToInt(x -> (int)x).toArray();
    }
