    public int[] maxSegmentSum(int[] nums, int[] removeQueries) {
        int n = nums.length;
        UnionFind uf = new UnionFind(n + 1);
        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }

        int[] maxSums = new int[n];
        Arrays.fill(maxSums, -1);

        for (int i = removeQueries.length - 1; i >= 0; i--) {
            int index = removeQueries[i];

            // Find the left and right segments
            int leftIndex = findLeftSegment(uf, prefixSum, index);
            int rightIndex = findRightSegment(uf, prefixSum, index);

            // Update maxSums array
            updateMaxSums(maxSums, uf, prefixSum, index, leftIndex, rightIndex);

            // Remove the element at index from the UnionFind
            removeElementFromUnionFind(uf, prefixSum, index);
        }

        return maxSums;
    }

    private int findLeftSegment(UnionFind uf, int[] prefixSum, int index) {
        if (index == 0 || prefixSum[index] - prefixSum[index - 1] <= 0) {
            return -1;
        }
        int leftIndex = index - 1;
        while (leftIndex >= 0 && prefixSum[leftIndex + 1] - prefixSum[leftIndex] > 0) {
            leftIndex--;
        }
        if (leftIndex < 0 || prefixSum[index] - prefixSum[index - 1] <= 0) {
            return index;
        } else {
            return leftIndex + 1;
        }
    }

    private int findRightSegment(UnionFind uf, int[] prefixSum, int index) {
        if (index == prefixSum.length - 2 || prefixSum[index + 2] - prefixSum[index + 1] <= 0) {
            return -1;
        }
        int rightIndex = index + 1;
        while (rightIndex < prefixSum.length - 1 && prefixSum[rightIndex + 1] - prefixSum[rightIndex] > 0) {
            rightIndex++;
        }
        if (rightIndex >= prefixSum.length || prefixSum[index + 2] - prefixSum[index + 1] <= 0) {
            return index;
        } else {
            return index + 1;
        }
    }

    private void updateMaxSums(int[] maxSums, UnionFind uf, int[] prefixSum, int index, int leftIndex, int rightIndex) {
        if (leftIndex != -1 && rightIndex != -1) {
            maxSums[index] = Math.max(maxSums[index], getSegmentSum(prefixSum, leftIndex, rightIndex));
        } else if (leftIndex != -1) {
            maxSums[index] = Math.max(maxSums[index], getSegmentSum(prefixSum, leftIndex, index));
        } else if (rightIndex != -1) {
            maxSums[index] = Math.max(maxSums[index], getSegmentSum(prefixSum, index + 1, rightIndex));
        }
    }

    private void removeElementFromUnionFind(UnionFind uf, int[] prefixSum, int index) {
        // In this problem we do not need to explicitly update the UnionFind
        // We just use it as a helper data structure to find segments in constant time.
        return;
    }

    private int getSegmentSum(int[] prefixSum, int start, int end) {
        if (start > end) {
            return 0;
        }
        return prefixSum[end + 1] - prefixSum[start];
    }
}

