public class Solution {
    public int fillCups(int[] amount) {
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>((a, b) -> b - a);

        for (int num : amount) {
            if (num != 0) {
                maxHeap.offer(num);
            }
        }

        int seconds = 0;
        while (!maxHeap.isEmpty()) {
            int first = maxHeap.poll();
            if (!maxHeap.isEmpty()) {
                int second = maxHeap.poll();
                if (--first > 0) {
                    maxHeap.offer(first);
                }
                if (--second > 0) {
