import java.util.Arrays;

public class Solution {
    public int fillCups(int[] amount) {
        Arrays.sort(amount);
        int low = 0, high = Integer.MAX_VALUE;

        while (low < high) {
            int mid = low + (high - low) / 2;
            if (check(amount, mid)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    public boolean check(int[] amount, int time) {
        int cold = amount[0], warm = amount[1], hot = amount[2];

        for (int i = 0; i < time; i++) {
            if (hot > 0) {
                hot--;
            } else if (warm > 0) {
                warm--;
            } else if (cold > 0) {
                cold--;
            }

            if (i + 1 == time) break;

            int max = Math.max(Math.max(hot, warm), cold);
            if (max <= 0) return true;
            if (hot > 0 && warm > 0) {
                hot--; warm--;
            } else if (warm > 0 && cold > 0) {
                warm--; cold--;
            } else if (cold > 0 && hot > 0) {
                cold--; hot--;
            }
        }

        return cold == 0 && warm == 0 && hot == 0;
    }
}

