public class Solution {
    public int maximumGroups(int[] grades) {
        int n = grades.length;
        int sum = 0, count = 0;
        for (int grade : grades) {
            sum += grade;
            count++;
        }

        int left = 1, right = n;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (check(mid, grades)) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return right;
    }

    private boolean check(int k, int[] grades) {
        long sum = 0;
        for (int grade : grades) {
            sum += grade;
        }

        if ((k * (k + 1)) / 2 > sum) {
            return false;
        }

        long currentSum = 0;
        int count = 1, index = 0;
        while (index < grades.length && k > 0) {
            currentSum += grades[index++];
            if (currentSum * k <= sum && count * k <= index) {
                k--;
                count++;
                currentSum = 0;
            }
        }

        return index == grades.length;
    }
}

