import java.util.HashMap;
import java.util.Map;

public class Solution {
    public String decodeMessage(String key, String message) {
        StringBuilder result = new StringBuilder();
        Map<Character, Character> substitutionTable = new HashMap<>();

        char[] uniqueChars = getUniqueChars(key);

        // Create a substitution table by mapping the first occurrence of each character in 'key' to its corresponding alphabetical index
        for (int i = 0; i < 26; ++i) {
            substitutionTable.put(uniqueChars[i], (char)(97 + i)); // 'a' has ASCII value of 97
        }

        // Apply the substitution table to decode the 'message'
        for (int i = 0; i < message.length(); ++i) {
            char c = message.charAt(i);

            if (c == ' ') {
                result.append(' ');
            } else {
                result.append(substitutionTable.get(c));
            }
        }

        return result.toString();
    }

    private char[] getUniqueChars(String key) {
        boolean[] seen = new boolean[26];
        char[] uniqueChars = new char[26];
        int count = 0;

        for (char c : key.toCharArray()) {
            if (!Character.isWhitespace(c)) {
                int index = c - 'a';

                if (!seen[index]) {
                    seen[index] = true;
                    uniqueChars[count++] = c;
                }
            }
        }

        // If there are still missing characters in the alphabet, add them to the end of the substitution table
        for (int i = 0; i < 26 && count < 26; ++i) {
            if (!seen[i]) {
                uniqueChars[count++] = (char)(97 + i); // 'a' has ASCII value of 97
