public class Solution {
    public int longestCycle(int[] edges) {
        int n = edges.length;
        boolean[] visited = new boolean[n];
        int maxCycleLength = -1;

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                int[] distance = new int[n + 1];
                int current = i, step = 0;

                while (current != -1 && !visited[current]) {
                    visited[current] = true;
                    distance[step] = current;
                    step++;

                    if (edges[current] == -1) break;
                    else if (distance[step - 2] == edges[current]) maxCycleLength = Math.max(maxCycleLength, step - getDistanceIndex(distance, edges[current]));

                    current = edges[current];
                }
            }
        }

        return maxCycleLength;
    }

    private int getDistanceIndex(int[] distance, int target) {
        for (int i = 0; i < distance.length; i++) {
            if (distance[i] == target) return i;
        }

        return -1;
    }
}

