public class Solution {
    public int longestCycle(int[] edges) {
        boolean[] visited = new boolean[edges.length];
        int maxCycleLength = -1;

        for (int i = 0; i < edges.length; i++) {
            if (!visited[i]) {
                maxCycleLength = Math.max(maxCycleLength, dfs(edges, visited, i, i, 0));
            }
        }

        return maxCycleLength;
    }

    private int dfs(int[] edges, boolean[] visited, int node, int startNode, int distance) {
        if (node == -1 || visited[node]) {
            if (node == startNode && distance > 0) {
                return distance;
            } else {
                return -1;
            }
        }

        visited[node] = true;

        int nextDistance = dfs(edges, visited, edges[node], startNode, distance + 1);

        visited[node] = false;

        return nextDistance;
    }
}

