import java.util.HashMap;

public class Solution {
    public String bestHand(int[] ranks, char[] suits) {
        boolean isFlush = true;
        HashMap<Character, Integer> suitMap = new HashMap<>();

        // Check for flush
        for (int i = 0; i < suits.length; i++) {
            if (!suitMap.containsKey(suits[i])) {
                suitMap.put(suits[i], 1);
            } else {
                int count = suitMap.get(suits[i]);
                suitMap.put(suits[i], ++count);
            }
            if (i > 0 && suits[i] != suits[i - 1]) {
                isFlush = false;
            }
        }

        // Check for three of a kind or pair
        HashMap<Integer, Integer> rankMap = new HashMap<>();
        boolean hasThreeOfAKind = false;
        boolean hasPair = false;
        for (int i = 0; i < ranks.length; i++) {
            if (!rankMap.containsKey(ranks[i])) {
                rankMap.put(ranks[i], 1);
            } else {
                int count = rankMap.get(ranks[i]);
                rankMap.put(ranks[i], ++count);
                if (count == 3) {
                    hasThreeOfAKind = true;
                } else if (count == 2 && !hasThreeOfAKind) {
                    hasPair = true;
                }
            }
        }

        // Determine the best hand
        if (isFlush) {
            return "Flush";
        } else if (hasThreeOfAKind) {
            return "Three of a Kind";
        } else if (hasPair) {
            return "Pair";
        } else {
            return "High Card";
        }
    }
}

