public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> Integer.compare(b, a));

        for (int i = 0; i < nums1.length; i++) {
            int diff = Math.abs(nums1[i] - nums2[i]);
            if (diff > 0) {
                pq.offer(diff);
            }
        }

        long kSum = k1 + k2;
        while (!pq.isEmpty() && kSum > 0) {
            int currDiff = pq.poll();
            int valToReduce = Math.min(kSum, currDiff);
            kSum -= valToReduce;
            if (currDiff - valToReduce > 0) {
                pq.offer(currDiff - valToReduce);
            }
        }

        long res = 0;
        while (!pq.isEmpty()) {
            int diff = pq.poll();
            res += (long)diff * diff;
        }
        return res;
    }
}

