public class Solution {
    public int maximumRows(int[][] matrix, int numSelect) {
        int m = matrix.length;
        int n = matrix[0].length;

        // Generate all possible subsets of columns
        List<List<Integer>> subsets = new ArrayList<>();
        backtrack(subsets, new ArrayList<>(), 0, n, numSelect);

        int maxCoveredRows = 0;

        for (List<Integer> subset : subsets) {
            Set<Integer> selectedColumns = new HashSet<>(subset);
            int coveredRows = 0;

            // Check each row to see if it's covered by the current subset
            for (int[] row : matrix) {
                boolean isCovered = true;

                for (int j = 0; j < n; j++) {
                    if (row[j] == 1 && !selectedColumns.contains(j)) {
                        isCovered = false;
                        break;
                    }
                }

                if (isCovered) {
                    coveredRows++;
                }
            }

            maxCoveredRows = Math.max(maxCoveredRows, coveredRows);
        }

        return maxCoveredRows;
    }

    private void backtrack(List<List<Integer>> subsets, List<Integer> currentSubset, int start, int n, int numSelect) {
        if (currentSubset.size() == numSelect) {
            subsets.add(new ArrayList<>(currentSubset));
            return;
        }

        for (int i = start; i < n; i++) {
            currentSubset.add(i);
            backtrack(subsets, currentSubset, i + 1, n, numSelect);
            currentSubset.remove(currentSubset.size() - 1);
        }
    }
}

