                // Calculate the maximum profit by cutting horizontally
                for (int k = 1; k < i; k++) {
                    dp[i][j] = Math.max(dp[i][j], dp[k][j] + dp[i - k][j]);
                }
            }
        }

        return dp[m][n];
    }
}

