        long maxProfit = 0;
        for (int[] price : prices) {
            if (price[0] == x && price[1] == y) {
                maxProfit = Math.max(maxProfit, price[2]);
            }
        }

        // Cut Vertically
        for (int i = 1; i < x; i++) {
            long left = dfs(i, y, prices, dp);
            long right = dfs(x - i, y, prices, dp);
            maxProfit = Math.max(maxProfit, left + right);
        }

        // Cut Horizontally
        for (int j = 1; j < y; j++) {
            long up = dfs(x, j, prices, dp);
            long down = dfs(x, y - j, prices, dp);
            maxProfit = Math.max(maxProfit, up + down);
        }

        // Store the maximum profit in the map
        dp.put(key, maxProfit);

        return maxProfit;
    }
}

