public class Solution {
    public int maximumXOR(int[] nums) {
        Trie trie = new Trie();
        for (int num : nums) {
            addNum(trie, num);
        }

        int max = 0;
        for (int num : nums) {
            max = Math.max(max, findMaxXor(trie, num));
        }

        return max;
    }

    private void addNum(Trie trie, int num) {
        Trie node = trie;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if (node.children[bit] == null) {
                node.children[bit] = new Trie();
            }
            node = node.children[bit];
        }
    }

    private int findMaxXor(Trie trie, int num) {
        Trie node = trie;
        int xor = 0;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if (node.children[1 - bit] != null) {
                xor |= (1 << i);
                node = node.children[1 - bit];
            } else {
                node = node.children[bit];
            }
        }
        return xor;
    }

    private static class Trie {
        Trie[] children;

        public Trie() {
            this.children = new Trie[2];
        }
    }
}

