public class Solution {
    // Using topological sort to solve this problem
    public int[][] buildMatrix(int k, int[][] rowC, int[][] colC) {
        Map<Integer, List<Integer>> graph = new HashMap<>();
        int[] indegreeRow = new int[k + 1];
        int[] indegreeCol = new int[k + 1];

        for (int[] rc : rowC) {
            if (!graph.containsKey(rc[0])) {
                graph.put(rc[0], new ArrayList<>());
            }
            graph.get(rc[0]).add(rc[1]);
            indegreeRow[rc[1]]++;
        }

        for (int[] cc : colC) {
            if (!graph.containsKey(cc[0])) {
                graph.put(cc[0], new ArrayList<>());
            }
            graph.get(cc[0]).add(cc[1]);
            indegreeCol[cc[1]]++;
        }

        if (hasCycle(indegreeRow, k) || hasCycle(indegreeCol, k)) {
            return new int[][] {};
        }

        List<Integer>[] topologicalSort = topologicalSort(graph, indegreeRow);
        int[][] result = new int[k][k];

        for (int i = 0; i < k; i++) {
            for (int j = 0; j < k; j++) {
                if (topologicalSort[i] != null) {
                    result[i][j] = topologicalSort[i].get(j);
                } else {
                    result[i][j] = -1;
                }
            }
        }

        return result;
    }

    private boolean hasCycle(int[] indegree, int k) {
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 1; i <= k; i++) {
            if (indegree[i] == 0) {
                queue.add(i);
            }
        }

        while (!queue.isEmpty()) {
            int current = queue.poll();
            indegree[current]--;
            for (Map.Entry<Integer, List<Integer>> entry : graph.entrySet()) {
                List<Integer> neighbors = entry.getValue();
                if (neighbors.contains(current)) {
                    indegree[current]--;
                    if (indegree[current] == 0) {
                        queue.add(entry.getKey());
                    }
                }
            }
        }

        for (int i = 1; i <= k; i++) {
            if (indegree[i] > 0) {
                return true;
            }
        }

        return false;
    }

    private List<Integer>[] topologicalSort(Map<Integer, List<Integer>> graph, int[] indegree) {
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 1; i < indegree.length; i++) {
            if (indegree[i] == 0) {
                queue.add(i);
            }
        }

        List<Integer>[] result = new ArrayList[indegree.length];
        int row = 0;
        while (!queue.isEmpty()) {
            Queue<Integer> tempQueue = new LinkedList<>();
            for (int current : queue) {
                if (result[row] == null) {
                    result[row] = new ArrayList<>();
                }
                result[row].add(current);
                for (Map.Entry<Integer, List<Integer>> entry : graph.entrySet()) {
                    List<Integer> neighbors = entry.getValue();
                    if (neighbors.contains(current)) {
                        indegree[current]--;
                        tempQueue.add(entry.getKey());
                    }
                }
            }
            row++;
            queue = new LinkedList<>(tempQueue);
        }

        return result;
    }

    private Map<Integer, List<Integer>> graph = new HashMap<>();
}

