            int below = condition[1];
            graph[above].add(below);
            indegreeRow[below]++;
        }

        // Build the column graph and update the indegree array
        Map<Integer, List<Integer>> colMap = new HashMap<>();
        for (int[] condition : colC) {
            int left = condition[0];
            int right = condition[1];
            if (!colMap.containsKey(left)) {
                colMap.put(left, new ArrayList<>());
            }
            colMap.get(left).add(right);
            indegreeCol[right]++;
        }

        // Check for conflicts between row and column conditions
        Queue<Integer> queueRow = new LinkedList<>();
        Queue<Integer> queueCol = new LinkedList<>();

        // Add nodes with indegree 0 to the queues
        for (int i = 1; i <= k; i++) {
            if (indegreeRow[i] == 0) {
                queueRow.add(i);
            }
            if (indegreeCol[i] == 0) {
                queueCol.add(i);
            }
        }

        // Perform topological sort on the row graph
        List<Integer> order = new ArrayList<>();
        while (!queueRow.isEmpty()) {
            int node = queueRow.poll();
            order.add(node);
            for (int neighbor : graph[node]) {
                indegreeRow[neighbor]--;
                if (indegreeRow[neighbor] == 0) {
                    queueRow.add(neighbor);
                }
            }
        }

        // Check if there's a cycle in the row graph
        if (order.size() != k) {
            return new int[][] {};
        }

        // Build the column order based on the row order and column conditions
        List<Integer> colOrder = new ArrayList<>();
        for (int node : order) {
            if (colMap.containsKey(node)) {
                for (int neighbor : colMap.get(node)) {
                    indegreeCol[neighbor]--;
                    if (indegreeCol[neighbor] == 0) {
                        queueCol.add(neighbor);
                    }
                }
            }
            colOrder.add(node);
        }

        // Check if there's a cycle in the column graph
        while (!queueCol.isEmpty()) {
            int node = queueCol.poll();
            colOrder.remove((Integer) node);
            for (int i = 0; i < colC.length; i++) {
                if (colC[i][1] == node) {
                    indegreeCol[colC[i][0]]--;
                    if (indegreeCol[colC[i][0]] == 0) {
                        queueCol.add(colC[i][0]);
                    }
                }
            }
        }

        // Check if the column order is valid
        if (!colOrder.isEmpty()) {
            return new int[][] {};
        }

        // Build the matrix based on the row and column orders
        int[][] matrix = new int[k][k];
        for (int i = 0; i < k; i++) {
            matrix[i][order.indexOf(i + 1)] = i + 1;
        }

        return matrix;
    }
