        for (int i = 1; i <= pattern.length() + 1; i++) {
            res.append(i);
        }

        return backtrack(res, 0, pattern, new boolean[10]);
    }

    private String backtrack(StringBuilder sb, int index, String pattern, boolean[] visited) {
        if (index == pattern.length()) {
            return sb.toString();
        }

        for (int i = 1; i <= 9; i++) {
            if (visited[i]) {
                continue;
            }

            visited[i] = true;

            StringBuilder temp = new StringBuilder(sb);
            int len = temp.length();

            if (index > 0) {
                char c = pattern.charAt(index - 1);

                if ((c == 'I' && temp.charAt(len - 2) >= ('0' + i)) || 
                    (c == 'D' && temp.charAt(len - 2) <= ('0' + i))) {
                    continue;
                }
            }

            temp.append((char)('0' + i));
            String result = backtrack(temp, index + 1, pattern, visited);
            if (result != null) {
                return result;
            }

            visited[i] = false;

        }

        return null;
    }
}

