                    (pattern.charAt(idx - 1) == 'D' && num[idx - 1] > i)) {
                    used[i] = true;
                    num[idx] = i;

                    if (dfs(idx + 1, sb, num, used, pattern)) {
                        return true;
                    }

                    used[i] = false;
                }
            }
        }

        return false;
    }
}

