public class Solution {
    public String smallestNumber(String pattern) {
        StringBuilder result = new StringBuilder();
        int index = 0;

        for (char c : pattern.toCharArray()) {
            if (c == 'I') {
                // find the next unused number that is greater than the previous one
                while (result.length() > index && Character.isDigit(result.charAt(index))) {
                    index++;
                }
                int num = (index == 0) ? 1 : result.charAt(index - 1) + 1;
                for (char i = '1'; i <= '9'; i++) {
                    if (!result.toString().contains(String.valueOf(i)) && i >= num) {
                        result.insert(index, i);
                        break;
                    }
                }
            } else if (c == 'D') {
                // find the next unused number that is smaller than the previous one
                while (result.length() > index && Character.isDigit(result.charAt(index))) {
                    index++;
                }
                int num = (index == 0) ? 9 : result.charAt(index - 1) - 1;
                for (char i = '9'; i >= '1'; i--) {
                    if (!result.toString().contains(String.valueOf(i)) && i <= num) {
                        result.insert(index, i);
                        break;
                    }
                }
            }
        }

        // append the last number
        int lastNum = 1;
        while (lastNum < 10) {
            boolean found = false;
            for (int i = 0; i < result.length(); i++) {
                if (result.charAt(i) == lastNum + '0') {
                    found = true;
                    break;
                }
            }
            if (!found) {
                result.append((char)(lastNum + '0'));
                break;
            }
            lastNum++;
        }

        return result.toString();
    }
