public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int countHousePlacements(int n) {
        long[] ways = new long[n + 1];

        // base cases: if there's one plot, we can place or not place a house
        ways[0] = 1; 
        ways[1] = 2; 

        // for two plots, we cannot place houses on both, so the number of ways is 3 (00, 01, 10)
        if(n >= 2) {
            ways[2] = 3;
        }

        // calculate the ways to place houses for each plot
        for(int i = 3; i <= n; i++) {
            // we can either place a house on this plot (in which case the previous one must be empty)
            // or not place a house on this plot (in which case the previous one can be either empty or occupied)
            ways[i] = (ways[i - 1] + ways[i - 2]) % MOD;
        }

        // since there are two sides of the street, we need to square the result
        return (int) ((ways[n] * ways[n]) % MOD);
    }
}

