import java.util.*;

public class Solution {
    public int reachableNodes(int n, int[][] edges, int[] restricted) {
        // Create adjacency list
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }

        // Populate the adjacency list
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        // Create a set of restricted nodes for efficient lookup
        Set<Integer> restrictedSet = new HashSet<>();
        for (int node : restricted) {
            restrictedSet.add(node);
        }

        // Perform DFS to count reachable nodes
        boolean[] visited = new boolean[n];
        dfs(0, adj, restrictedSet, visited);

        // Count the number of reachable nodes
        int count = 0;
        for (boolean b : visited) {
            if (b) count++;
        }

        return count;
    }

    private void dfs(int node, List<List<Integer>> adj, Set<Integer> restrictedSet, boolean[] visited) {
        // If the current node is restricted or already visited, return
        if (restrictedSet.contains(node) || visited[node]) return;

        // Mark the current node as visited
        visited[node] = true;

        // Recursively visit all adjacent nodes that are not restricted
        for (int neighbor : adj.get(node)) {
            dfs(neighbor, adj, restrictedSet, visited);
        }
    }
}

