public class Solution {
    public int longestSubsequence(String s, int k) {
        char[] binary = Integer.toBinaryString(k).toCharArray();
        int n = s.length(), m = binary.length;
        boolean[][] dp = new boolean[n + 1][m + 1];

        for (int i = 0; i <= n; i++) {
            dp[i][0] = true;
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                dp[i][j] = dp[i - 1][j];
                if (s.charAt(i - 1) == '0') {
                    dp[i][j] |= dp[i - 1][j];
                } else if (s.charAt(i - 1) == '1' && j > 0 && binary[m - j] == '1') {
                    dp[i][j] |= dp[i - 1][j - 1];
                }
            }
        }

        for (int i = m; i >= 0; i--) {
            if (dp[n][i]) return i;
        }

        return 0;
    }
}

