public class Solution {
    public int longestSubsequence(String s, int k) {
        char[] chars = s.toCharArray();
        int n = chars.length;
        long num = 0;

        for (int i = n - 1; i >= 0 && num <= k; --i) {
            if (chars[i] == '0') {
                num = num * 2;
            } else {
                num = num * 2 + 1;
            }

            if (num > k) break;
        }

        int countZero = 0, countOne = 0;
        for (char c : chars) {
            if (c == '0') ++countZero;
            else ++countOne;
        }

        if (num <= k) return n;
        long pow2 = 1;
        while (pow2 * 2 <= k && num > k) {
            --countOne;
            num -= pow2;
            pow2 *= 2;
        }

        int ans = countZero + Math.max(0, countOne);
        if (num > k) return n - 1;
        else return ans;
    }
}

