public class Solution {
    public int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);

        int busIndex = 0;
        int passengerIndex = 0;
        for (int i = 0; i < buses.length - 1; i++) {
            while (passengerIndex < passengers.length && passengers[passengerIndex] <= buses[i]) {
                if ((passengerIndex - busIndex * capacity) < capacity) {
                    passengerIndex++;
                } else {
                    break;
                }
            }
            busIndex++;
        }

        int lastBus = buses[buses.length - 1];
        while (passengerIndex < passengers.length && passengers[passengerIndex] <= lastBus) {
            if ((passengerIndex - busIndex * capacity) < capacity) {
                passengerIndex++;
            } else {
                break;
            }
        }

        int result = lastBus;

        // Check if the last bus is full
        if (passengerIndex - busIndex * capacity == capacity) {
            // Find the time when the last passenger boarded
            while (passengerIndex > 0 && passengers[passengerIndex - 1] == passengers[passengerIndex]) {
                passengerIndex--;
            }
            result = passengers[passengerIndex - 1] - 1;
        } else {
            // Check if we can board on the last moment
            while (passengerIndex > 0 && passengers[passengerIndex - 1] == lastBus) {
                passengerIndex--;
            }
            if (passengers.length > 0 && passengers[passengerIndex] < lastBus) {
                result = passengers[passengerIndex];
            } else {
                // Find the available time slot
                for (int i = buses.length - 2; i >= 0; i--) {
                    int currentBus = buses[i];
                    while (passengerIndex > 0 && passengers[passengerIndex - 1] == currentBus) {
                        passengerIndex--;
                    }
                    if ((passengerIndex - i * capacity) < capacity) {
                        result = currentBus;
                        break;
                    } else if (i > 0 && buses[i - 1] + 1 <= currentBus) {
                        result = currentBus - 1;
                        break;
                    }
                }
            }
        }

        return result;
    }
}

