public class Solution {
    public int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);

        int i = 0; // index for buses
        int j = 0; // index for passengers

        while (i < buses.length && j < passengers.length) {
            int count = 0;
            while (j < passengers.length && passengers[j] <= buses[i]) {
                if (count < capacity) {
                    count++;
                }
                j++;
            }
            i++;
        }

        // check the last bus
        if (i > 0) {
            if (buses[i - 1] == passengers[passengers.length - 1]) {
                return passengers[passengers.length - 1];
            } else if (j < passengers.length && buses[i - 1] >= passengers[j]) {
                int lastBusTime = buses[buses.length - 1];
                while (j > 0 && passengers[j - 1] == passengers[j] - 1) {
                    j--;
                }
                return Math.min(lastBusTime, passengers[j - 1] - 1);
            } else if (buses[i - 1] - passengers[passengers.length - 1] < capacity) {
                int lastPassengerIndex = 0;
                for (int k = passengers.length - 1; k >= 0 && passengers[k] == passengers[passengers.length - 1]; k--) {
                    if (++lastPassengerIndex == capacity) break;
                }
                return passengers[lastPassengerIndex + passengers.length - 1] - 1;
            } else {
                return buses[i - 1];
            }
        }

        // no bus
        return Integer.MIN_VALUE;
    }
}

