            while (cap > 0 && passengerIdx >= 0 && passengers[passengerIdx] <= buses[i]) {
                cap--;
                passengerIdx--;
            }
            if (cap > 0) {
                return Math.max(buses[i], passengerIdx + 1 == 0 ? Integer.MAX_VALUE : passengers[passengerIdx + 1] - 1);
            } else if (i == 0 || buses[i] != passengers[passengerIdx + 1]) {
                return passengers[passengerIdx + 1];
            }
        }

        return 0;
    }
