// #Medium #Depth_First_Search #Breadth_First_Search #Tree #Binary_Tree
// #2022_11_15_Time_12_ms_(64.14%)_Space_49.7_MB_(87.20%)
import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Solution {
    public TreeNode reverseOddLevels(TreeNode root) {
        if (root == null) return null;

        Queue<TreeNode> queue = new LinkedList<>();
        queue.add(root);
        int level = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            List<Integer> values = new ArrayList<>();

            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();
                values.add(node.val);

                if (node.left != null) {
                    queue.add(node.left);
                }
                if (node.right != null) {
                    queue.add(node.right);
                }
            }

            if ((level + 1) % 2 == 0) {
                int left = 0;
                int right = values.size() - 1;

                while (left < right) {
                    // Swap the node values
                    TreeNode tempLeftNode = findNode(root, level + 1, left);
                    TreeNode tempRightNode = findNode(root, level + 1, right);

                    int tempValue = tempLeftNode.val;
                    tempLeftNode.val = tempRightNode.val;
                    tempRightNode.val = tempValue;

                    left++;
                    right--;
                }
            }

            level++;
        }

        return root;
    }

    public TreeNode findNode(TreeNode root, int level, int index) {
        if (root == null || level < 0) return null;

        if (level == 0) return root;

        int nodesAtLevel = (int) Math.pow(2, level);
        int leftChildIndex = index * 2 + 1 - nodesAtLevel;

        TreeNode node = findNode(root.left, level - 1, leftChildIndex / 2);

        if (node == null) {
            node = findNode(root.right, level - 1, leftChildIndex / 2);
        }

        return node;
    }
}

