/**
 * This public class Solution a method that checks whether a sentence is circular or not.
 * A sentence is considered circular if the last character of each word matches 
 * the first character of the next word, and the last character of the last word 
 * matches the first character of the first word.
 */
public class Solution {
    /**
     * Checks whether a given sentence is circular or not.
     * @param sentence The input sentence to check for circularity.
     * @return True if the sentence is circular, false otherwise.
     */
    public boolean isCircularSentence(String sentence) {
        String[] words = sentence.split(" ");

        // Check each word against the next one
        for (int i = 0; i < words.length - 1; i++) {
            if (words[i].charAt(words[i].length() - 1) != words[i + 1].charAt(0)) {
                return false;
            }
        }

        // Check last word against the first one
        if (words[words.length - 1].charAt(words[words.length - 1].length() - 1) 
                != words[0].charAt(0)) {
            return false;
        }

        return true;
    }
}

