import com_github_leetcode.TreeNode;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int[] treeQueries(TreeNode root, int[] queries) {
        Map<Integer, TreeNode> parent = new HashMap<>();
        dfs(root, null, parent);

        int n = queries.length;
        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            int queryNodeVal = queries[i];
            TreeNode queryNode = findNodeByVal(root, queryNodeVal);
            if (queryNode == null) continue;

            TreeNode currentNode = root;
            int maxDepth = 0;
            while (currentNode != null && !isDescendant(currentNode, queryNode)) {
                maxDepth++;
                currentNode = parent.get(currentNode.val);
            }
            result[i] = Math.max(maxDepth, getHeight(root) - getDepth(queryNode));
        }

        return result;
    }

    private void dfs(TreeNode node, TreeNode parentNode, Map<Integer, TreeNode> parent) {
        if (node == null) return;
        parent.put(node.val, parentNode);
        dfs(node.left, node, parent);
        dfs(node.right, node, parent);
    }

    private TreeNode findNodeByVal(TreeNode root, int val) {
        if (root == null || root.val == val) return root;
        TreeNode left = findNodeByVal(root.left, val);
        if (left != null) return left;
        return findNodeByVal(root.right, val);
    }

    private boolean isDescendant(TreeNode ancestor, TreeNode descendant) {
        while (descendant != null) {
            if (descendant == ancestor) return true;
            descendant = parent.get(descendant.val);
        }
        return false;
    }

    private int getHeight(TreeNode root) {
        if (root == null) return 0;
        return Math.max(getHeight(root.left), getHeight(root.right)) + 1;
    }

    private int getDepth(TreeNode node) {
        if (node == null) return 0;
        return getDepth(parent.get(node.val)) + 1;
    }
}

