import com_github_leetcode.TreeNode;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int[] treeQueries(TreeNode root, int[] queries) {
        Map<TreeNode, Integer> heightMap = new HashMap<>();
        dfs(root, 0, heightMap);

        int n = queries.length;
        int[] answer = new int[n];

        for (int i = 0; i < n; i++) {
            TreeNode node = findNode(root, queries[i]);
            heightMap.remove(node);

            Map<TreeNode, Integer> tempHeightMap = new HashMap<>();
            dfs(root, 0, tempHeightMap);
            answer[i] = getMaxValue(tempHeightMap.values());
        }

        return answer;
    }

    private void dfs(TreeNode node, int height, Map<TreeNode, Integer> heightMap) {
        if (node == null) return;

        heightMap.put(node, height);
        dfs(node.left, height + 1, heightMap);
        dfs(node.right, height + 1, heightMap);
    }

    private TreeNode findNode(TreeNode node, int value) {
        if (node == null) return null;

        if (node.val == value) return node;

        TreeNode leftResult = findNode(node.left, value);
        if (leftResult != null) return leftResult;

        return findNode(node.right, value);
    }

    private int getMaxValue(java.util.Collection<Integer> values) {
        int max = 0;
        for (Integer value : values) {
            if (value > max) max = value;
        }
        return max;
    }
}

