            TreeNode newRoot = removeSubtree(root, removedNode, parentMap);
            result[i] = getHeight(newRoot);
        }

        return result;
    }

    private void dfs(TreeNode node, TreeNode parent, Map<TreeNode, TreeNode> parentMap) {
        if (node == null) return;
        parentMap.put(node, parent);
        dfs(node.left, node, parentMap);
        dfs(node.right, node, parentMap);
    }

    private TreeNode findNodeByValue(TreeNode root, int value, Map<TreeNode, TreeNode> parentMap) {
        if (root == null || root.val == value) return root;
        TreeNode leftResult = findNodeByValue(root.left, value, parentMap);
        if (leftResult != null) return leftResult;
        return findNodeByValue(root.right, value, parentMap);
    }

    private TreeNode removeSubtree(TreeNode root, TreeNode removedNode, Map<TreeNode, TreeNode> parentMap) {
        if (root == null || removedNode == null) return root;
        TreeNode parent = parentMap.get(removedNode);
        if (parent.left == removedNode) {
            parent.left = null;
        } else {
            parent.right = null;
        }
        return removeSubtree(parent, parent, parentMap);
    }

    private int getHeight(TreeNode node) {
        if (node == null) return 0;
        return Math.max(getHeight(node.left), getHeight(node.right)) + 1;
    }
