public class Solution {
    public String oddString(String[] words) {
        int n = words.length;
        if (n == 1) return words[0];

        // Get the difference array for the first word
        int[] diff0 = getDifferenceArray(words[0]);

        // Count occurrences of each difference array
        int count0 = 0, count1 = 0;
        String odd = "";
        for (String word : words) {
            int[] diff = getDifferenceArray(word);
            if (isSame(diff, diff0)) {
                count0++;
            } else {
                odd = word;
                count1++;
            }
        }

        // If the first difference array occurs less than two times, return the string with this difference array
        if (count0 < 2) return words[0];

        // Otherwise, return the string that has a different difference array
        return odd;
    }

    private int[] getDifferenceArray(String word) {
        int n = word.length();
        int[] diff = new int[n - 1];
        for (int i = 0; i < n - 1; i++) {
            diff[i] = word.charAt(i + 1) - word.charAt(i);
        }
        return diff;
    }

    private boolean isSame(int[] arr1, int[] arr2) {
        if (arr1.length != arr2.length) return false;

        for (int i = 0; i < arr1.length; i++) {
            if (arr1[i] != arr2[i]) return false;
        }

        return true;
    }
}

