import java.util.List;

public class Solution {
    public long minimumTotalDistance(List<Integer> robot, int[][] f) {
        // Convert List to array for easier manipulation
        Integer[] robotArray = robot.toArray(new Integer[0]);

        // Sort factories by x-position in asc order
        Arrays.sort(f, (a, b) -> a[0] - b[0]);

        // Sort robots by x-position in asc order
        Arrays.sort(robotArray);

        int m = f.length;
        long[][] dp = new long[m + 1][robot.size() + 1];

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= robot.size(); j++) {
                // Cost of adding current robot to the current factory
                long cost = Math.abs(robotArray[j - 1] - f[i - 1][0]);

                if (j <= f[i - 1][1]) {
                    dp[i][j] = dp[i][j - 1] + cost;
                } else {
                    // If the current factory is full, calculate the cost of moving the rightmost robot in the
                    // factory to the next one and add it to the current cost.
                    long minCost = Long.MAX_VALUE;

                    for (int k = i - 1; k >= 0; k--) {
                        if (f[k][1] > 0) {
                            long newCost = dp[k][j - f[i - 1][1]] + Math.abs(robotArray[j - 1] - f[i - 1][0]);
                            minCost = Math.min(minCost, newCost);
                        }
                    }

                    dp[i][j] = Math.min(dp[i - 1][j], minCost);
                }
            }
        }

        // The minimum total distance is stored in dp[m][n]
        return dp[m][robot.size()];
    }
}

