import java.util.Arrays;
import java.util.List;

public class Solution {
    public long minimumTotalDistance(List<Integer> robot, int[][] f) {
        // convert list to array
        Integer[] robots = robot.toArray(new Integer[0]);
        Arrays.sort(robots);

        // sort factories by x-position in asc order
        Arrays.sort(f, (a, b) -> a[0] - b[0]);

        long totalDistance = 0;
        int[] assignedRobots = new int[f.length];

        for (int i = robots.length - 1; i >= 0; --i) {
            int minDistance = Integer.MAX_VALUE;
            int minIndex = -1;

            for (int j = 0; j < f.length; ++j) {
                // calculate distance from current robot to the factory
                long distance = Math.abs(robots[i] - f[j][0]);

                if (assignedRobots[j] < f[j][1]) {
                    // if current factory is not full, assign robot and update distance
                    assignedRobots[j]++;
                    totalDistance += distance;
                    break;
                } else {
                    // if current factory is full, try to move rightmost robot in the factory to the next one
                    long newDistance = calculateNewDistance(robots[i], f, j, assignedRobots);
                    if (newDistance < minDistance) {
                        minDistance = newDistance;
                        minIndex = j;
                    }
                }
            }

            // assign current robot to the previous factory and move any non-fit robots to the right
            if (minIndex != -1) {
                totalDistance += minDistance;
                assignedRobots[minIndex]++;
            }
        }

        return totalDistance;
    }

    private long calculateNewDistance(int robot, int[][] f, int index, int[] assignedRobots) {
        long newDistance = Math.abs(robot - f[index][0]);
        // move rightmost robot in the factory to the next one
        if (index + 1 < f.length && assignedRobots[index + 1] < f[index + 1][1]) {
            newDistance += Math.abs(f[index][0] - f[index + 1][0]);
            assignedRobots[index]--;
            assignedRobots[index + 1]++;
        }
        return newDistance;
    }
}

