        for (int[] interval : intervals) {
            if (!pq.isEmpty() && pq.peek() <= interval[0]) {
                // If the current interval does not intersect with any of the previous intervals, 
                // remove the end time of the previous interval from the priority queue
                pq.poll();
            }
            // Add the end time of the current interval to the priority queue
