import java.util.HashMap;

public class Solution {
    public int deleteString(String s) {
        int n = s.length();
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            dp[i][i] = 1;
        }

        for (int length = 2; length <= n; length++) {
            for (int start = 0; start <= n - length; start++) {
                int end = start + length - 1;

                if (length == 2 && s.charAt(start) == s.charAt(end)) {
                    dp[start][end] = 2;
                } else if (s.substring(start, start + length / 2).equals(s.substring(start + length / 2, end + 1))) {
                    int max = 0;

                    for (int k = start; k <= end - length / 2; k++) {
                        if (dp[k][end] > max) {
                            max = dp[k][end];
                        }
                    }

                    dp[start][end] = max + 1;
                } else {
                    int max = 0;

                    for (int k = start; k < end; k++) {
                        if (dp[start][k] + dp[k + 1][end] > max) {
                            max = dp[start][k] + dp[k + 1][end];
                        }
                    }

                    dp[start][end] = max;
                }
            }
        }

        return dp[0][n - 1];
    }
}

