import java.util.HashMap;

public class Solution {
    public int deleteString(String s) {
        int n = s.length();
        HashMap<String, Integer> memo = new HashMap<>();

        return dp(s, 0, memo);
    }

    private int dp(String s, int start, HashMap<String, Integer> memo) {
        if (start == s.length()) {
            return 0;
        }

        String key = start + "," + s.substring(start);
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        int maxOps = 1;
        for (int i = 1; i <= (s.length() - start) / 2; i++) {
            if (s.startsWith(s.substring(start, start + i), start + i)) {
                maxOps = Math.max(maxOps, 1 + dp(s, start + i, memo));
            }
        }

        memo.put(key, maxOps);
        return maxOps;
    }
}

