import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int[][] closestNodes(TreeNode root, int[] queries) {
        List<Integer> values = new ArrayList<>();
        inorder(root, values);

        int n = queries.length;
        int[][] answer = new int[n][2];

        for (int i = 0; i < n; i++) {
            int min = -1, max = -1;

            // Find the largest value in the tree that is smaller than or equal to queries[i]
            int left = 0, right = values.size() - 1;
            while (left <= right) {
                int mid = left + (right - left) / 2;
                if (values.get(mid) <= queries[i]) {
                    min = values.get(mid);
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }

            // Find the smallest value in the tree that is greater than or equal to queries[i]
            left = 0; 
            right = values.size() - 1;
            while (left <= right) {
                int mid = left + (right - left) / 2;
                if (values.get(mid) >= queries[i]) {
                    max = values.get(mid);
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }

            answer[i][0] = min;
            answer[i][1] = max;
        }

        return answer;
    }

    private void inorder(TreeNode root, List<Integer> values) {
        if (root == null) return;
        inorder(root.left, values);
        values.add(root.val);
        inorder(root.right, values);
    }
}

