    private int findMin(List<Integer> values, int target) {
        int min = -1;
        for (int value : values) {
            if (value <= target && (min == -1 || value > min)) {
                min = value;
            }
        }
        return min;
    }

    private int findMax(List<Integer> values, int target) {
        int max = -1;
        for (int value : values) {
            if (value >= target && (max == -1 || value < max)) {
                max = value;
            }
        }
        return max;
    }
