public class Solution {
    public long totalCost(int[] costs, int k, int candidates) {
        PriorityQueue<int[]> left = new PriorityQueue<>((a, b) -> a[0] == b[0] ? a[1] - b[1] : a[0] - b[0]);
        PriorityQueue<int[]> right = new PriorityQueue<>((a, b) -> a[0] == b[0] ? a[1] - b[1] : a[0] - b[0]);

        // Initialize left and right minheaps
        for (int i = 0; i < costs.length && i < candidates; i++) {
            left.offer(new int[] {costs[i], i});
        }
        for (int i = costs.length - 1, j = 0; j < candidates && i >= 0; i--, j++) {
            right.offer(new int[] {costs[i], i});
        }

        long totalCost = 0;
        while (k-- > 0) {
            // Compare the top elements of left and right minheaps
            int[] topLeft = left.peek();
            int[] topRight = right.peek();

            if (topLeft[0] <= topRight[0]) {
                totalCost += topLeft[0];
                System.out.println("Adding " + topLeft[0]);

                // Remove the top element from left minheap
                left.poll();

                // If there are still elements to be added to left minheap, do so
                if (left.size() < candidates && costs.length > 0) {
                    int[] next = new int[] {costs[topLeft[1] + 1], topLeft[1] + 1};
                    if (topLeft[1] + 1 < costs.length) {
                        left.offer(next);
                    }
                }
            } else {
                totalCost += topRight[0];

                // Remove the top element from right minheap
                right.poll();

                // If there are still elements to be added to right minheap, do so
