// #2023_01_07_Time_57_ms_(96.24%)_Space_54_MB_(92.26%)
import java.util.PriorityQueue;

public class Solution {
    public long totalCost(int[] costs, int k, int candidates) {
        PriorityQueue<int[]> minHeapLeft = new PriorityQueue<>((a, b) -> a[0] == b[0] ? a[1] - b[1] : a[0] - b[0]);
        PriorityQueue<int[]> minHeapRight = new PriorityQueue<>((a, b) -> a[0] == b[0] ? a[1] - b[1] : a[0] - b[0]);

        for (int i = 0; i < costs.length && i < candidates; i++) {
            minHeapLeft.offer(new int[] {costs[i], i});
        }

        for (int i = costs.length - 1, j = 0; j < candidates && i >= 0; i--, j++) {
            minHeapRight.offer(new int[] {costs[i], i});
        }

        long totalCost = 0;
        while (k-- > 0) {
            if (minHeapLeft.isEmpty() || !minHeapRight.isEmpty() && minHeapLeft.peek()[0] >= minHeapRight.peek()[0]) {
                totalCost += minHeapRight.poll()[0];
                if (!minHeapRight.isEmpty()) {
                    int[] top = minHeapRight.poll();
                    if (top[1] > candidates) {
                        minHeapRight.offer(new int[] {costs[top[1] - candidates], top[1] - candidates});
                    }
                } else {
                    while (!minHeapLeft.isEmpty() && minHeapLeft.peek()[1] < costs.length - candidates) {
                        minHeapRight.offer(minHeapLeft.poll());
                    }
                }
            } else {
                totalCost += minHeapLeft.poll()[0];
                if (!minHeapLeft.isEmpty()) {
                    int[] top = minHeapLeft.poll();
                    if (top[1] + candidates < costs.length) {
                        minHeapLeft.offer(new int[] {costs[top[1] + candidates], top[1] + candidates});
                    }
                } else {
                    while (!minHeapRight.isEmpty() && minHeapRight.peek()[1] >= candidates) {
                        minHeapLeft.offer(minHeapRight.poll());
                    }
                }
            }
        }

        return totalCost;
    }
}

