// #2022_12_16_Time_57_ms_(97.10%)_Space_85.2_MB_(99.42%)
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public List<List<String>> mostPopularCreator(String[] creators, String[] ids, int[] views) {
        Map<String, Long> creatorViews = new HashMap<>();
        Map<String, Integer> creatorMaxViewIndex = new HashMap<>();

        for (int i = 0; i < creators.length; i++) {
            creatorViews.put(creators[i], creatorViews.getOrDefault(creators[i], 0L) + views[i]);
            if (!creatorMaxViewIndex.containsKey(creators[i]) || views[i] > views[creatorMaxViewIndex.get(creators[i])]) {
                creatorMaxViewIndex.put(creators[i], i);
            } else if (views[i] == views[creatorMaxViewIndex.get(creators[i])] && ids[i].compareTo(ids[creatorMaxViewIndex.get(creators[i])]) < 0) {
                creatorMaxViewIndex.put(creators[i], i);
            }
        }

        long maxViews = 0;
        for (long view : creatorViews.values()) {
            maxViews = Math.max(maxViews, view);
        }

        List<List<String>> result = new ArrayList<>();
        for (Map.Entry<String, Long> entry : creatorViews.entrySet()) {
            if (entry.getValue() == maxViews) {
                List<String> list = new ArrayList<>();
                list.add(entry.getKey());
                list.add(ids[creatorMaxViewIndex.get(entry.getKey())]);
                result.add(list);
            }
        }

        return result;
    }
}

