public class Solution {
    public List<List<String>> mostPopularCreator(String[] creators, String[] ids, int[] views) {
        Map<String, Long> popularityMap = new HashMap<>();
        Map<String, String> videoIdMap = new HashMap<>();

        for (int i = 0; i < creators.length; i++) {
            long currentViews = popularityMap.getOrDefault(creators[i], 0L);
            popularityMap.put(creators[i], currentViews + views[i]);

            if (!videoIdMap.containsKey(creators[i]) || views[i] > getVideoView(videoIdMap, creators[i], views, ids)) {
                videoIdMap.put(creators[i], ids[i]);
            } else if (views[i] == getVideoView(videoIdMap, creators[i], views, ids) && ids[i].compareTo(videoIdMap.get(creators[i])) < 0) {
                videoIdMap.put(creators[i], ids[i]);
            }
        }

        long maxPopularity = Collections.max(popularityMap.values());
        List<List<String>> result = new ArrayList<>();

        for (String creator : popularityMap.keySet()) {
            if (popularityMap.get(creator) == maxPopularity) {
                result.add(Arrays.asList(creator, videoIdMap.get(creator)));
            }
        }

        return result;
    }

    private int getVideoView(Map<String, String> videoIdMap, String creator, int[] views, String[] ids) {
        for (int i = 0; i < ids.length; i++) {
            if (ids[i].equals(videoIdMap.get(creator)) && creators[i].equals(creator)) {
                return views[i];
            }
        }

        return -1;
    }
}

