public class Solution {
    public int longestNiceSubarray(int[] nums) {
        int n = nums.length;
        int maxLen = 1;

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j <= n; j++) {
                if (isNice(nums, i, j)) {
                    maxLen = Math.max(maxLen, j - i);
                }
            }
        }

        return maxLen;
    }

    private boolean isNice(int[] nums, int start, int end) {
        for (int i = start; i < end; i++) {
            for (int j = i + 1; j < end; j++) {
                if ((nums[i] & nums[j]) != 0) {
                    return false;
                }
            }
        }

        return true;
    }
}

