        for (int i = 0; i <= roads.length; i++) 
            graph[i] = new ArrayList<>();

        for (int[] road : roads) {
            graph[road[0]].add(road[1]);
            graph[road[1]].add(road[0]);
        }

        return dfs(graph, seats, 0, -1);
