        long total = 0;
        int people = 1;

        for (int child : graph[node]) {
            if (child == parent) 
                continue;

            long temp = dfs(graph, seats, child, node);
            total += temp;
            people += temp / seats + (temp % seats != 0 ? 1 : 0);
        }

        return node > 0 ? total + people / seats : total;
    }
