            graph.get(v).add(new int[]{u, nodeValues[u]});
        }

        int maxStarSum = Integer.MIN_VALUE;

        // Iterate through each node and consider it as the center of a star
        for (int i = 0; i < nodeValues.length; i++) {
            PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> graph.get(i).get(b)[1] - graph.get(i).get(a)[1]);

            // Add all neighbors of the current node to a priority queue
            for (int j = 0; j < graph.get(i).size(); j++) {
                pq.offer(j);
            }

            int sum = nodeValues[i];
            int count = 0;

            // Select the 'maxNumberOfEdges' nodes with the highest values
            while (!pq.isEmpty() && count < maxNumberOfEdges) {
                int idx = pq.poll();
                sum += graph.get(i).get(idx)[1];
                count++;
            }

            maxStarSum = Math.max(maxStarSum, sum);
        }

        return maxStarSum;
    }
