        ArrayDeque<TreeNode> queue = new ArrayDeque<>();
        queue.offer(root);
        int result = 0;

        while (!queue.isEmpty()) {
            List<Integer> levelValues = new ArrayList<>();

            // Store nodes at the current level
            for (int i = queue.size(); i > 0; i--) {
                TreeNode node = queue.poll();

                if (node != null) {
                    levelValues.add(node.val);

                    // Add children to the queue
                    if (node.left != null) queue.offer(node.left);
                    if (node.right != null) queue.offer(node.right);
                }
            }

            // Count inversions in the current level
            int[] sortedLevel = levelValues.stream().mapToInt(i -> i).toArray();
            Arrays.sort(sortedLevel);
            result += countInversions(levelValues, sortedLevel);
        }

        return result;
    }

    private int countInversions(List<Integer> original, int[] sorted) {
        int inversions = 0;

        for (int i = 0; i < original.size(); i++) {
            for (int j = i + 1; j < original.size(); j++) {
                if (original.get(i) > original.get(j)) inversions++;
            }
        }

        return inversions / 2;
    }
}

