import java.util.Map;

public class Solution {
    public int minimumOperations(TreeNode root) {
        if (root == null) {
            return 0;
        }

        ArrayDeque<TreeNode> queue = new ArrayDeque<>();
        queue.offer(root);
        int operations = 0;

        while (!queue.isEmpty()) {
            List<Integer> levelValues = new ArrayList<>();
            int levelSize = queue.size();

            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.poll();
                levelValues.add(node.val);

                if (node.left != null) {
                    queue.offer(node.left);
                }
                if (node.right != null) {
                    queue.offer(node.right);
                }
            }

            int[] sortedLevelValues = new int[levelValues.size()];
            for (int i = 0; i < levelValues.size(); i++) {
                sortedLevelValues[i] = levelValues.get(i);
            }
            Arrays.sort(sortedLevelValues);

            Map<Integer, Integer> valueToIndexMap = new HashMap<>();
            for (int i = 0; i < sortedLevelValues.length; i++) {
                valueToIndexMap.put(sortedLevelValues[i], i);
            }

            boolean[] visited = new boolean[levelValues.size()];
            for (int i = 0; i < levelValues.size(); i++) {
                if (!visited[i]) {
                    int cycleSize = getCycleSize(levelValues, i, valueToIndexMap, visited);
                    operations += (cycleSize - 1);
                }
            }
        }

        return operations;
    }

    private int getCycleSize(List<Integer> levelValues, int startIndex, Map<Integer, Integer> valueToIndexMap, boolean[] visited) {
        int currentNode = startIndex;
        int cycleSize = 0;

        while (!visited[currentNode]) {
            visited[currentNode] = true;
            cycleSize++;
            int nextValue = levelValues.get(currentNode);
            int nextIndex = valueToIndexMap.get(nextValue);
            currentNode = nextIndex;
        }

        return cycleSize;
    }
}

