import java.util.Arrays;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numberOfPaths(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;

        // Calculate the prefix sum of each cell
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i > 0) {
                    grid[i][j] += grid[i - 1][j];
                }
                if (j > 0) {
                    grid[i][j] += grid[i][j - 1];
                }
                if (i > 0 && j > 0) {
                    grid[i][j] -= grid[i - 1][j - 1];
                }
            }
        }

        // Perform DFS with memoization
        return dfs(grid, k, 0, 0, m, n, new Integer[m][n]);
    }

    private int dfs(int[][] grid, int k, int i, int j, int m, int n, Integer[][] memo) {
        if (i < 0 || i >= m || j < 0 || j >= n) {
            return 0;
        }

        if (memo[i][j] != null) {
            return memo[i][j];
        }

        // Calculate the sum of elements on the current path
        int sum = grid[i][j];

        // Base case: reached the destination cell
        if (i == m - 1 && j == n - 1) {
            return sum % k == 0 ? 1 : 0;
        }

        // Recursive calls for moving down and right
        int paths = dfs(grid, k, i + 1, j, m, n, memo);
        paths += dfs(grid, k, i, j + 1, m, n, memo);
        paths %= MOD;

        return memo[i][j] = paths;
    }
}

