public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numberOfPaths(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;

        long[][][] dp = new long[m][n][k];

        // Initialize dp
        for (int i = 0; i < m; i++) {
            Arrays.fill(dp[i][0], 0);
        }
        for (int j = 0; j < n; j++) {
            Arrays.fill(dp[0][j], 0);
        }

        // Initialize base case
        dp[0][0][grid[0][0] % k] = 1;

        // Fill up the dp array
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) continue;

                long[] currRow = new long[k];
                long[] prevUpRow = dp[i-1][j];
                long[] prevLeftCol = dp[i][j-1];

                for (int x = 0; x < k; x++) {
                    int newX = (x + grid[i][j]) % k;
                    currRow[newX] += prevUpRow[x];
                    if (currRow[newX] >= MOD) currRow[newX] -= MOD;

                    currRow[newX] += prevLeftCol[x];
                    if (currRow[newX] >= MOD) currRow[newX] -= MOD;
                }

                dp[i][j] = currRow;
            }
        }

        // Return the result
        return (int) dp[m-1][n-1][0];
    }
