public class Solution {
    public String[] sortPeople(String[] names, int[] heights) {
        Map<Integer, String> map = new HashMap<>();

        // Store the name and height in a map for easy access
        for (int i = 0; i < heights.length; i++) {
            map.put(heights[i], names[i]);
        }

        // Sort the heights array in descending order
        Arrays.sort(heights);
        reverseArray(heights, 0, heights.length - 1);

        // Create a new string array to store the sorted names
        String[] result = new String[heights.length];

        // Populate the result array with the names corresponding to the sorted heights
        for (int i = 0; i < heights.length; i++) {
            result[i] = map.get(heights[i]);
        }

        return result;
    }

    private void reverseArray(int[] array, int start, int end) {
        while (start < end) {
            // Swap the elements at start and end indices
            int temp = array[start];
            array[start] = array[end];
            array[end] = temp;

            // Move towards the center of the array
            start++;
            end--;
        }
    }
}

