        int maxLength = 0;
        for (int i = 0; i < s.length(); i++) {
            for (int j = i + 1; j <= s.length(); j++) {
                String substring = s.substring(i, j);
                if (isAlphabeticalContinuous(substring)) {
                    maxLength = Math.max(maxLength, substring.length());
                }
            }
        }
        return maxLength;
