    public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
        // Create the graph
        graph = new HashMap<>();
        for (int i = 0; i < edges.length; i++) {
            if (!graph.containsKey(edges[i][0])) {
                graph.put(edges[i][0], new ArrayList<>());
            }
            if (!graph.containsKey(edges[i][1])) {
                graph.put(edges[i][1], new ArrayList<>());
            }
            graph.get(edges[i][0]).add(edges[i][1]);
            graph.get(edges[i][1]).add(edges[i][0]);
        }

        // Perform DFS from Alice's starting node (node 0)
        boolean[] visited = new boolean[amount.length];
        int aliceProfit = dfsAlice(0, -1, amount, visited);

        // Perform DFS from Bob's starting node
        int bobTime = bfsBob(bob, 0);
        int aliceBobMeetTime = Math.max(bobTime, 2 * amount.length);
        return maxProfit;
    }

    private int dfsAlice(int node, int parent, int[] amount, boolean[] visited) {
        visited[node] = true;

        // Calculate the profit at this node
        int profit = amount[node];

        // If we are a leaf node and Bob has not yet reached us, return the profit
        if (graph.get(node).size() == 1 && !visited[0]) {
            maxProfit = Math.max(maxProfit, profit);
            return profit;
        }

        // Explore all neighboring nodes
        for (int neighbor : graph.get(node)) {
            if (!visited[neighbor] && neighbor != parent) {
                int childProfit = dfsAlice(neighbor, node, amount, visited);
                profit += childProfit;
            }
        }

        return profit;
    }

    private int bfsBob(int bob, int time) {
        Queue<int[]> queue = new LinkedList<>();
        boolean[] visited = new boolean[graph.size()];
        queue.offer(new int[] {bob, time});
        visited[bob] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int node = current[0];
            time = current[1];

            // If we have reached the root, return the time
            if (node == 0) {
                return time;
            }

            for (int neighbor : graph.get(node)) {
                if (!visited[neighbor]) {
                    queue.offer(new int[] {neighbor, time + 1});
                    visited[neighbor] = true;
                }
            }
        }

        return time;
    }
