import java.util.*;

public class Solution {
    public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
        int n = amount.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        // Build the tree
        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        // Find all leaf nodes
        List<Integer> leaves = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (graph[i].size() == 1 && i != 0) {
                leaves.add(i);
            }
        }

        int[][] distanceToBob = new int[n][2];
        calculateDistance(graph, bob, distanceToBob);

        int maxProfit = Integer.MIN_VALUE;
        for (int leaf : leaves) {
            // Calculate the path from root to leaf
            List<Integer> alicePath = findPath(graph, 0, leaf);

            // Calculate Alice's profit along the path
            int[] aliceProfit = calculateProfit(alicePath, amount, distanceToBob);

            maxProfit = Math.max(maxProfit, aliceProfit[1]);
        }

        return maxProfit;
    }

    private void calculateDistance(List<Integer>[] graph, int bob, int[][] distance) {
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[] {bob, 0});

        boolean[] visited = new boolean[distance.length];
        visited[bob] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            distance[current[0]][0] = current[1];

            for (int neighbor : graph[current[0]]) {
                if (!visited[neighbor]) {
                    queue.offer(new int[] {neighbor, current[1] + 1});
                    visited[neighbor] = true;
                }
            }
        }

        // Calculate distance from each node to root
        Arrays.fill(visited, false);
        queue.clear();
        queue.offer(new int[] {0, 0});
        visited[0] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            distance[current[0]][1] = current[1];

            for (int neighbor : graph[current[0]]) {
                if (!visited[neighbor]) {
                    queue.offer(new int[] {neighbor, current[1] + 1});
                    visited[neighbor] = true;
                }
            }
        }
    }

    private List<Integer> findPath(List<Integer>[] graph, int start, int end) {
        Queue<int[]> queue = new LinkedList<>();
        boolean[] visited = new boolean[graph.length];

        queue.offer(new int[] {start});
        visited[start] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();

            if (current[current.length - 1] == end) {
                List<Integer> list = new ArrayList<>();
                for (int i : current) {
                    list.add(i);
                }
                return list;
            }

            for (int neighbor : graph[current[current.length - 1]]) {
                if (!visited[neighbor]) {
                    int[] newPath = Arrays.copyOf(current, current.length + 1);
                    newPath[newPath.length - 1] = neighbor;
                    queue.offer(newPath);
                    visited[neighbor] = true;
                }
            }
        }

        return new ArrayList<>();
    }

    private int[] calculateProfit(List<Integer> path, int[] amount, int[][] distanceToBob) {
        int profit = 0;
        boolean[] openedGates = new boolean[amount.length];

        for (int i : path) {
            if (!openedGates[i]) {
                profit += amount[i];
                if (profit < 0 && distanceToBob[i][0] == distanceToBob[i][1]) {
                    // Shared cost, Bob is at the same node as Alice
                    profit -= profit / 2;
                }
                openedGates[i] = true;
            }
        }

        return new int[] {profit};
    }
}

