import java.util.*;

public class Solution {
    private int res = Integer.MIN_VALUE;

    public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
        int n = amount.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        int[][] bobPath = findBobPath(graph, 0, bob);
        boolean[] visited = new boolean[n];
        dfs(graph, amount, 0, bobPath, 0, 0, visited);

        return res;
    }

    private void dfs(List<Integer>[] graph, int[] amount, int node, int[][] bobPath, int index, int sum, boolean[] visited) {
        if (graph[node].size() == 1 && node != 0 || bobPath[index][2] >= amount.length - 1) {
            res = Math.max(res, sum);
            return;
        }

        for (int child : graph[node]) {
            if (visited[child]) continue;

            int oldSum = sum;
            visited[child] = true;

            if (bobPath[index][2] == index || bobPath[index][0] == node) {
                if (amount[node] < 0) sum += amount[node] / 2;
                else sum += amount[node] / 2.0;
            } else {
                sum += amount[node];
            }

            dfs(graph, amount, child, bobPath, index + 1, sum, visited);
            sum = oldSum;
            visited[child] = false;
        }
    }

    private int[][] findBobPath(List<Integer>[] graph, int start, int end) {
        Queue<int[]> queue = new LinkedList<>();
        boolean[] visited = new boolean[graph.length];

        queue.offer(new int[]{start, -1, 0});
        visited[start] = true;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int[] nodeInfo = queue.poll();
                if (nodeInfo[0] == end) return getBobPath(nodeInfo, graph);

                for (int child : graph[nodeInfo[0]]) {
                    if (!visited[child]) {
                        queue.offer(new int[]{child, nodeInfo[0], nodeInfo[2] + 1});
                        visited[child] = true;
                    }
                }
            }
        }

        return null;
    }

    private int[][] getBobPath(int[] endNode, List<Integer>[] graph) {
        int[][] path = new int[endNode[2] + 1][3];

        int node = endNode[0], parent = endNode[1];
        for (int i = endNode[2]; i >= 0; i--) {
            path[i][0] = node;
            path[i][1] = parent;
            path[i][2] = i;

            if (parent == -1) break;
            int temp = parent;
            parent = -1;

            for (int child : graph[node]) {
                if (child != temp && !isParent(graph, node, child)) {
                    continue;
                }
                parent = child;
                break;
            }

            node = temp;
        }

        return path;
    }

    private boolean isParent(List<Integer>[] graph, int node, int potentialChild) {
        Queue<int[]> queue = new LinkedList<>();
        boolean[] visited = new boolean[graph.length];

        queue.offer(new int[]{node, 0});
        visited[node] = true;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int[] nodeInfo = queue.poll();

                if (nodeInfo[0] == potentialChild) return true;

                for (int child : graph[nodeInfo[0]]) {
                    if (!visited[child]) {
                        queue.offer(new int[]{child, nodeInfo[1] + 1});
                        visited[child] = true;
                    }
                }
            }
        }

        return false;
    }
}

