public class Solution {
    private static final int MOD = (int) 1e9 + 7;
    private static final boolean[] PRIME = new boolean[10];

    static {
        for (int i = 0; i < 10; i++) {
            if (i == 2 || i == 3 || i == 5 || i == 7) {
                PRIME[i] = true;
            }
        }
    }

    public int beautifulPartitions(String s, int k, int minLength) {
        int n = s.length();
        long[][] dp = new long[n + 1][k + 1];
        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= k; j++) {
                for (int len = minLength; len <= i; len++) {
                    if (i - len < 0) break;
                    String sub = s.substring(i - len, i);
                    if (PRIME[sub.charAt(0) - '0'] && !PRIME[sub.charAt(len - 1) - '0']) {
                        dp[i][j] = (dp[i][j] + dp[i - len][j - 1]) % MOD;
                    }
                }
            }
        }

        return (int) dp[n][k];
    }
}

