    }

    private boolean isPrime(char c) {
        return c == '2' || c == '3' || c == '5' || c == '7';
    }

    private boolean isNonPrime(char c) {
        return !isPrime(c);
    }

    private int dp(String s, int k, int minLength, int i) {
        if (i == s.length()) {
            return k == 0 ? 1 : 0;
        }
        String key = k + "," + i;
        if (memo.containsKey(key)) {
            return memo.get(key);
        }
        int res = 0;
        for (int j = i + minLength; j <= s.length(); j++) {
            if (isPrime(s.charAt(i)) && isNonPrime(s.charAt(j - 1))) {
                res = (res + dp(s, k - 1, minLength, j)) % MOD;
            }
        }
        memo.put(key, res);
        return res;
    }
}

