        if (index == s.length() && k == 0) {
            return 1;
        }
        if (k < 0 || index >= s.length()) {
            return 0;
        }
        if (dp[index][k] != null) {
            return dp[index][k];
        }

        long res = 0;
        for (int i = minLength; i <= s.length() - index; i++) {
            String sub = s.substring(index, index + i);
            if (prime[sub.charAt(0) - '0'] && !prime[sub.charAt(sub.length() - 1) - '0']) {
                res += dfs(s, index + i, k - 1, minLength, dp);
                res %= MOD;
            }
        }

        return dp[index][k] = res;
    }
}

