    private int dfs(String s, int n, int k, int minLength, int start, int count, Integer[][] dp) {
        if (count > k || start >= n) {
            return count == k && start == n ? 1 : 0;
        }
        if (dp[start][count] != null) {
            return dp[start][count];
        }

        int res = 0;
        for (int end = start + minLength; end <= n; end++) {
            if (PRIME_DIGITS[s.charAt(start) - '0'] && !PRIME_DIGITS[s.charAt(end - 1) - '0']) {
                res += dfs(s, n, k, minLength, end, count + 1, dp);
                res %= MOD;
            }
        }

        return dp[start][count] = res;
    }
}

