        int targetSum = skill[0] + skill[skill.length - 1];

        if (targetSum * (skill.length / 2) != sumOfArray(skill)) {
            return -1;
        }

        long chemistrySum = 0;
        int left = 0, right = skill.length - 1;
        while (left < right) {
            if (skill[left] + skill[right] == targetSum) {
