                left++;
                right--;
            } else if (skill[left] + skill[right] > targetSum) {
                return -1;
            } else {
                return -1;
            }
        }

        return chemistrySum;
    }

    private int sumOfArray(int[] arr) {
        int sum = 0;
        for (int num : arr) {
            sum += num;
        }
        return sum;
    }
}

