public class Solution {
    private int totalSum;
    private Map<Integer, List<Integer>> graph;

    public int componentValue(int[] nums, int[][] edges) {
        totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }

        graph = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            graph.put(i, new ArrayList<>());
        }
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        int maxCount = -1;
        for (int i = 1; i <= totalSum / 2; i++) {
            if (totalSum % i == 0) {
                if (canSplit(i)) {
                    maxCount = Math.max(maxCount, totalSum / i - 1);
                }
            }
        }

        return maxCount;
    }

    private boolean canSplit(int target) {
        int[] visited = new int[graph.size()];
        for (int i = 0; i < graph.size(); i++) {
            if (visited[i] == 0 && !dfs(i, 0, target, visited)) {
                return false;
            }
        }
        return true;
    }

    private boolean dfs(int node, int sum, int target, int[] visited) {
        visited[node] = 1;
        sum += nums[node];
        for (int neighbor : graph.get(node)) {
            if (visited[neighbor] == 0) {
                if (!dfs(neighbor, sum, target, visited)) {
                    return false;
                }
            } else if (visited[neighbor] == 2) {
                continue;
            } else {
                return false;
            }
        }

        if (sum == target) {
            visited[node] = 2;
            return true;
        }

        visited[node] = 0;
        return false;
    }

    private int[] nums;

    public void setNums(int[] nums) {
        this.nums = nums;
