import java.util.List;

public class Solution {
    public int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        List<List<Integer>> graph = new ArrayList<>();

        // Initialize the adjacency list
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        // Build the adjacency list
        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            graph.get(u).add(v);
            graph.get(v).add(u);
        }

        int totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }

        // Check if the total sum can be divided evenly
        for (int divisor = 1; divisor <= n / 2; divisor++) {
            if (totalSum % divisor != 0) continue;

            boolean[] visited = new boolean[n];
            int components = 0;

            for (int i = 0; i < n; i++) {
                if (!visited[i]) {
                    long componentValue = dfs(graph, nums, i, visited);

                    // Check if the current component's value is a multiple of the divisor
                    if (componentValue == totalSum / divisor) {
                        components++;
                    } else {
                        break;
                    }
                }
            }

            if (components > 0 && components * (totalSum / divisor) == totalSum) {
                return n - 1 - (divisor - 1);
            }
        }

        // If no valid solution is found, return 0
        return 0;
    }

    private long dfs(List<List<Integer>> graph, int[] nums, int node, boolean[] visited) {
        if (visited[node]) return 0;

        visited[node] = true;
        long componentValue = nums[node];

        for (int neighbor : graph.get(node)) {
            componentValue += dfs(graph, nums, neighbor, visited);
        }

        return componentValue;
    }
}

