        // Build the adjacency list representation of the tree
        for (int[] edge : edges) {
            this.graph[edge[0]].add(edge[1]);
            this.graph[edge[1]].add(edge[0]);
        }

        int totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }

        // Check all possible values
        for (int i = n; i >= 1; i--) {
