    private boolean dfs(int node, int parent, boolean[] visited, int[] nums, int target) {
        visited[node] = true;

        int sum = nums[node];
        for (int child : this.graph[node]) {
            if (!visited[child]) {
                sum += dfs(child, node, visited, nums, target);
            }
        }

        // If the current subtree's value exceeds the target
        if (sum > target) {
            return Integer.MAX_VALUE;
        } else if (sum == target) {
