import java.util.*;

public class Solution {
    public int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        int totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }

        if (totalSum == 0) return n - 1;

        List<Integer> divisors = new ArrayList<>();
        for (int i = 1; i <= Math.sqrt(totalSum); i++) {
            if (totalSum % i == 0) {
                divisors.add(i);
                if (i * i != totalSum) {
                    divisors.add(totalSum / i);
                }
            }
        }

        int maxEdgesDeleted = 0;
        for (int divisor : divisors) {
            if (dfs(nums, graph, 0, -1, totalSum / divisor)) {
                maxEdgesDeleted = Math.max(maxEdgesDeleted, n - divisor);
            }
        }

        return maxEdgesDeleted;
    }

    private boolean dfs(int[] nums, List<List<Integer>> graph, int node, int parent, int target) {
        int sum = 0;
        for (int child : graph.get(node)) {
            if (child != parent && !dfs(nums, graph, child, node, target)) {
                return false;
            }
            sum += nums[child];
        }
        sum += nums[node];
        if (sum > target) {
            return false;
        } else if (sum < target) {
            return true;
        }
        return true;
    }
}

