public class Solution {
    private Map<Integer, List<Integer>> graph;
    private int[] parent;
    private int[] size;

    public int numberOfGoodPaths(int[] vals, int[][] edges) {
        int n = vals.length;
        this.graph = new HashMap<>();
        for (int i = 0; i < n; i++) {
            graph.put(i, new ArrayList<>());
        }
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        this.parent = new int[n];
        Arrays.setAll(parent, i -> i);
        this.size = new int[n];
        Arrays.fill(size, 1);

        Arrays.sort(edges, Comparator.comparingInt(o -> Math.max(vals[o[0]], vals[o[1]])));
        int count = n;
        for (int[] edge : edges) {
            if (!isSameGroup(edge[0], edge[1]) && Math.max(vals[edge[0]], vals[edge[1]]) == vals[edge[0]]) {
                union(edge[0], edge[1]);
                count += size[findParent(edge[0])] * size[findParent(edge[1])];
            }
        }

        return count;
    }

    private int findParent(int node) {
        if (parent[node] != node) {
            parent[node] = findParent(parent[node]);
        }
        return parent[node];
    }

    private void union(int u, int v) {
        int pu = findParent(u);
        int pv = findParent(v);
        if (pu == pv) {
            return;
        }
        size[pu] += size[pv];
        parent[pv] = pu;
    }
}

