import java.util.*;

public class Solution {
    public int numberOfGoodPaths(int[] vals, int[][] edges) {
        Arrays.sort(edges, Comparator.comparingInt(edge -> Math.max(vals[edge[0]], vals[edge[1]])));

        UnionFind uf = new UnionFind(vals.length);
        int result = 0;

        for (int[] edge : edges) {
            int x = edge[0];
            int y = edge[1];

            if (vals[x] == vals[y]) {
                result += countSameValuePaths(uf, x, y, vals);
            }

            uf.union(x, y);
        }

        // add the single node paths
        for (int i = 0; i < vals.length; i++) {
            if (uf.find(i) == i) {
                result++;
            }
        }

        return result;
    }

    private int countSameValuePaths(UnionFind uf, int x, int y, int[] vals) {
        int value = vals[x];
        Map<Integer, Integer> mapX = new HashMap<>();
        Map<Integer, Integer> mapY = new HashMap<>();

        for (int node : uf.getConnectedNodes(x)) {
            if (vals[node] == value) {
                mapX.put(node, 1);
            }
        }

        for (int node : uf.getConnectedNodes(y)) {
            if (vals[node] == value) {
                mapY.put(node, 1);
            }
        }

        int count = 0;
        for (Integer node : mapX.keySet()) {
            if (mapY.containsKey(node)) {
                count += mapX.get(node) * mapY.get(node);
            }
        }

        return count;
    }

    private class UnionFind {
        private int[] parent;

        public UnionFind(int n) {
            this.parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX != rootY) {
                parent[rootX] = rootY;
            }
        }

        public int find(int x) {
            if (parent[x] == x) {
                return x;
            } else {
                parent[x] = find(parent[x]);
                return parent[x];
            }
        }

        public List<Integer> getConnectedNodes(int node) {
            List<Integer> connectedNodes = new ArrayList<>();

            for (int i = 0; i < parent.length; i++) {
                if (find(i) == find(node)) {
                    connectedNodes.add(i);
                }
            }

            return connectedNodes;
        }
    }
}

