import java.util.*;

public class Solution {
    private int ans = 0;
    private Map<Integer, List<Integer>> graph;

    public int numberOfGoodPaths(int[] vals, int[][] edges) {
        Arrays.sort(edges, Comparator.comparingInt(e -> Math.max(vals[e[0]], vals[e[1]])));

        UnionFind uf = new UnionFind(vals.length);
        graph = new HashMap<>();

        for (int i = 0; i < vals.length; i++) {
            graph.put(i, new ArrayList<>());
        }

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];

            if (Math.max(vals[u], vals[v]) != Math.min(vals[u], vals[v])) continue;

            ans += getSameValueNodes(u, uf, vals);
            ans += getSameValueNodes(v, uf, vals);

            graph.get(u).add(v);
            graph.get(v).add(u);

            uf.union(u, v);
        }

        return ans + vals.length;
    }

    private int getSameValueNodes(int node, UnionFind uf, int[] vals) {
        int count = 0;
        for (int i : graph.get(node)) {
            if (!uf.isSameSet(i, node)) continue;

            if (vals[i] == vals[node]) count++;
        }

        return count;
    }

    private class UnionFind {
        private int[] parent;

        public UnionFind(int n) {
            this.parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);

            if (rootA != rootB) {
                parent[rootB] = rootA;
            }
        }

        public boolean isSameSet(int a, int b) {
            return find(a) == find(b);
        }

        private int find(int x) {
            if (x != parent[x]) {
                return parent[x] = find(parent[x]);
            }

            return x;
        }
    }
}

