import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Solution {
    public int magnificentSets(int n, int[][] edges) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        int maxGroups = -1;
        for (int groupSize = 1; groupSize <= n; groupSize++) {
            if (canDivideIntoGroup(graph, groupSize)) {
                maxGroups = Math.max(maxGroups, groupSize);
            }
        }

        return maxGroups;
    }

    private boolean canDivideIntoGroup(List<List<Integer>> graph, int groupSize) {
        for (int i = 1; i <= graph.size() - 1; i++) {
            if (!bfs(graph, i, groupSize)) {
                return false;
            }
        }

        return true;
    }

    private boolean bfs(List<List<Integer>> graph, int startNode, int groupSize) {
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[] {startNode, 1});
        boolean[] visited = new boolean[graph.size()];
        visited[startNode] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int currentNode = current[0];
            int currentGroupIndex = current[1];

            if (currentGroupIndex > groupSize) {
                return false;
            }

            for (int neighbor : graph.get(currentNode)) {
                if (!visited[neighbor]) {
                    visited[neighbor] = true;
                    queue.offer(new int[] {neighbor, currentGroupIndex + 1});
                } else if (Math.abs(currentGroupIndex - getGroupIndex(visited, neighbor, groupSize)) != 1) {
                    return false;
                }
            }
        }

        for (int i = 1; i <= graph.size() - 1; i++) {
            if (!visited[i]) {
                return bfs(graph, i, groupSize);
            }
        }

        return true;
    }

    private int getGroupIndex(boolean[] visited, int node, int groupSize) {
        for (int i = 1; i <= visited.length - 1; i++) {
            if (visited[i]) {
                int groupIndex = 0;
                while (!visited[groupIndex * groupSize + 1] && groupIndex < visited.length / groupSize) {
                    groupIndex++;
                }
                return groupIndex + 1;
            }
        }

        return -1;
    }
}

