        }

        // Populate the adjacency list
        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        int maxGroups = 0;

        // Perform BFS to find the maximum number of groups for each connected component
        boolean[] visited = new boolean[n + 1];
        for (int i = 1; i <= n; i++) {
            if (!visited[i]) {
                Queue<Integer> queue = new LinkedList<>();
                queue.offer(i);
                visited[i] = true;

                int currentMaxGroups = 0;
                while (!queue.isEmpty()) {
                    int size = queue.size();

                    // Try different group sizes from 1 to the size of the current level
                    for (int groupSize = 1; groupSize <= size; groupSize++) {
                        boolean validGrouping = true;

                        // Check if it's possible to divide the nodes at this level into groups of the specified size
                        List<List<Integer>> groups = new ArrayList<>();
                        for (int j = 0; j < groupSize; j++) {
                            groups.add(new ArrayList<>());
                        }
                        int index = 0;
                        while (!queue.isEmpty() && index < size) {
                            int node = queue.poll();
                            groups.get(index % groupSize).add(node);
                            index++;
                        }

                        // Check if the grouping satisfies the condition
                        for (List<Integer> group : groups) {
                            for (int node : group) {
                                for (int neighbor : graph[node]) {
                                    boolean foundNeighborInCorrectGroup = false;
                                    int neighborGroupIndex = -1;
                                    for (int j = 0; j < groups.size(); j++) {
                                        if (groups.get(j).contains(neighbor)) {
                                            neighborGroupIndex = j;
                                            break;
                                        }
                                    }
                                    if (neighborGroupIndex == -1) continue;

                                    // Calculate the absolute difference between group indices
                                    int diff = Math.abs(groups.indexOf(group) - neighborGroupIndex);
                                    if (diff > 0 && diff != 1) {
                                        validGrouping = false;
                                        break;
                                    }
                                }
                            }
                        }

                        // Update the maximum number of groups if a valid grouping is found
                        if (validGrouping) {
                            currentMaxGroups = Math.max(currentMaxGroups, groupSize);
                        }
                    }

                    // Add nodes from the next level to the queue
                    for (int node : graph[queue.peek()]) {
                        if (!visited[node]) {
                            queue.offer(node);
                            visited[node] = true;
                        }
                    }
                }

                maxGroups = Math.max(maxGroups, currentMaxGroups);
            }
        }

        return maxGroups == 0 ? -1 : maxGroups;
    }
