        }

        for (int[] edge : edges) {
            graph[edge[0] - 1].add(edge[1] - 1);
            graph[edge[1] - 1].add(edge[0] - 1);
        }

        int maxGroups = 0;
        boolean[] visited = new boolean[n];

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                Queue<Integer> queue = new LinkedList<>();
                queue.add(i);
                visited[i] = true;

                List<List<Integer>> groups = new ArrayList<>();
                int maxVal = -1;
                boolean isPossible = true;

                while (!queue.isEmpty()) {
                    int size = queue.size();

                    for (int j = 0; j < size; j++) {
                        int node = queue.poll();

                        if (groups.isEmpty() || groups.get(groups.size() - 1).size() >= maxVal + 2) {
                            List<Integer> newGroup = new ArrayList<>();
                            newGroup.add(node);
                            groups.add(newGroup);
                            maxVal++;
                        } else {
                            groups.get(groups.size() - 1).add(node);
                        }

                        for (int neighbor : graph[node]) {
                            if (!visited[neighbor]) {
                                visited[neighbor] = true;
                                queue.add(neighbor);
                            } else {
                                boolean found = false;
                                for (int k = 0; k < groups.size(); k++) {
                                    if (groups.get(k).contains(neighbor)) {
                                        if (Math.abs(groups.size() - 1 - k) != 1) {
                                            isPossible = false;
