import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Solution {
    public int magnificentSets(int n, int[][] edges) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            graph.add(new ArrayList<>());
        }

        // Build the graph
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        int maxGroups = 0;

        // Iterate over each node in the graph
        for (int i = 1; i <= n; i++) {
            Queue<Integer> queue = new LinkedList<>();
            boolean[] visited = new boolean[n + 1];
            queue.offer(i);
            visited[i] = true;

            int groups = 0;
            List<List<Integer>> levels = new ArrayList<>();
            levels.add(new ArrayList<>(Arrays.asList(i)));

            while (!queue.isEmpty()) {
                int size = queue.size();
                List<Integer> level = new ArrayList<>();

                for (int j = 0; j < size; j++) {
                    int node = queue.poll();

                    // Add neighbors to the next level
                    for (int neighbor : graph.get(node)) {
                        if (!visited[neighbor]) {
                            visited[neighbor] = true;
                            queue.offer(neighbor);
                            level.add(neighbor);
                        }
                    }
                }

                if (!level.isEmpty()) {
                    levels.add(level);
                }
            }

            // Check if the nodes can be divided into groups
            boolean valid = true;
            for (int k = 0; k < levels.size(); k++) {
                int groupIndex = (k % 2) + 1;

                for (int node : levels.get(k)) {
                    if (!graph.get(node).isEmpty()) {
                        for (int neighbor : graph.get(node)) {
                            // Find the level of the neighbor
                            boolean found = false;
                            for (int l = 0; l < levels.size(); l++) {
                                if (levels.get(l).contains(neighbor)) {
                                    int groupIndexNeighbor = (l % 2) + 1;
                                    if (Math.abs(groupIndex - groupIndexNeighbor) != 1) {
                                        valid = false;
                                    }
                                    found = true;
                                    break;
                                }
                            }

                            // If the neighbor is not in any level, it's not possible to divide the nodes
                            if (!found) {
                                valid = false;
                            }
                        }
                    }
                }
            }

            // Update maxGroups if it's possible to divide the nodes
            if (valid) {
                groups = levels.size();
                maxGroups = Math.max(maxGroups, groups);
            } else {
                return -1; // It's impossible to group the nodes
            }
        }

        return maxGroups;
    }
}

