        PriorityQueue<int[]> idleRooms = new PriorityQueue<>((a, b) -> a[0] == b[0] ? a[1] - b[1] : a[0] - b[0]);

        for (int i = 0; i < n; i++) {
            idleRooms.offer(new int[] {0, i});
        }

        PriorityQueue<int[]> delayedMeetings = new PriorityQueue<>((a, b) -> a[0] - b[0]);

        int[] meetingCount = new int[n];
        int time = 0;

        for (int[] meeting : meetings) {
            while (!idleRooms.isEmpty() && idleRooms.peek()[0] <= meeting[0]) {
                delayedMeetings.offer(new int[] {idleRooms.poll()[0], idleRooms.peek()[1]});
                idleRooms.poll();
            }

            if (!delayedMeetings.isEmpty()) {
                if (delayedMeetings.peek()[0] < meeting[0]) {
                    time = delayedMeetings.peek()[0];
                    idleRooms.offer(new int[] {time + meeting[1] - meeting[0], delayedMeetings.poll()[1]});
                } else {
                    time = meeting[0];
                    idleRooms.offer(new int[] {time + meeting[1] - meeting[0], idleRooms.size()});
                }
            } else {
                time = meeting[0];
                idleRooms.offer(new int[] {time + meeting[1] - meeting[0], idleRooms.size()});
            }

            meetingCount[idleRooms.peek()[1]]++;
        }

        int maxMeetings = 0;
        for (int i : meetingCount) {
            if (i > maxMeetings) {
