// #Hard #Array #Sorting #Greedy #2022_11_15_Time_4_ms_(97.57%)_Space_98_MB_(87.50%)
public class Solution {
    public long minimumMoney(int[][] transactions) {
        Arrays.sort(transactions, new Comparator<int[]>() {
            @Override
            public int compare(int[] a, int[] b) {
                return Integer.compare(b[1] - b[0], a[1] - a[0]);
            }
        });

        long money = 0;
        long debt = 0;

        for (int[] transaction : transactions) {
            if (money < transaction[0]) {
                debt += transaction[0] - money;
            }

            money -= transaction[0];
            money += transaction[1];
            money = Math.max(money, 0);
        }

        return debt;
    }
}

