public class Solution {
    public boolean canEqualFrequency(String word) {
        Map<Character, Integer> frequencyMap = new HashMap<>();

        // populate the frequency map
        for (char c : word.toCharArray()) {
            frequencyMap.put(c, frequencyMap.getOrDefault(c, 0) + 1);
        }

        int distinctFrequencies = 0;
        int expectedFrequency = -1;

        // find the distinct frequencies and their counts
        for (int frequency : frequencyMap.values()) {
            if (expectedFrequency == -1 || frequency != expectedFrequency) {
                distinctFrequencies++;
                expectedFrequency = frequency;
            }
        }

        // if all frequencies are equal, we can remove one character to make them equal
        if (distinctFrequencies == 1) {
            return !frequencyMap.containsValue(1);
        }

        // if there's more than two distinct frequencies, it's impossible to make them equal by removing one character
        if (distinctFrequencies > 2) {
            return false;
        }

        int maxFrequency = -1;
        for (int frequency : frequencyMap.values()) {
            if (frequency > maxFrequency) {
                maxFrequency = frequency;
            }
        }

        // check if we can remove one character from the word to make all frequencies equal
        for (char c : word.toCharArray()) {
            Map<Character, Integer> newFrequencyMap = new HashMap<>(frequencyMap);
            newFrequencyMap.put(c, newFrequencyMap.get(c) - 1);

            if (newFrequencyMap.get(c) == 0) {
                newFrequencyMap.remove(c);
            }

            distinctFrequencies = 0;
            expectedFrequency = -1;

            for (int frequency : newFrequencyMap.values()) {
                if (expectedFrequency == -1 || frequency != expectedFrequency) {
                    distinctFrequencies++;
                    expectedFrequency = frequency;
                }
            }

            // check if all frequencies in the new word are equal
            if (distinctFrequencies == 1) {
                return true;
            }
        }

        return false;
    }
