// #Easy #String #Hash_Table #Counting #2022_11_18_Time_1_ms_(75.41%)_Space_41.9_MB_(50.90%)
public class Solution {
    public boolean canEqualFrequency(String word) {
        Map<Character, Integer> frequency = new HashMap<>();

        // count the frequency of each character
        for (char c : word.toCharArray()) {
            frequency.put(c, frequency.getOrDefault(c, 0) + 1);
        }

        // if there is only one unique character in the string, 
        // removing any character will make all characters have same frequency
        if (frequency.size() == 1) return true;

        int maxFrequency = 0;
        for (int freq : frequency.values()) {
            maxFrequency = Math.max(maxFrequency, freq);
        }

        // count the number of unique frequencies
        Map<Integer, Integer> frequencyCount = new HashMap<>();
        for (int freq : frequency.values()) {
            frequencyCount.put(freq, frequencyCount.getOrDefault(freq, 0) + 1);
        }

        // if there are two different frequencies and one of them is 1, 
        // removing the character with frequency 1 will make all characters have same frequency
        if (frequencyCount.size() == 2 && frequencyCount.containsKey(1)) return true;

        // if the maximum frequency minus 1 equals to any other frequency, 
        // removing one character from the maximum frequency will make all characters have same frequency
        for (int freq : frequency.values()) {
            if (freq - 1 != maxFrequency) continue;
            int count = 0;
            for (int f : frequency.values()) {
                if (f == freq || f == freq - 1) count++;
            }
            if (count == frequency.size()) return true;
        }

        return false;
    }
}

