public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int countPalindromes(String s) {
        long res = 0;
        for (char c1 = '0'; c1 <= '9'; c1++) {
            for (char c2 = '0'; c2 <= '9'; c2++) {
                String pattern = "" + c1 + c2;
                int n = s.length();
                long[][] dp = new long[n][n];

                // Initialize count of palindromic subsequences ending at each position
                for (int i = 0; i < n; i++) {
                    if (s.charAt(i) == pattern.charAt(1)) {
                        dp[i][i] = 2;
                    } else if (s.charAt(i) == pattern.charAt(0)) {
                        dp[i][i] = 1;
                    }
                }

                // Fill dp in a bottom-up manner
                for (int length = 2; length <= n; length++) {
                    for (int i = 0, j = length - 1; j < n; i++, j++) {
                        if (length == 2) {
                            dp[i][j] = s.charAt(i) == s.charAt(j) ? dp[i][i] * dp[j][j] % MOD : 0;
                        } else {
                            dp[i][j] = 0;
                            for (int k = i; k < j; k++) {
                                dp[i][j] = (dp[i][j] + dp[i][k] * dp[k + 1][j]) % MOD;
                            }
                        }

                        // Update result if we find a palindromic subsequence matching the pattern
                        if (length == n && s.charAt(i) == pattern.charAt(0) && s.charAt(j) == pattern.charAt(1)) {
                            res = (res + dp[i][j]) % MOD;
                        }
                    }
                }
            }
        }

        return (int) res;
    }
}

