public class Solution {
    public String[] splitMessage(String message, int limit) {
        int n = message.length();
        for (int k = 1; k <= n; k++) {
            if ((k - 1) * (limit - Math.floor(Math.log10(k)) - 3) + limit - Math.floor(Math.log10(k)) - 2 >= n) {
                String[] res = new String[k];
                int start = 0;
                for (int i = 0; i < k - 1; i++) {
                    int len = limit - (int)Math.floor(Math.log10(k + 1)) - 3;
                    res[i] = message.substring(start, start + len) + "<" + (i + 1) + "/" + k + ">";
                    start += len;
                }
                res[k - 1] = message.substring(start) + "<" + k + "/" + k + ">";
                return res;
            }
        }
        return new String[0];
    }
}

