        int[] validLengths = new int[totalParts];
        int totalLen = message.length();
        boolean possible = true;
        for (int i = 1; i <= totalParts; i++) {
            if (i == totalParts) {
                // last part can be shorter
                validLengths[i - 1] = limit - String.valueOf(i).length() - String.valueOf(totalParts).length() - 3;
            } else {
                int length = limit - String.valueOf(i + 1).length() - String.valueOf(totalParts).length() - 3;
                if (totalLen < length) {
                    possible = false;
                    break;
                }
                validLengths[i - 1] = length;
                totalLen -= length;
            }
        }

        if (!possible) return new String[0];

        String[] result = new String[totalParts];
        int start = 0;
        for (int i = 1; i <= totalParts; i++) {
            String suffix = "<" + i + "/" + totalParts + ">";
            result[i - 1] = message.substring(start, start + validLengths[i - 1]) + suffix;
            start += validLengths[i - 1];
        }

        return result;
    }
}

