                if (lcm > k || lcm < 0) break;
                if (lcm == k) count++;
            }
        }
        return count;
    }

    private long calculateGCD(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    private long calculateLCM(long a, long b) {
        long gcd = calculateGCD(a, b);
        if (gcd == 0 || a / gcd > Integer.MAX_VALUE || b / gcd > Integer.MAX_VALUE) return -1; // To avoid overflow
        return a * (b / gcd);
    }
}

