public class Solution {
    public long minimumTotalCost(int[] nums1, int[] nums2) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int i = 0; i < nums1.length; i++) {
            if (nums1[i] == nums2[i]) {
                map.put(nums1[i], map.getOrDefault(nums1[i], 0) + 1);
            }
        }

        long totalCost = 0;
        boolean isPossible = true;

        for (int key : map.keySet()) {
            int count = map.get(key);
            if ((count & 1) == 1 || (!map.containsKey(key) && count > 0)) {
                isPossible = false;
                break;
            } else {
                totalCost += (long) key * (count / 2);
            }
        }

        if (isPossible) {
            for (int i = 0; i < nums1.length; i++) {
                if (nums1[i] != nums2[i]) {
                    continue;
                }

                int minIndex = -1;
                int minValue = Integer.MAX_VALUE;

                for (int j = i + 1; j < nums1.length; j++) {
                    if (nums1[j] == nums2[i] && nums1[i] != nums2[j]) {
                        totalCost += i + j;
                        swap(nums1, i, j);
                        break;
                    } else if (nums1[i] == nums2[j] && nums1[j] != nums2[i]) {
                        minIndex = j;
                        minValue = Math.min(minValue, nums1[minIndex]);
                    }
                }

                if (minIndex == -1) {
                    isPossible = false;
                    break;
                } else {
                    totalCost += i + minIndex;
                    swap(nums1, i, minIndex);
                }
            }
        }

        return isPossible ? totalCost : -1;
    }

    private void swap(int[] nums1, int i, int j) {
        int temp = nums1[i];
        nums1[i] = nums1[j];
        nums1[j] = temp;
    }
}

