                pq.offer(new int[] {key, map.get(key).get(0)});
            }
        }

        while (!pq.isEmpty() && pq.size() > 1) {
            int[] arr1 = pq.poll();
            int[] arr2 = pq.poll();
            cost += arr1[1] + arr2[1];
            List<Integer> list1 = map.get(arr1[0]);
