                remaining -= Math.min(count[i][0], remaining);
            }
        }

        if (remaining <= 0) return res;

        for (int i = n - 1; i >= 0; i--) {
            if (nums1[i] != nums2[i] && nums1[i] != maxIndex && nums2[i] != maxIndex) {
                remaining--;
                res += i;

                if (remaining <= 0) break;
            }
        }

        return remaining > 0 ? -1 : res;
    }
}

