public class Solution {
    public ListNode removeNodes(ListNode head) {
        if (head == null || head.next == null) return head;

        // Reverse the linked list
        ListNode prev = null, curr = head, nextTemp = null;
        while (curr != null) {
            nextTemp = curr.next;
            curr.next = prev;
            prev = curr;
            curr = nextTemp;
        }

        // Initialize dummy node and new head
        ListNode dummy = new ListNode(0);
        ListNode newHead = dummy;
        int maxVal = Integer.MIN_VALUE;

        // Traverse reversed linked list from left to right
        while (prev != null) {
            if (prev.val >= maxVal) {
                maxVal = prev.val;
                dummy.next = prev;
                dummy = dummy.next;
            }
            prev = prev.next;
        }

        // Set next of last node to null
        dummy.next = null;

        return newHead.next;
    }
}

