// #2022_04_19_Time_104_ms_(88.83%)_Space_58.3_MB_(91.85%)
import java.util.PriorityQueue;

public class Solution {
    public int minimumDeviation(int[] nums) {
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>((a, b) -> b - a);

        for (int num : nums) {
            if (num % 2 == 1) {
                num *= 2;
            }
            maxHeap.offer(num);
        }

        int minDeviation = Integer.MAX_VALUE;
        int smallest = getSmallest(maxHeap);

        while (!maxHeap.isEmpty()) {
            int largest = maxHeap.poll();
            minDeviation = Math.min(minDeviation, largest - smallest);

            if (largest % 2 == 0) {
                int newNum = largest / 2;
                maxHeap.offer(newNum);

                if (newNum < smallest) {
                    smallest = getSmallest(maxHeap);
                }
            } else {
                break;
            }
        }

        return minDeviation;
    }

    private int getSmallest(PriorityQueue<Integer> maxHeap) {
        int smallest = Integer.MAX_VALUE;

        if (!maxHeap.isEmpty()) {
            PriorityQueue<Integer> temp = new PriorityQueue<>();

            while (!maxHeap.isEmpty()) {
                int num = maxHeap.poll();
                smallest = Math.min(smallest, num);
                temp.offer(num);
            }

            while (!temp.isEmpty()) {
                maxHeap.offer(temp.poll());
            }
        }

        return smallest;
    }
}

