public class Solution {
    private int maxHappiness = Integer.MIN_VALUE;

    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        int[][] grid = new int[m][n];
        dfs(grid, 0, introvertsCount, extrovertsCount);
        return maxHappiness;
    }

    private void dfs(int[][] grid, int index, int introvertsCount, int extrovertsCount) {
        if (index == m * n) {
            calculateHappiness(grid, introvertsCount, extrovertsCount);
            return;
        }

        int x = index / n;
        int y = index % n;

        // not place
        dfs(grid, index + 1, introvertsCount, extrovertsCount);

        if (introvertsCount > 0) {
            grid[x][y] = 2; // place intro
            dfs(grid, index + 1, introvertsCount - 1, extrovertsCount);
            grid[x][y] = 0;
        }

        if (extrovertsCount > 0) {
            grid[x][y] = 3; // place extro
            dfs(grid, index + 1, introvertsCount, extrovertsCount - 1);
            grid[x][y] = 0;
        }
    }

    private void calculateHappiness(int[][] grid, int introvertsCount, int extrovertsCount) {
        int happiness = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 2) { // intro
                    happiness += 120;
                    if (i > 0 && grid[i - 1][j] != 0) happiness -= 30;
                    if (i < m - 1 && grid[i + 1][j] != 0) happiness -= 30;
                    if (j > 0 && grid[i][j - 1] != 0) happiness -= 30;
                    if (j < n - 1 && grid[i][j + 1] != 0) happiness -= 30;
                } else if (grid[i][j] == 3) { // extro
                    happiness += 40;
                    if (i > 0 && grid[i - 1][j] != 0) happiness += 20;
                    if (i < m - 1 && grid[i + 1][j] != 0) happiness += 20;
                    if (j > 0 && grid[i][j - 1] != 0) happiness += 20;
                    if (j < n - 1 && grid[i][j + 1] != 0) happiness += 20;
                }
            }
        }

        maxHappiness = Math.max(maxHappiness, happiness);
    }

    private static final int m = 10; // default value
    private static final int n = 10; // default value
}

