// #Hard #Dynamic_Programming #Bit_Manipulation #Bitmask #Memoization
// #2022_04_23_Time_95_ms_(75.00%)_Space_53.1_MB_(58.33%)

public class Solution {
    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        int[][] dp = new int[m * n][introvertsCount + 1];
        for (int i = 0; i < dp.length; i++) {
            for (int j = 0; j < dp[0].length; j++) {
                dp[i][j] = -1;
            }
        }

        return dfs(0, introvertsCount, extrovertsCount, m, n, dp);
    }

    private int dfs(int index, int remainingIntroverts, int remainingExtroverts, int m, int n, int[][] dp) {
        if (index == m * n || remainingIntroverts == 0 && remainingExtroverts == 0) {
            return 0;
        }

        if (dp[index][remainingIntroverts] != -1) {
            return dp[index][remainingIntroverts];
        }

        int maxHappiness = dfs(index + 1, remainingIntroverts, remainingExtroverts, m, n, dp);

        // Place an introvert
        if (remainingIntroverts > 0) {
            int happiness = 120;
            for (int neighborIndex : getNeighborIndices(index, m, n)) {
                if (neighborIndex >= 0 && neighborIndex < m * n) {
                    happiness -= 30;
                }
            }
            maxHappiness = Math.max(maxHappiness, happiness + dfs(index + 1, remainingIntroverts - 1, remainingExtroverts, m, n, dp));
        }

        // Place an extrovert
        if (remainingExtroverts > 0) {
            int happiness = 40;
            for (int neighborIndex : getNeighborIndices(index, m, n)) {
                if (neighborIndex >= 0 && neighborIndex < m * n) {
                    happiness += 20;
                }
            }
            maxHappiness = Math.max(maxHappiness, happiness + dfs(index + 1, remainingIntroverts, remainingExtroverts - 1, m, n, dp));
        }

        dp[index][remainingIntroverts] = maxHappiness;
        return maxHappiness;
    }

    private int[] getNeighborIndices(int index, int m, int n) {
        int row = index / n;
        int col = index % n;

        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        int[] neighborIndices = new int[4];

        for (int i = 0; i < 4; i++) {
            int newRow = row + directions[i][0];
            int newCol = col + directions[i][1];

            if (newRow >= 0 && newRow < m && newCol >= 0 && newCol < n) {
                neighborIndices[i] = newRow * n + newCol;
            } else {
                neighborIndices[i] = -1;
            }
        }

        return neighborIndices;
    }
}

