            col = 0;
        }
        if (row == m) {
            return 0;
        }

        if (memo[row][col][currentIntroverts] != -1) {
            return memo[row][col][currentIntroverts];
        }

        int ans = dp(m, n, introvertsRemaining, extrovertsRemaining, row, col + 1, currentIntroverts);
        if (introvertsRemaining > 0) {
            int introvertHappiness = 120 - countNeighbors(row, col, m, n, currentIntroverts) * 30;
            ans = Math.max(ans, dp(m, n, introvertsRemaining - 1, extrovertsRemaining, row, col + 1, currentIntroverts + 1) + introvertHappiness);
        }

        if (extrovertsRemaining > 0) {
            int extrovertHappiness = 40 + countNeighbors(row, col, m, n, currentIntroverts) * 20;
            ans = Math.max(ans, dp(m, n, introvertsRemaining, extrovertsRemaining - 1, row, col + 1, currentIntroverts) + extrovertHappiness);
        }

        memo[row][col][currentIntroverts] = ans;

        return ans;
    }

    private int countNeighbors(int row, int col, int m, int n, int currentIntroverts) {
        int neighbors = 0;
        if (row > 0 && (currentIntroverts - (n * (row - 1))) >= 0) {
            neighbors++;
        }
        if (col > 0 && ((currentIntroverts - row) >= 0)) {
            neighbors++;
        }
        if (row < m - 1 && (currentIntroverts + n - (n * row)) <= currentIntroverts) {
            neighbors++;
        }
        if (col < n - 1 && (currentIntroverts + 1 - row) <= currentIntroverts) {
            neighbors++;
        }

        return neighbors;
    }
}

