// #2022_04_23_Time_95_ms_(75.00%)_Space_53.1_MB_(58.33%)
public class Solution {
    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        int maxHappiness = 0;

        for (int mask = 0; mask < (1 << (m * n)); mask++) {
            boolean isValidMask = isValid(mask, m, n, introvertsCount, extrovertsCount);

            if (!isValidMask) {
                continue;
            }

            int currentHappiness = calculateHappiness(mask, m, n);
            maxHappiness = Math.max(maxHappiness, currentHappiness);
        }

        return maxHappiness;
    }

    private boolean isValid(int mask, int m, int n, int introvertsCount, int extrovertsCount) {
        int introvertCount = 0;
        int extrovertCount = 0;

        for (int i = 0; i < m * n; i++) {
            if ((mask & (1 << i)) != 0) {
                if ((i % 2) == 0 && extrovertCount < extrovertsCount) {
                    introvertCount++;
                } else if ((i % 2) == 1 && introvertCount < introvertsCount) {
                    extrovertCount++;
                } else {
                    return false;
                }
            }
        }

        return (introvertCount <= introvertsCount) && (extrovertCount <= extrovertsCount);
    }

    private int calculateHappiness(int mask, int m, int n) {
        int happiness = 0;

        for (int i = 0; i < m * n; i++) {
            if ((mask & (1 << i)) == 0) {
                continue;
            }

            if ((i % 2) == 0) { // introvert
                happiness += 120;

                int neighborCount = countNeighbors(mask, m, n, i);
                happiness -= 30 * neighborCount;
            } else { // extrovert
                happiness += 40;

                int neighborCount = countNeighbors(mask, m, n, i);
                happiness += 20 * neighborCount;
            }
        }

        return happiness;
    }

    private int countNeighbors(int mask, int m, int n, int index) {
        int row = index / n;
        int col = index % n;
        int neighbors = 0;

        // north
        if (row > 0 && ((mask & (1 << (index - n))) != 0)) {
            neighbors++;
        }

        // south
        if (row < m - 1 && ((mask & (1 << (index + n))) != 0)) {
            neighbors++;
        }

        // east
        if (col < n - 1 && ((mask & (1 << (index + 1))) != 0)) {
            neighbors++;
        }

        // west
        if (col > 0 && ((mask & (1 << (index - 1))) != 0)) {
            neighbors++;
        }

        return neighbors;
    }
}

