        int[] suffixMaxPort = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            suffixMaxPort[i] = Math.max(boxes[i][0], suffixMaxPort[i + 1]);
        }
        int[][] dp = new int[n + 1][n + 1];
