                    dp[i][j] = 2;
                } else if (boxes[j][0] != suffixMaxPort[j + 1]) {
                    dp[i][j] = dp[i][j + 1] + 2;
                } else {
                    dp[i][j] = Math.min(dp[i][j + 1], dp[i][j + 1] + 1);
                }
            }
        }
        int ans = dp[0][n];
        for (int i = 0; i < n; i++) {
            int[] countWeight = new int[]{0, 0};
            int j = i;
            while (j < n && countWeight[0] < maxBoxes && countWeight[1] <= maxWeight) {
                countWeight[0]++;
                countWeather(j, boxes, countWeight);
