public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;
        int[] prefixSum = new int[n + 1];

        // Calculate the prefix sum for weights
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + boxes[i][1];
        }

        // Initialize DP table with max value
        int[] dp = new int[n + 1];
        for (int i = 0; i <= n; i++) {
            dp[i] = Integer.MAX_VALUE / 2;
        }

        // Base case: deliver the first box
        dp[0] = 0;

        // Iterate over each box
        for (int i = 1; i <= n; i++) {
            // Try to load as many boxes as possible into the ship
            for (int j = i - 1; j >= Math.max(0, i - maxBoxes) && prefixSum[i] - prefixSum[j] <= maxWeight; j--) {
                int portsChangeCount = getPortsChangeCount(boxes, j + 1, i);
                dp[i] = Math.min(dp[i], dp[j] + portsChangeCount + 2);
            }
        }

        return dp[n];
    }

    private int getPortsChangeCount(int[][] boxes, int start, int end) {
        if (start >= end) {
            return 0;
        }

        int count = 0;
        for (int i = start; i < end; i++) {
            if (i == start || boxes[i][0] != boxes[i - 1][0]) {
                count++;
            }
        }

        return count;
    }
}

