public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;
        int[] suffixMinPorts = new int[n + 1];
        for (int i = n - 1; i >= 0; --i) {
            suffixMinPorts[i] = Math.min(suffixMinPorts[i + 1] + (boxes[i][0] != boxes[i + 1][0] ? 1 : 0), boxes[i][0]);
        }

        int[][] dp = new int[n + 1][n + 1];
        for (int i = n - 1; i >= 0; --i) {
            for (int j = i; j < n; ++j) {
                if (j - i + 1 > maxBoxes || getWeight(boxes, i, j) > maxWeight) {
                    dp[i][j] = Integer.MAX_VALUE / 2;
                } else if (i == j) {
                    dp[i][j] = suffixMinPorts[j];
                } else {
                    int minTrips = Integer.MAX_VALUE;
                    for (int k = i; k < j; ++k) {
                        minTrips = Math.min(minTrips, dp[i][k] + dp[k + 1][j]);
                    }
                    dp[i][j] = Math.min(minTrips, suffixMinPorts[j]);
                }
            }
        }

        return dp[0][n - 1] * 2;
    }

    private int getWeight(int[][] boxes, int start, int end) {
        int weight = 0;
        for (int i = start; i <= end; ++i) {
            weight += boxes[i][1];
