// #Hard #Array #Dynamic_Programming #Heap_Priority_Queue #Queue #Segment_Tree #Monotonic_Queue
// #2022_04_13_Time_9_ms_(91.09%)_Space_74.2_MB_(94.06%)
public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;

        // Calculate the cumulative weights
        int[] cumWeights = new int[n + 1];
        for (int i = 0; i < n; i++) {
            cumWeights[i + 1] = cumWeights[i] + boxes[i][1];
        }

        // Calculate the port changes
        int[] portsChanges = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            if (i == 0 || boxes[i - 1][0] != boxes[i % n][0]) {
                portsChanges[i] = portsChanges[i - 1] + 1;
            } else {
                portsChanges[i] = portsChanges[i - 1];
            }
        }

        // Initialize the dp array
        int[] dp = new int[n + 1];
        for (int i = n; i >= 0; i--) {
            if (i == n) {
                dp[i] = 0;
            } else {
                dp[i] = Integer.MAX_VALUE;
                for (int j = i + 1; j <= Math.min(i + maxBoxes, n); j++) {
                    if (cumWeights[j] - cumWeights[i] > maxWeight) {
                        break;
                    }
                    dp[i] = Math.min(dp[i], dp[j] + portsChanges[j - 1] - portsChanges[i]);
                }
            }
        }

        return dp[0] + n;
    }
}

