public class Solution {
    public List<Boolean> checkArithmeticSubarrays(int[] nums, int[] l, int[] r) {
        List<Boolean> result = new ArrayList<>();

        for (int i = 0; i < l.length; i++) {
            int[] subarray = getSubarray(nums, l[i], r[i]);

            if (subarray == null) {
                result.add(false);
                continue;
            }

            Arrays.sort(subarray);

            boolean isArithmetic = true;
            int diff = subarray[1] - subarray[0];

            for (int j = 2; j < subarray.length; j++) {
                if (subarray[j] - subarray[j - 1] != diff) {
                    isArithmetic = false;
                    break;
                }
            }

            result.add(isArithmetic);
        }

        return result;
    }

    private int[] getSubarray(int[] nums, int left, int right) {
        if (left < 0 || right >= nums.length || left > right) {
            return null;
        }

        int[] subarray = new int[right - left + 1];
        System.arraycopy(nums, left, subarray, 0, right - left + 1);

        return subarray;
    }
}

