public class Solution {
    public int createSortedArray(int[] instructions) {
        TreeMap<Integer, Integer> map = new TreeMap<>();
        int cost = 0;
        for (int instruction : instructions) {
            int leftCount = countLessThan(map, instruction);
            int rightCount = countGreaterThan(map, instruction);
            cost += Math.min(leftCount, rightCount);
            addElementToMap(map, instruction);
        }
        return cost % (1000000007);
    }

    private int countLessThan(TreeMap<Integer, Integer> map, int num) {
        int count = 0;
        for (int key : map.keySet()) {
            if (key < num) {
                count += map.get(key);
            } else {
                break;
            }
        }
        return count;
    }

    private int countGreaterThan(TreeMap<Integer, Integer> map, int num) {
        int total = 0;
        for (int key : map.keySet()) {
            total += map.get(key);
        }
        return total - countLessThan(map, num);
    }

    private void addElementToMap(TreeMap<Integer, Integer> map, int num) {
        if (map.containsKey(num)) {
            map.put(num, map.get(num) + 1);
        } else {
            map.put(num, 1);
        }
    }
}

