import java.util.Arrays;
public class Solution {
    public int minimumIncompatibility(int[] nums, int k) {
        int n = nums.length;
        if (n % k != 0) return -1;

        Arrays.sort(nums);
        int subsetSize = n / k;

        int[][] dp = new int[k][1 << n];
        for (int i = 0; i < k; i++) {
            Arrays.fill(dp[i], Integer.MAX_VALUE);
        }
        dp[0][0] = 0;

        for (int i = 0; i < k; i++) {
            for (int mask = 0; mask < (1 << n); mask++) {
                if (dp[i][mask] == Integer.MAX_VALUE) continue;
                int count = 0, max = -1, min = Integer.MAX_VALUE;
                for (int j = 0; j < n; j++) {
                    if ((mask & (1 << j)) != 0) {
                        count++;
                        max = Math.max(max, nums[j]);
                        min = Math.min(min, nums[j]);
                        if (count == subsetSize) break;
                    }
                }
                if (count == subsetSize) {
                    int incompatibility = max - min;
                    dp[i + 1][mask] = Math.min(dp[i + 1][mask], dp[i][mask] + incompatibility);
                }
                for (int j = 0; j < n; j++) {
                    if ((mask & (1 << j)) == 0) {
                        int newMask = mask | (1 << j);
                        boolean duplicate = false;
                        for (int l = 0; l < j; l++) {
                            if ((newMask & (1 << l)) != 0 && nums[j] == nums[l]) {
                                duplicate = true;
                                break;
                            }
                        }
                        if (!duplicate) dp[i][newMask] = Math.min(dp[i][newMask], dp[i][mask]);
                    }
                }
            }
        }

        return dp[k - 1][(1 << n) - 1];
    }
}

