public class Solution {
    public int minimumIncompatibility(int[] nums, int k) {
        int n = nums.length;
        if (n % k != 0) return -1;

        Arrays.sort(nums);
        int subsetSize = n / k;
        int[][] subsets = new int[k][subsetSize];
        boolean[] visited = new boolean[n];

        for (int i = 0; i < n; i++) {
            if (visited[i]) continue;
            dfs(subsets, visited, nums, i, 0);
            if (subsets[0].length != subsetSize) return -1;
        }

        int sumOfIncompatibilities = 0;
        for (int[] subset : subsets) {
            Arrays.sort(subset);
            sumOfIncompatibilities += subset[subset.length - 1] - subset[0];
        }
        return sumOfIncompatibilities;
    }

    private void dfs(int[][] subsets, boolean[] visited, int[] nums, int index, int subsetIndex) {
        if (index == nums.length || subsetIndex == subsets.length) return;

        for (int i = 0; i < nums.length; i++) {
            if (!visited[i] && !contains(subsets[subsetIndex], nums[i])) {
                visited[i] = true;
                subsets[subsetIndex][getFirstEmptyIndex(subsets[subsetIndex])] = nums[i];
                dfs(subsets, visited, nums, index + 1, subsetIndex);
                if (subsets[0].length != nums.length / subsets.length) return;
            }
        }

        for (int i = 0; i < nums.length; i++) {
            if (!visited[i]) {
                visited[i] = true;
                dfs(subsets, visited, nums, index + 1, subsetIndex);
                if (subsets[0].length != nums.length / subsets.length) return;
            }
        }

        for (int i = 0; i < nums.length; i++) {
            if (!visited[i]) {
                for (int j = 0; j < subsets.length; j++) {
                    subsets[j][getFirstEmptyIndex(subsets[j])] = nums[i];
                    dfs(subsets, visited, nums, index + 1, subsetIndex);
                }
            }
        }
    }

    private boolean contains(int[] array, int value) {
        for (int element : array) {
            if (element == value) return true;
        }
        return false;
    }

    private int getFirstEmptyIndex(int[] array) {
        for (int i = 0; i < array.length; i++) {
            if (array[i] == 0) return i;
        }
        throw new RuntimeException("No empty index found");
    }
}

