import java.util.Arrays;

public class Solution {
    public int minimumIncompatibility(int[] nums, int k) {
        int n = nums.length;
        if (n % k != 0) return -1;

        Arrays.sort(nums);
        int subsetSize = n / k;

        // Check if it's possible to distribute the array into k subsets of equal size with no two equal elements in the same subset
        for (int i = 0; i < n - subsetSize + 1; i++) {
            if (nums[i] == nums[i + subsetSize - 1]) return -1;
        }

        // Initialize a dynamic programming table to store the minimum possible sum of incompatibilities
        int[][] dp = new int[n][1 << k];
        for (int[] row : dp) Arrays.fill(row, Integer.MAX_VALUE);

        // Base case: one subset with all elements from nums[0] to nums[i]
        for (int i = 0; i < n - subsetSize + 1; i++) {
            int maxVal = nums[i + subsetSize - 1];
            int minVal = nums[i];
            dp[i][1 << 0] = maxVal - minVal;
        }

        // Fill the dynamic programming table
        for (int i = 0; i < n - subsetSize; i++) {
            for (int bitmask = 0; bitmask < (1 << k); bitmask++) {
                if (dp[i][bitmask] != Integer.MAX_VALUE) {
                    for (int j = i + 1; j <= n - subsetSize; j++) {
                        int nextBitmask = bitmask | (1 << (j / subsetSize));
                        if ((nextBitmask & (~bitmask)) == (nextBitmask ^ bitmask)) {
                            dp[j][nextBitmask] = Math.min(dp[j][nextBitmask], dp[i][bitmask] + nums[j + subsetSize - 1] - nums[j]);
                        }
                    }
                }
            }
        }

        // The minimum possible sum of incompatibilities is stored in the last cell of the dynamic programming table
        int bitmask = (1 << k) - 1;
        return dp[n - subsetSize][bitmask];
    }
}

