import java.util.Arrays;
public class Solution {
    public int minimumIncompatibility(int[] nums, int k) {
        int n = nums.length;
        if (n % k != 0) return -1;

        Arrays.sort(nums);
        int size = n / k;

        int[][] dp = new int[n][1 << n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dp[i], Integer.MAX_VALUE);
        }

        dp[0][1] = 0;
        for (int mask = 1; mask < (1 << n); mask++) {
            int count = Integer.bitCount(mask);

            if (count % size != 0) continue;

            int maxVal = -1, minVal = Integer.MAX_VALUE;
            boolean hasDuplicate = false;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) continue;
                if (minVal > nums[i]) minVal = nums[i];
                if (maxVal < nums[i]) maxVal = nums[i];

                int innerMask = mask ^ (1 << i);
                for (int j = 0; j < n; j++) {
                    if ((innerMask & (1 << j)) != 0 && nums[j] == nums[i]) hasDuplicate = true;
                }
            }

            if (hasDuplicate) continue;

            int subsetIncomp = maxVal - minVal;

            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0 && dp[i][mask ^ (1 << i)] != Integer.MAX_VALUE) {
                    dp[count][mask] = Math.min(dp[count][mask], dp[i][mask ^ (1 << i)] + subsetIncomp);
                }
            }
        }

        return dp[n - 1][(1 << n) - 1];
    }
}

