public class Solution {
    public int[] mostCompetitive(int[] nums, int k) {
        int n = nums.length;
        int[] result = new int[k];
        Stack<Integer> stack = new Stack<>();

        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && stack.size() + n - i > k && nums[stack.peek()] > nums[i]) {
                stack.pop();
            }
            if (stack.size() < k) {
                stack.push(i);
            }
        }

        for (int i = 0; i < k; i++) {
            result[i] = nums[stack.get(i)];
        }

        return result;
    }
}

