            }
            if (i > 0 && values.get(i) <= values.get(i - 1)) { // Not increasing
                return false;
            }
        }
        return true;
    }

    private boolean isDecreasingEven(List<Integer> values) {
        for (int i = 0; i < values.size(); i++) {
            if ((values.get(i) % 2 != 0)) { // Odd value at odd-indexed level
                return false;
            }
            if (i > 0 && values.get(i) >= values.get(i - 1)) { // Not decreasing
                return false;
            }
        }
        return true;
    }
