public class Solution {
    public boolean canFormArray(int[] arr, int[][] pieces) {
        Map<Integer, Integer> indexMap = new HashMap<>();

        // Populate the map with the first element of each piece and its index
        for (int i = 0; i < pieces.length; i++) {
            indexMap.put(pieces[i][0], i);
        }

        int arrIndex = 0;

        while (arrIndex < arr.length) {
            if (!indexMap.containsKey(arr[arrIndex])) {
                return false;
            }

            int pieceIndex = indexMap.get(arr[arrIndex]);

            // Compare the current piece with the corresponding part of arr
            for (int j = 0; j < pieces[pieceIndex].length; j++) {
                if (arrIndex >= arr.length || arr[arrIndex] != pieces[pieceIndex][j]) {
                    return false;
                }
                arrIndex++;
            }
        }

        // If we've reached the end of arr and all elements have been used, return true
        for (int[] piece : pieces) {
            if (!contains(arr, piece)) {
                return false;
            }
        }

        return true;
    }

    private boolean contains(int[] arr, int[] piece) {
        int count = 0;
        for (int num : piece) {
            for (int i = 0; i < arr.length; i++) {
                if (arr[i] == num) {
                    count++;
                    break;
                }
            }
        }

        return count == piece.length;
    }
}

