        // Calculate combination values and store in 2D array
        for (int i = 0; i < row + col; i++) {
            comb[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
            }
        }

        k--; // Convert to 0-based index
        StringBuilder path = new StringBuilder();

        while (row > 0 && col > 0) {
            // If choosing 'H' doesn't exceed k, then choose it
            if ((long) (comb[row + col - 2][col - 1]) <= k) {
                path.append('V');
                row--;
            } else {
                path.append('H');
                col--;
                k -= comb[row + col][col];
            }
        }

        // Append remaining characters
        while (row > 0) {
            path.append('V');
            row--;
        }

        while (col > 0) {
            path.append('H');
            col--;
        }

        return path.toString();
    }
