public class Solution {
    public int[] frequencySort(int[] nums) {
        Map<Integer, Integer> frequencyMap = new HashMap<>();

        // Count the frequency of each number
        for (int num : nums) {
            frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
        }

        // Create a list to store the numbers and their frequencies
        List<Map.Entry<Integer, Integer>> list = new ArrayList<>(frequencyMap.entrySet());

        // Sort the list based on the frequency of the numbers and then by the number itself in descending order
        Collections.sort(list, (a, b) -> {
            if (a.getValue().equals(b.getValue())) {
                return b.getKey() - a.getKey();
            } else {
                return a.getValue() - b.getValue();
            }
        });

        // Create an array to store the sorted numbers
        int[] result = new int[nums.length];
        int index = 0;

        // Populate the result array with the sorted numbers
        for (Map.Entry<Integer, Integer> entry : list) {
            int num = entry.getKey();
            int frequency = entry.getValue();

            for (int i = 0; i < frequency; i++) {
                result[index++] = num;
            }
        }

        return result;
    }
}

