    private int getRank(int[][] ans, int[][] matrix, int row, int col) {
        int m = matrix.length, n = matrix[0].length;
        int rank = 0;

        for (int i = 0; i < n; i++) {
            if (i == col) continue;
            if (matrix[row][col] > matrix[row][i]) {
                rank = Math.max(rank, ans[row][i] + 1);
            } else if (matrix[row][col] == matrix[row][i]) {
                rank = Math.max(rank, ans[row][i]);
            }
        }

        for (int i = 0; i < m; i++) {
            if (i == row) continue;
            if (matrix[row][col] > matrix[i][col]) {
                rank = Math.max(rank, ans[i][col] + 1);
            } else if (matrix[row][col] == matrix[i][col]) {
                rank = Math.max(rank, ans[i][col]);
            }
        }

        return rank;
    }
}

