import java.util.Arrays;

public class Solution {
    private final int[] parent;
    private final int[] rank;

    public Solution(int n) {
        this.parent = new int[n];
        for (int i = 0; i < n; i++) {
            this.parent[i] = i;
        }
        this.rank = new int[n];
    }

    public int findParent(int x) {
        if (this.parent[x] != x) {
            this.parent[x] = this.findParent(this.parent[x]);
        }
        return this.parent[x];
    }

    public void union(int a, int b) {
        int parentA = this.findParent(a);
        int parentB = this.findParent(b);

        if (this.rank[parentA] < this.rank[parentB]) {
            this.parent[parentA] = parentB;
        } else if (this.rank[parentA] > this.rank[parentB]) {
            this.parent[parentB] = parentA;
        } else {
            this.parent[parentB] = parentA;
            this.rank[parentA]++;
        }
    }

    public int[][] matrixRankTransform(int[][] matrix) {
        int m = matrix.length, n = matrix[0].length;

        // Store the rank of each element
        int[][] result = new int[m][n];

        // Create pairs (value, row, column)
        int[][] values = new int[m * n][3];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                values[i * n + j] = new int[] {matrix[i][j], i, j};
            }
        }

        // Sort the pairs by value
        Arrays.sort(values, (a, b) -> a[0] - b[0]);

        Solution dsuRow = new Solution(m);
        Solution dsuCol = new Solution(n);

        int row = 1;
        for (int[] pair : values) {
            if (pair[0] != values[row - 1][0]) {
                row++;
            }

            // Find the maximum rank of elements in the same row
            int maxRankRow = 0;
            for (int i = 0; i < m; i++) {
                if (result[i][pair[2]] > 0) {
                    maxRankRow = Math.max(maxRankRow, result[i][pair[2]]);
                    dsuRow.union(pair[1], i);
                }
            }

            // Find the maximum rank of elements in the same column
            int maxRankCol = 0;
            for (int j = 0; j < n; j++) {
                if (result[pair[1]][j] > 0) {
                    maxRankCol = Math.max(maxRankCol, result[pair[1]][j]);
                    dsuCol.union(pair[2], j);
                }
            }

            // Assign the rank to the element
            int parentRow = dsuRow.findParent(pair[1]);
            int parentCol = dsuCol.findParent(pair[2]);

            for (int i = 0; i < m; i++) {
                if (dsuRow.parent[i] == parentRow) {
                    result[i][pair[2]] = row;
                }
            }

            for (int j = 0; j < n; j++) {
                if (dsuCol.parent[j] == parentCol) {
                    result[pair[1]][j] = row;
                }
            }

            // Update the DSU
            dsuRow.union(pair[1], pair[1]);
            for (int i = 0; i < m; i++) {
                if (dsuRow.parent[i] == parentRow) {
                    result[i][pair[2]] = row;
                }
            }

            dsuCol.union(pair[2], pair[2]);
            for (int j = 0; j < n; j++) {
                if (dsuCol.parent[j] == parentCol) {
                    result[pair[1]][j] = row;
                }
            }
        }

        return result;
    }
}

