import java.util.*;

public class Solution {
    public int[][] matrixRankTransform(int[][] matrix) {
        if (matrix.length == 0 || matrix[0].length == 0) return new int[][] {};

        int m = matrix.length;
        int n = matrix[0].length;

        Map<Integer, List<int[]>> map = new HashMap<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (!map.containsKey(matrix[i][j])) {
                    map.put(matrix[i][j], new ArrayList<>());
                }
                map.get(matrix[i][j]).add(new int[] {i, j});
            }
        }

        Arrays.sort(matrix, (a, b) -> a[0] - b[0]);

        int[][] res = new int[m][n];

        for (int k : map.keySet()) {
            List<int[]> list = map.get(k);

            for (int[] pos : list) {
                int i = pos[0];
                int j = pos[1];

                int maxRank = 0;
                if (j > 0 && res[i][j - 1] != 0) {
                    maxRank = Math.max(maxRank, res[i][j - 1]);
                }
                if (i > 0 && res[i - 1][j] != 0) {
                    maxRank = Math.max(maxRank, res[i - 1][j]);
                }

                int sameRowMaxRank = 0;
                for (int p = j + 1; p < n; p++) {
                    if (matrix[i][p] == matrix[i][j]) {
                        sameRowMaxRank = Math.max(sameRowMaxRank, res[i][p]);
                    }
                }

                int sameColMaxRank = 0;
                for (int p = i + 1; p < m; p++) {
                    if (matrix[p][j] == matrix[i][j]) {
                        sameColMaxRank = Math.max(sameColMaxRank, res[p][j]);
                    }
                }

                maxRank = Math.max(maxRank, Math.max(sameRowMaxRank, sameColMaxRank));

                int rank = 0;
                for (int p = j - 1; p >= 0; p--) {
                    if (matrix[i][p] < matrix[i][j]) break;
                    rank++;
                }
                for (int p = i - 1; p >= 0; p--) {
                    if (matrix[p][j] < matrix[i][j]) break;
                    rank++;
                }

                res[i][j] = Math.max(maxRank + 1, rank);
            }
        }
        return res;
    }
}

