        int m = matrix.length, n = matrix[0].length;
        int[][] answer = new int[m][n];

        Map<Integer, Integer> rowMin = new HashMap<>();
        Map<Integer, Integer> colMin = new HashMap<>();

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                rowMin.put(r, Math.min(rowMin.getOrDefault(r, Integer.MAX_VALUE), matrix[r][c]));
                colMin.put(c, Math.min(colMin.getOrDefault(c, Integer.MAX_VALUE), matrix[r][c]));
            }
        }

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                int min = rowMin.get(r);
                if (matrix[r][c] > colMin.get(c)) {
                    answer[r][c] = matrix[r][c];
                } else if (rowMin.get(r) > colMin.get(c)) {
                    answer[r][c] = matrix[r][c];
                } else {
                    int maxRank = 0;
                    for (int i = 0; i < m; i++) {
                        if (answer[i][c] != 0 && matrix[i][c] <= matrix[r][c]) {
                            maxRank = Math.max(maxRank, answer[i][c]);
                        }
                    }
                    for (int j = 0; j < n; j++) {
                        if (answer[r][j] != 0 && matrix[r][j] <= matrix[r][c]) {
                            maxRank = Math.max(maxRank, answer[r][j]);
                        }
                    }
                    answer[r][c] = maxRank + 1;
                }
            }
        }

        return answer;
    }
}

