public class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            graph[edge[0] - 1].add(edge[1] - 1);
            graph[edge[1] - 1].add(edge[0] - 1);
        }

        int[] result = new int[n - 1];
        for (int mask = 1; mask < (1 << n); mask++) {
            List<Integer> nodes = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    nodes.add(i);
                }
            }

            boolean isConnected = true;
            for (int node : nodes) {
                if (!isConnected(graph, mask, node, -1)) {
                    isConnected = false;
                    break;
                }
            }

            if (isConnected) {
                int maxDistance = getMaxDistance(graph, mask, nodes);
                if (maxDistance > 0 && maxDistance < n) {
                    result[maxDistance - 1]++;
                }
            }
        }

        return result;
    }

    private boolean isConnected(List<Integer>[] graph, int mask, int node, int parent) {
        for (int neighbor : graph[node]) {
            if ((mask & (1 << neighbor)) != 0 && neighbor != parent) {
                if (!isConnected(graph, mask, neighbor, node)) {
                    return false;
                }
            }
        }
        return true;
    }

    private int getMaxDistance(List<Integer>[] graph, int mask, List<Integer> nodes) {
        int maxDistance = 0;
        for (int start : nodes) {
            boolean[] visited = new boolean[graph.length];
            int distance = getBFS(graph, mask, start, visited);
            if (distance > maxDistance) {
                maxDistance = distance;
            }
        }
        return maxDistance;
    }

    private int getBFS(List<Integer>[] graph, int mask, int start, boolean[] visited) {
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{start, 0});
        visited[start] = true;

        int maxDistance = 0;
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            if (current[1] > maxDistance) {
                maxDistance = current[1];
            }

            for (int neighbor : graph[current[0]]) {
                if ((mask & (1 << neighbor)) != 0 && !visited[neighbor]) {
                    visited[neighbor] = true;
                    queue.offer(new int[]{neighbor, current[1] + 1});
                }
            }
        }
        return maxDistance;
    }
}

