import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        List<Integer>[] graph = new List[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            graph[edge[0] - 1].add(edge[1] - 1);
            graph[edge[1] - 1].add(edge[0] - 1);
        }

        int[] result = new int[n - 1];

        for (int mask = 1; mask < (1 << n); mask++) {
            if (Integer.bitCount(mask) > 1) {
                List<Integer> nodes = new ArrayList<>();
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) != 0) {
                        nodes.add(i);
                    }
                }

                Map<Integer, Integer> distance = new HashMap<>();
                boolean[] visited = new boolean[n];

                int maxDistance = -1;

                for (int node : nodes) {
                    if (!visited[node]) {
                        dfs(graph, node, mask, visited, distance, 0);
                    }
                }

                for (Map.Entry<Integer, Integer> entry : distance.entrySet()) {
                    maxDistance = Math.max(maxDistance, entry.getValue());
                }

                boolean isSubtree = true;
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) != 0 && !visited[i]) {
                        isSubtree = false;
                        break;
                    }
                }

                for (int node : nodes) {
                    boolean[] visitedTemp = new boolean[n];
                    dfs(graph, node, mask, visitedTemp, distance, 0);
                    if (!isSubtree || maxDistance != distance.get(node)) {
                        isSubtree = false;
                        break;
                    }
                }

                if (isSubtree && maxDistance > 0) {
                    result[maxDistance - 1]++;
                }
            }
        }

        return result;
    }

    private void dfs(List<Integer>[] graph, int node, int mask, boolean[] visited, Map<Integer, Integer> distance, int depth) {
        visited[node] = true;
        if (distance.containsKey(node)) {
            distance.put(node, Math.max(distance.get(node), depth));
        } else {
            distance.put(node, depth);
        }

        for (int neighbor : graph[node]) {
            if ((mask & (1 << neighbor)) != 0 && !visited[neighbor]) {
                dfs(graph, neighbor, mask, visited, distance, depth + 1);
            }
        }
    }
}

