    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        List<Integer>[] graph = new List[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        // Build the graph
        for (int[] edge : edges) {
            graph[edge[0] - 1].add(edge[1] - 1);
            graph[edge[1] - 1].add(edge[0] - 1);
        }

        int[] result = new int[n - 1];

        // Iterate over all possible subsets of cities
        for (int mask = 1; mask < (1 << n); mask++) {
            List<Integer> subset = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    subset.add(i);
                }
            }

            // Check if the subset forms a connected subgraph
            if (!isConnected(subset, graph)) {
                continue;
            }

            int maxDistance = getMaxDistance(subset, graph);
            if (maxDistance > 0 && maxDistance < n) {
                result[maxDistance - 1]++;
            }
        }

        return result;
    }

    private boolean isConnected(List<Integer> subset, List<Integer>[] graph) {
        boolean[] visited = new boolean[graph.length];
        dfs(subset.get(0), subset, visited, graph);

        for (int i : subset) {
            if (!visited[i]) {
                return false;
            }
        }

        return true;
    }

    private void dfs(int node, List<Integer> subset, boolean[] visited, List<Integer>[] graph) {
        visited[node] = true;
        for (int neighbor : graph[node]) {
            if (subset.contains(neighbor) && !visited[neighbor]) {
                dfs(neighbor, subset, visited, graph);
            }
        }
    }

    private int getMaxDistance(List<Integer> subset, List<Integer>[] graph) {
        int maxDistance = 0;

        for (int start : subset) {
            boolean[] visited = new boolean[graph.length];
            int distance = bfs(start, subset, visited, graph);
            maxDistance = Math.max(maxDistance, distance);
        }

        return maxDistance;
    }

    private int bfs(int start, List<Integer> subset, boolean[] visited, List<Integer>[] graph) {
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[] {start, 0});
        visited[start] = true;

        int maxDistance = 0;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            maxDistance = Math.max(maxDistance, current[1]);

            for (int neighbor : graph[current[0]]) {
                if (subset.contains(neighbor) && !visited[neighbor]) {
                    queue.offer(new int[] {neighbor, current[1] + 1});
                    visited[neighbor] = true;
                }
            }
        }

        return maxDistance;
    }
}

