import java.util.*;

public class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int i = 0; i < n; i++) {
            graph.put(i + 1, new ArrayList<>());
        }

        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        int[] res = new int[n - 1];
        for (int mask = 1; mask < (1 << n); mask++) {
            Map<Integer, Integer> dist = new HashMap<>();
            boolean possible = true;
            for (int i = 1; i <= n; i++) {
                if ((mask & (1 << (i - 1))) != 0) {
                    if (!dfs(i, graph, dist, mask)) {
                        possible = false;
                        break;
                    }
                }
            }

            if (!possible) continue;

            int maxDist = 0;
            for (int d : dist.values()) {
                maxDist = Math.max(maxDist, d);
            }
            if (maxDist > 0 && maxDist < n) {
                res[maxDist - 1]++;
            }
        }

        return res;
    }

    private boolean dfs(int node, Map<Integer, List<Integer>> graph, Map<Integer, Integer> dist, int mask) {
        for (int neighbor : graph.get(node)) {
            if ((mask & (1 << (neighbor - 1))) != 0 && !dist.containsKey(neighbor)) {
                dist.put(neighbor, dist.getOrDefault(node, 0) + 1);
                dfs(neighbor, graph, dist, mask);
            }
        }
        return true;
    }
}

