        for (boolean b : visited) {
            if (!b) {
                return false;
            }
        }
        return true;
    }

    private void dfs(List<Integer> subset, boolean[] visited, int index, int node) {
        visited[index] = true;
        List<Integer> neighbors = graph.get(node);
        for (Integer neighbor : neighbors) {
            int newIndex = subset.indexOf(neighbor);
            if (newIndex != -1 && !visited[newIndex]) {
                dfs(subset, visited, newIndex, neighbor);
            }
        }
    }

    private int getMaxDistance(List<Integer> subset) {
        int maxDistance = 0;
        for (int i = 0; i < subset.size(); i++) {
            for (int j = i + 1; j < subset.size(); j++) {
                int distance = getDistance(subset.get(i), subset.get(j), new HashSet<>());
                if (distance > maxDistance) {
                    maxDistance = distance;
                }
            }
        }
        return maxDistance;
    }

    private int getDistance(int start, int end, Set<Integer> visited) {
        if (start == end) {
            return 0;
        }
        visited.add(start);
        List<Integer> neighbors = graph.get(start);
        for (Integer neighbor : neighbors) {
            if (!visited.contains(neighbor)) {
                int distance = getDistance(neighbor, end, visited);
                if (distance != -1) {
                    return distance + 1;
                }
            }
        }
        return -1;
    }
}

