public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numWays(String[] words, String target) {
        int[][] count = new int[26][words[0].length()];

        for (String word : words) {
            for (int i = 0; i < word.length(); i++) {
                count[word.charAt(i) - 'a'][i]++;
            }
        }

        Integer[][] memo = new Integer[target.length()][words[0].length() + 1];

        return dfs(0, 0, target, words[0].length(), count, memo);
    }

    private int dfs(int i, int k, String target, int length, int[][] count, Integer[][] memo) {
        if (i == target.length()) {
            return 1;
        }

        if (k >= length) {
            return 0;
        }

        if (memo[i][k] != null) {
            return memo[i][k];
        }

        long res = dfs(i, k + 1, target, length, count, memo);

        int index = target.charAt(i) - 'a';
        if (count[index][k] > 0) {
            res += count[index][k] * dfs(i + 1, k + 1, target, length, count, memo);
        }

        return memo[i][k] = (int) (res % MOD);
    }
}

