// #Hard #Array #String #Dynamic_Programming #2022_04_20_Time_50_ms_(95.33%)_Space_75.1_MB_(48.00%)
public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numWays(String[] words, String target) {
        int m = target.length();
        int n = words[0].length();

        long[][] dp = new long[m + 1][n];

        for (int j = 0; j < n; j++) {
            dp[0][j] = 1;
        }

        for (int i = 1; i <= m; i++) {
            int[] count = new int[26];
            for (String word : words) {
                count[word.charAt(i - 1) - 'a']++;
            }

            for (int j = 0; j < n; j++) {
                if (j > 0) {
                    dp[i][j] += dp[i][j - 1];
                    dp[i][j] %= MOD;
                }

                int charIndex = target.charAt(i - 1) - 'a';
                if (count[charIndex] > 0) {
                    long ways = count[charIndex] * dp[i - 1][j];
                    dp[i][j] += ways;
                    dp[i][j] %= MOD;
                }

                // Update the count array
                for (int k = 0; k < 26; k++) {
                    if (k != charIndex) {
                        count[k] = 0;
                    } else {
                        int updatedCount = 0;
                        for (String word : words) {
                            if (word.charAt(j) == target.charAt(i - 1)) {
                                updatedCount++;
                            }
                        }
                        count[charIndex] -= updatedCount;
                    }
                }
            }
        }

        return (int) dp[m][n - 1];
    }
}

