        for (String word : words) {
            for (int i = 0; i < word.length(); i++) {
                count[word.charAt(i) - 'a'][i]++;
            }
        }

        return dfs(count, target, 0, 0);
    }

    private int dfs(int[][] count, String target, int index, int pos) {
        if (index == target.length()) {
            return 1;
        }
        if (pos >= words[0].length()) {
            return 0;
        }

        int res = dfs(count, target, index, pos + 1);

        for (int i = 0; i < count[target.charAt(index) - 'a'].length; i++) {
            if (i == pos && count[target.charAt(index) - 'a'][pos] > 0) {
                int tmp = count[target.charAt(index) - 'a'][pos];
                count[target.charAt(index) - 'a'][pos]--;
                res = (res + dfs(count, target, index + 1, pos + 1)) % MOD;
                count[target.charAt(index) - 'a'][pos] = tmp;
            }
        }

        return res;
    }

    private static String[] words;

