public class Solution {
    public int[] getSumAbsoluteDifferences(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];

        // Calculate the total sum of all elements in the array
        long totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }

        // Initialize prefix sum and suffix sum arrays
        long[] prefixSums = new long[n + 1];
        long[] suffixSums = new long[n + 1];

        // Calculate prefix sums
        for (int i = 0; i < n; i++) {
            prefixSums[i + 1] = prefixSums[i] + nums[i];
        }

        // Calculate suffix sums
        for (int i = n - 1; i >= 0; i--) {
            suffixSums[i] = suffixSums[i + 1] + nums[i];
        }

        // Calculate result array
        for (int i = 0; i < n; i++) {
            long leftSum = prefixSums[i];
            long rightSum = totalSum - leftSum - nums[i];

            int leftCount = i;
            int rightCount = n - i - 1;

            result[i] = Math.abs(leftCount * nums[i] - leftSum) + Math.abs(rightSum - rightCount * nums[i]);
        }

        return result;
    }
}

