import java.util.Deque;
import java.util.LinkedList;

public class Solution {
    public int maxResult(int[] nums, int k) {
        Deque<int[]> deque = new LinkedList<>();
        deque.offer(new int[]{nums[0], 0});

        for (int i = 1; i < nums.length; i++) {
            // remove elements that are out of bounds from the front
            while (!deque.isEmpty() && deque.peekFirst()[1] < i - k) {
                deque.pollFirst();
            }

            int score = deque.peekFirst()[0];
            int sum = score + nums[i];

            // remove elements with smaller scores than current from the back
            while (!deque.isEmpty() && deque.peekLast()[0] <= sum) {
                deque.pollLast();
            }

            deque.offer(new int[]{sum, i});
        }

        return deque.peekLast()[0];
    }
}

