import java.util.Deque;
import java.util.LinkedList;

public class Solution {
    public int maxResult(int[] nums, int k) {
        int n = nums.length;
        int[] dp = new int[n];
        Deque<Integer> dqMax = new LinkedList<>();

        for (int i = 0; i < n; i++) {
            // remove indices out of the window
            while (!dqMax.isEmpty() && dqMax.peekFirst() < i - k) {
                dqMax.pollFirst();
            }

            if (i == 0) {
                dp[i] = nums[0];
            } else {
                dp[i] = nums[i] + dp[dqMax.peekFirst()];
            }

            // remove indices with smaller values
            while (!dqMax.isEmpty() && dp[dqMax.peekLast()] < dp[i]) {
                dqMax.pollLast();
            }

            dqMax.offerLast(i);
        }

        return dp[n - 1];
    }
}

