import java.util.PriorityQueue;

public class Solution {
    public String findLexSmallestString(String s, int a, int b) {
        HashSet<String> visited = new HashSet<>();
        PriorityQueue<String> pq = new PriorityQueue<>();

        pq.offer(s);
        visited.add(s);

        while (!pq.isEmpty()) {
            String curr = pq.poll();

            if (isAllZero(curr)) return curr;

            // add a to all odd indices
            String next1 = addA(curr, a);
            if (!visited.contains(next1)) {
                pq.offer(next1);
                visited.add(next1);
            }

            // rotate s to the right by b positions
            String next2 = rotate(curr, b);
            if (!visited.contains(next2)) {
                pq.offer(next2);
                visited.add(next2);
            }
        }

        return "";
    }

    private boolean isAllZero(String curr) {
        for (char c : curr.toCharArray()) {
            if (c != '0') return false;
        }
        return true;
    }

    private String addA(String s, int a) {
        char[] chars = s.toCharArray();
        for (int i = 1; i < chars.length; i += 2) {
            int num = chars[i] - '0' + a;
            chars[i] = (char)((num % 10) + '0');
        }
        return String.valueOf(chars);
    }

    private String rotate(String s, int b) {
        char[] chars = s.toCharArray();
        int n = chars.length;
        StringBuilder sb = new StringBuilder();

        for (int i = n - b; i < n; i++) {
            sb.append(chars[i]);
        }
        for (int i = 0; i <= n - b - 1; i++) {
            sb.append(chars[i]);
        }

        return sb.toString();
    }
}

