import java.util.HashMap;
import java.util.Map;

// #Medium #String #Hash_Table #Sorting #2022_04_23_Time_12_ms_(97.58%)_Space_59.6_MB_(39.11%)
public class Solution {
    public boolean closeStrings(String word1, String word2) {
        if (word1.length() != word2.length()) {
            return false;
        }

        Map<Character, Integer> countMap = new HashMap<>();
        for (char c : word1.toCharArray()) {
            countMap.put(c, countMap.getOrDefault(c, 0) + 1);
        }

        Map<Character, Integer> existMap = new HashMap<>();
        for (char c : word2.toCharArray()) {
            if (!countMap.containsKey(c)) {
                return false;
            }
            existMap.put(c, existMap.getOrDefault(c, 0) + 1);
        }

        if (existMap.size() != countMap.size()) {
            return false;
        }

        int[] countArr = new int[countMap.size()];
        int i = 0;
        for (int count : countMap.values()) {
            countArr[i++] = count;
        }

        int[] existArr = new int[existMap.size()];
        i = 0;
        for (int count : existMap.values()) {
            existArr[i++] = count;
        }

        Arrays.sort(countArr);
        Arrays.sort(existArr);

        for (i = 0; i < countArr.length; i++) {
            if (countArr[i] != existArr[i]) {
                return false;
            }
        }

        return true;
    }
}

