public class Solution {
    public int waysToMakeFair(int[] nums) {
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            int oddSum = 0, evenSum = 0;
            for (int j = 0; j < nums.length; j++) {
                if (j < i) {
                    if (j % 2 == 0) {
                        evenSum += nums[j];
                    } else {
                        oddSum += nums[j];
                    }
                } else if (j > i) {
                    if ((j - 1) % 2 == 0) {
                        evenSum += nums[j];
                    } else {
                        oddSum += nums[j];
                    }
                }
            }
            if (oddSum == evenSum) {
                count++;
            }
        }
        return count;
    }
}

