import java.util.*;

public class Solution {
    public int minimumMountainRemovals(int[] nums) {
        int n = nums.length;

        // Calculate longest increasing subsequence
        int[] lis = new int[n];
        for (int i = 0; i < n; i++) {
            lis[i] = 1;
            for (int j = 0; j < i; j++) {
                if (nums[j] < nums[i]) {
                    lis[i] = Math.max(lis[i], lis[j] + 1);
                }
            }
        }

        // Calculate longest decreasing subsequence
        int[] lds = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            lds[i] = 1;
            for (int j = n - 1; j > i; j--) {
                if (nums[j] < nums[i]) {
                    lds[i] = Math.max(lds[i], lds[j] + 1);
                }
            }
        }

        // Calculate minimum number of elements to remove
        int minRemovals = n;
        for (int i = 0; i < n; i++) {
            if (lis[i] > 1 && lds[i] > 1) {
                minRemovals = Math.min(minRemovals, n - lis[i] - lds[i] + 1);
            }
        }

        return minRemovals;
    }
}

