public class Solution {
    public int stoneGameVII(int[] stones) {
        int n = stones.length;
        int[][] dp = new int[n][n];

        // Calculate prefix sum for efficient calculation of remaining stones' values.
        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + stones[i];
        }

        // Initialize dp array with base cases where only one stone is left.
        for (int i = 0; i < n - 1; i++) {
            dp[i][i + 1] = Math.max(stones[i], stones[i + 1]);
        }

        // Fill up the dp array using dynamic programming and game theory principles.
        for (int len = 3; len <= n; len++) {
            for (int left = 0; left <= n - len; left++) {
                int right = left + len - 1;

                // Calculate remaining stones' values if the leftmost stone is removed.
                int removeLeft = prefixSum[right + 1] - prefixSum[left + 1];

                // Calculate remaining stones' values if the rightmost stone is removed.
                int removeRight = prefixSum[right] - prefixSum[left];

                // Apply game theory principles to maximize Alice's score and minimize Bob's score.
                dp[left][right] = Math.max(removeLeft - dp[left + 1][right], removeRight - dp[left][right - 1]);
            }
        }

        return dp[0][n - 1];
    }
}

