        int maxRequestCount = 0;
        Map<Integer, Integer> requestCounts = new HashMap<>();

        TreeSet<Server> busy = new TreeSet<>(Comparator.comparingInt(a -> a.busyTime).thenComparingInt(a -> a.id));

        for (int i = 0; i < arrival.length; i++) {
            int arrTime = arrival[i];
            while (!busy.isEmpty() && busy.first().busyTime <= arrTime) {
                Server s = busy.pollFirst();
                available.offer(s);
            }

            if (available.isEmpty()) continue;

            Server server;
            // Try to assign request to the ith server
            for (int j = i % k; ; j = (j + 1) % k) {
                server = new Server(j, -1);
                if (!available.remove(server)) continue;
                available.offer(server);

                busy.add(new Server(server.id, arrTime + load[i]));
                requestCounts.put(server.id, requestCounts.getOrDefault(server.id, 0) + 1);
                break;
            }
        }

        for (int server : requestCounts.keySet()) {
            if (requestCounts.get(server) > maxRequestCount) {
                busiest.clear();
                maxRequestCount = requestCounts.get(server);
                busiest.add(server);
            } else if (requestCounts.get(server) == maxRequestCount) {
                busiest.add(server);
            }
        }

