public class Solution {
    public List<Integer> busiestServers(int k, int[] arrival, int[] load) {
        PriorityQueue<int[]> busy = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        TreeSet<Integer> available = new TreeSet<>();
        for (int i = 0; i < k; i++) {
            available.add(i);
        }

        Server[] servers = new Server[k];
        for (int i = 0; i < k; i++) {
            servers[i] = new Server(i, 0);
        }

        for (int i = 0; i < arrival.length; i++) {
            while (!busy.isEmpty() && busy.peek()[0] <= arrival[i]) {
                available.add(busy.poll()[1]);
            }

            if (available.isEmpty()) {
                continue;
            }

            Integer nextServer = available.ceiling(i % k);
            if (nextServer == null) {
                nextServer = available.first();
            }

            servers[nextServer].handled++;
            busy.offer(new int[] { arrival[i] + load[i], nextServer });
            available.remove(nextServer);
        }

        int maxHandled = 0;
        for (int i = 0; i < k; i++) {
            maxHandled = Math.max(maxHandled, servers[i].handled);
        }

        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            if (servers[i].handled == maxHandled) {
                result.add(servers[i].id);
            }
        }

        return result;
    }

    public static class Server {
        int id;
        int handled;

        public Server(int id, int busyTime) {
            this.id = id;
            this.handled = 0;
        }
    }
}

