// #Hard #Dynamic_Programming #Bit_Manipulation #Memoization
// #2022_04_12_Time_1_ms_(88.24%)_Space_39.5_MB_(84.80%)
import java.util.LinkedList;

public class Solution {
    public int minimumOneBitOperations(int n) {
        LinkedList<Integer> bits = new LinkedList<>();

        while (n > 0) {
            bits.add(n % 2);
            n /= 2;
        }

        boolean[] visited = new boolean[bits.size()];
        return dfs(bits, 0, visited);
    }

    private int dfs(LinkedList<Integer> bits, int index, boolean[] visited) {
        if (index >= bits.size()) {
            return 0;
        }
        if (visited[index]) {
            return Integer.MAX_VALUE / 2;
        }

        visited[index] = true;

        if (bits.get(index) == 1 && index > 0 && bits.get(index - 1) == 0) {
            return dfs(bits, index + 1, visited);
        } else if (index > 1 && bits.get(index) == 1) {
            int count = 2;
            for (int i = index - 2; i >= 0; i--) {
                if (bits.get(i) == 0) {
                    break;
                }
                count++;
            }
            return dfs(bits, index + count, visited);
        } else {
            return 1 + dfs(bits, index + 1, visited);
        }
    }
}

