            // Iterate through the sorted list of times and check for overlapping intervals
            for (int i = 2; i < entry.getValue().size(); i++) {
                if (entry.getValue().get(i) - entry.getValue().get(i - 2) <= 60) {
                    result.add(entry.getKey());
                    break;
                }
            }
        }

        Collections.sort(result);

        return result;
    }

    // Helper function to convert time from "HH:MM" format to minutes
    private int convertToMinutes(String time) {
        String[] parts = time.split(":");
        return Integer.parseInt(parts[0]) * 60 + Integer.parseInt(parts[1]);
