import java.util.Arrays;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int maxProfit(int[] inventory, int orders) {
        Arrays.sort(inventory);
        long res = 0;

        for (int i = inventory.length - 1; i >= 0 && orders > 0; i--) {
            if (i == 0 || inventory[i] != inventory[i - 1]) {
                int count = 1;
                while (i - count >= 0 && inventory[i - count] == inventory[i]) {
                    count++;
                }

                long ballsToSell = Math.min(orders, inventory[i] * count);
                res += calculateProfit(inventory[i], ballsToSell / count) * count;
                orders -= ballsToSell;
            } else {
                continue;
            }
        }

        return (int) (res % MOD);
    }

    private long calculateProfit(int initialBalls, int ballsToSell) {
        long sum = 0;
        for (int i = initialBalls; i > initialBalls - ballsToSell; i--) {
            sum += i;
        }

        return sum;
    }
}

