import java.util.Arrays;

public class Solution {
    private static final int MOD = 1000000007;

    public int maxProfit(int[] inventory, int orders) {
        Arrays.sort(inventory);
        long result = 0;

        for (int i = 0; i < inventory.length; i++) {
            if (i > 0 && inventory[i] != inventory[i - 1]) {
                int count = i;
                int diff = inventory[i] - inventory[i - 1];

                while (orders >= count * diff) {
                    result += count * (inventory[i] + inventory[i] - diff + 1) / 2 * diff;
                    result %= MOD;

                    orders -= count * diff;
                    inventory[i] -= diff;
                }
            }
        }

        int n = inventory.length;
        long count = n;
        long diff = inventory[n - 1];

        while (orders > 0) {
            if (diff == 0) break;

            long sell = Math.min(orders / count, diff);
            result += count * (inventory[n - 1] + inventory[n - 1] - sell + 1) / 2 * sell;
            result %= MOD;

            orders -= count * sell;
            diff--;
        }

        return (int) result;
    }
}

