import java.util.Arrays;

public class Solution {
    public int maxProfit(int[] inventory, int orders) {
        Arrays.sort(inventory);
        int i = 0;
        long res = 0;
        while (orders > 0 && i < inventory.length) {
            if (i + 1 == inventory.length || orders >= inventory[i + 1] - inventory[i]) {
                long sold = orders / (inventory.length - i);
                long remaining = orders % (inventory.length - i);
                for (int j = i; j < inventory.length; j++) {
                    res += (long) (inventory[j] + inventory[j] - sold + 1) * sold / 2;
                }
                if (remaining > 0) {
                    for (int j = 0; j < remaining; j++) {
                        res += inventory[i + j];
                    }
                }
                break;
            } else {
                long sold = orders / (i + 1);
                long remaining = orders % (i + 1);
                for (int j = i; j >= 0; j--) {
                    if (sold > 0) {
                        res += (long) (inventory[j] + inventory[i] + 1) * sold / 2;
                        sold--;
                    }
                    inventory[j]--;
                    orders--;
                }
            }
        }
        return (int) (res % (1000000007));
    }
}

