import java.util.Arrays;
public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int maxProfit(int[] inventory, int orders) {
        Arrays.sort(inventory);
        long res = 0;
        for (int i = 0; i < inventory.length; ++i) {
            if (orders == 0) break;
            int curCnt = inventory[i];
            int prevCnt = (i > 0 ? inventory[i - 1] : 0);
            int diffCnt = curCnt - prevCnt;

            long times = Math.min(orders, diffCnt * (inventory.length - i));
            orders -= times;
            res += sum(curCnt, curCnt - times / (inventory.length - i)) % MOD * ((long) (inventory.length - i)) % MOD;
            if (times % (inventory.length - i) != 0) {
                int next = (curCnt - times / (inventory.length - i));
                orders -= inventory.length - i;
                res += sum(next, next - (orders / (inventory.length - i))) % MOD * ((long) (inventory.length - i)) % MOD;
            }
        }

        return (int) (res % MOD);
    }

    private long sum(int start, int end) {
        if (end > start)
            return (start + end) * (long) (end - start + 1) / 2L;
        else
            return 0;
    }
}

