        // Create adjacency list representation of graph
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        // Populate the adjacency list
        for (int[] road : roads) {
            int u = road[0];
            int v = road[1];
            graph[u].add(v);
            graph[v].add(u);
        }

        // Calculate network rank for each pair of cities
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int rank = 0;

                // Count the number of roads directly connected to city i or city j
                Set<Integer> neighborsI = new HashSet<>(graph[i]);
                Set<Integer> neighborsJ = new HashSet<>(graph[j]);
                rank += neighborsI.size();
                rank += neighborsJ.size();

                // Subtract the common neighbor (the road between cities i and j) if it exists
                if (neighborsI.contains(j)) {
                    rank--;
                }

                maxRank = Math.max(maxRank, rank);
            }
        }

        return maxRank;
    }
}

