        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int rank = graph.get(i).size() + graph.get(j).size();

                // Subtract the intersection to avoid counting roads twice
                Set<Integer> intersection = new HashSet<>(graph.get(i));
