        int[] cityRoads = new int[n];

        // Create an adjacency matrix to store connections between cities
        boolean[][] is Connected = new boolean[n][n];

        for (int[] road : roads) {
            cityRoads[road[0]]++;
            cityRoads[road[1]]++;
            isConnected[road[0]][road[1]] = true;
            isConnected[road[1]][road[0]] = true;
        }

        int maxNetworkRank = 0;

        // Iterate over all pairs of cities
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                // Calculate the network rank of the current pair of cities
                int networkRank = cityRoads[i] + cityRoads[j];

                // Subtract the duplicate connection if it exists
                if (isConnected[i][j]) {
                    networkRank--;
                }

                maxNetworkRank = Math.max(maxNetworkRank, networkRank);
            }
        }

        return maxNetworkRank;
    }
}

