            count[a + 1]--;
            count[a + b]--;
            count[a + b + 1]++;
        }

        for (int i = 2; i <= 2 * limit; i++) {
            count[i] += count[i - 1];
        }

        int minMoves = Integer.MAX_VALUE;
        for (int i = 2; i <= 2 * limit; i++) {
            minMoves = Math.min(minMoves, count[i]);
        }

        return minMoves;
    }
