public class Solution {
    public int countBinarySubstrings(String s) {
        int count = 0;
        for (int i = 0; i < s.length(); ) {
            char c = s.charAt(i);
            int ones = 0, zeros = 0;
            while (i < s.length() && s.charAt(i) == c) {
