    private boolean isConsecutive(String s) {
        int zeros = 0;
        int ones = 0;
        for (char c : s.toCharArray()) {
            if (c == '0') {
                zeros++;
            } else {
                ones++;
            }
        }
        if (zeros != ones || zeros == 0 || ones == 0) {
            return false;
        }

        boolean seenZero = false;
        boolean seenOne = false;
        char prevChar = s.charAt(0);
        for (char c : s.substring(1).toCharArray()) {
            if ((c == '0' && !seenZero && prevChar != '0') || 
                (c == '1' && !seenOne && prevChar != '1')) {
                return false;
            }
            seenZero = seenZero || c == '0';
            seenOne = seenOne || c == '1';
            if ((prevChar == '0' && c == '0') || 
                (prevChar == '1' && c == '1')) {
                continue;
            } else {
                prevChar = c;
            }
        }

        return true;
    }
}

