import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int minStickers(String[] stickers, String target) {
        Map<Character, Integer> charToIndex = new HashMap<>();

        // count the characters of every sticker
        for (int i = 0; i < stickers.length; i++) {
            for (char c : stickers[i].toCharArray()) {
                if (!charToIndex.containsKey(c)) {
                    charToIndex.put(c, i);
                }
            }
        }

        Map<String, Integer> memo = new HashMap<>();
        return dfs(stickers, target, memo);
    }

    private int dfs(String[] stickers, String target, Map<String, Integer> memo) {
        if (memo.containsKey(target)) {
            return memo.get(target);
        }

        if (target.isEmpty()) {
            return 0;
        }

        int ans = Integer.MAX_VALUE;
        for (String sticker : stickers) {
            StringBuilder sb = new StringBuilder(target);
            for (char c : sticker.toCharArray()) {
                int index = sb.indexOf(String.valueOf(c));
                while (index != -1) {
                    sb.deleteCharAt(index);
                    index = sb.indexOf(String.valueOf(c));
                }
            }

            if (sb.length() < target.length()) {
                int res = dfs(stickers, sb.toString(), memo);
                if (res != -1) {
                    ans = Math.min(ans, 1 + res);
                }
            }
        }

        memo.put(target, ans == Integer.MAX_VALUE ? -1 : ans);
        return memo.get(target);
    }
}

