// #2022_03_22_Time_34_ms_(70.23%)_Space_54.1_MB_(35.88%)
import java.util.HashMap;
import java.util.HashSet;

public class Solution {
    // count the characters of every sticker
    // For each character, save the sticker index which has this character
    public int minStickers(String[] stickers, String target) {
        HashMap<Character, Integer> map = new HashMap<>();
        for (int i = 0; i < target.length(); i++) {
            map.put(target.charAt(i), map.getOrDefault(target.charAt(i), 0) + 1);
        }

        int[][] freqs = new int[stickers.length][26];
        for (int i = 0; i < stickers.length; i++) {
            for (char c : stickers[i].toCharArray()) {
                freqs[i][c - 'a']++;
            }
        }

        HashMap<String, Integer> memo = new HashMap<>();
        return dfs(map, freqs, memo);
    }

    private int dfs(HashMap<Character, Integer> map, int[][] freqs, HashMap<String, Integer> memo) {
        String key = getStringFromMap(map);
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        if (map.isEmpty()) {
            return 0;
        }

        int min = Integer.MAX_VALUE;
        for (int[] freq : freqs) {
            HashMap<Character, Integer> nextMap = getNextMap(map, freq);
            if (!nextMap.equals(map)) {
                min = Math.min(min, dfs(nextMap, freqs, memo));
            }
        }

        memo.put(key, min == Integer.MAX_VALUE ? -1 : min + 1);
        return memo.get(key);
    }

    private HashMap<Character, Integer> getNextMap(HashMap<Character, Integer> map, int[] freq) {
        HashMap<Character, Integer> nextMap = new HashMap<>(map);
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0 && nextMap.containsKey((char)(i + 'a'))) {
                nextMap.put((char)(i + 'a'), Math.max(0, nextMap.get((char)(i + 'a')) - freq[i]));
                if (nextMap.get((char)(i + 'a')) == 0) {
                    nextMap.remove((char)(i + 'a'));
                }
            }
        }
        return nextMap;
    }

    private String getStringFromMap(HashMap<Character, Integer> map) {
        StringBuilder sb = new StringBuilder();
        for (char c : map.keySet()) {
            sb.append(c);
        }
        return sb.toString();
    }
}

