import java.util.*;

public class Solution {
    public int minStickers(String[] stickers, String target) {
        int n = stickers.length;
        int[][] cnt = new int[n][26];

        for (int i = 0; i < n; i++) {
            for (char c : stickers[i].toCharArray()) {
                cnt[i][c - 'a']++;
            }
        }

        HashMap<Integer, Integer> memo = new HashMap<>();
        return dfs(target, cnt, memo);
    }

    public int dfs(String target, int[][] cnt, HashMap<Integer, Integer> memo) {
        int mask = 0;
        for (int i = 0; i < target.length(); i++) {
            mask |= 1 << i;
        }

        if (!memo.containsKey(mask)) {
            int ans = Integer.MAX_VALUE;
            if (mask == 0) ans = 0;

            outer:
            for (int i = 0; i < cnt.length; i++) {
                int m = mask;
                for (char c : target.toCharArray()) {
                    if ((m & (1 << target.indexOf(c))) != 0 && cnt[i][c - 'a'] > 0) {
                        m ^= 1 << target.indexOf(c);
                        cnt[i][c - 'a']--;
                    }
                }

                int tmp = dfs(Integer.toBinaryString(m), cnt, memo);
                if (tmp == -1) continue outer;
                ans = Math.min(ans, 1 + tmp);

                for (char c : target.toCharArray()) {
                    if ((mask & (1 << target.indexOf(c))) != 0 && cnt[i][c - 'a'] > 0) {
                        cnt[i][c - 'a']++;
                    }
                }
            }

            memo.put(mask, ans == Integer.MAX_VALUE ? -1 : ans);
        }

        return memo.get(mask);
    }

    private String IntegerToBinaryString(int num, int length) {
        StringBuilder binary = new StringBuilder();
        while (num > 0) {
            if ((num & 1) != 0) {
                binary.append('1');
            } else {
                binary.append('0');
            }
            num >>= 1;
        }

        return String.format("%" + length + "s", binary.toString()).replace(' ', '0');
    }

    public int dfs(String mask, int[][] cnt, HashMap<Integer, Integer> memo) {
        char[] arr = new char[26];
        for (char c : mask.toCharArray()) {
            if (c == '1') continue;
            arr[c - 'a']++;
        }

        StringBuilder target = new StringBuilder();
        for (int i = 0; i < arr.length; i++) {
            while (arr[i]-- > 0) {
                target.append((char)(i + 'a'));
            }
        }

        int[] cntTarget = new int[26];
        for (char c : target.toString().toCharArray()) {
            cntTarget[c - 'a']++;
        }

        return dfs(target.toString(), cnt, memo);
    }
}

