        if (n < 3 * k) return new int[0];

        // Calculate prefix sum
        long[] prefixSum = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }

        // Function to calculate the sum of a subarray in O(1) time
        int sum(int l, int r) {
            return (int) (prefixSum[r + 1] - prefixSum[l]);
        }

        long maxSum = Long.MIN_VALUE;
        int[] res = new int[3];
        for (int i = 0; i <= n - 3 * k; i++) {
            for (int j = i + k; j <= n - 2 * k; j++) {
                for (int m = j + k; m <= n - k; m++) {
                    long currSum = sum(i, i + k - 1) + sum(j, j + k - 1) + sum(m, m + k - 1);
                    if (currSum > maxSum || (currSum == maxSum && (i < res[0] || (i == res[0] && j < res[1]) || (i == res[0] && j == res[1] && m < res[2])))) {
                        maxSum = currSum;
                        res[0] = i;
                        res[1] = j;
                        res[2] = m;
                    }
                }
            }
        }
        return res;
    }
}

