public class Solution {
    public int[] maxSumOfThreeSubarrays(int[] nums, int k) {
        int n = nums.length;
        int[][] sum = new int[n + 1][n];

        // calculate prefix sum for subarray of length k
        for (int i = 0; i < n - k + 1; i++) {
            int currentSum = 0;
            for (int j = i; j < i + k; j++) {
                currentSum += nums[j];
            }
            sum[1][i] = currentSum;
        }

        // calculate prefix sum for subarray of length k for every position
        for (int i = 2; i <= n - k + 1; i++) {
            for (int j = 0; j < n - k + 1; j++) {
                if (j == 0) {
                    sum[i][j] = sum[i - 1][j];
                } else {
                    sum[i][j] = Math.max(sum[i - 1][j], sum[i - 1][j - 1]);
                }
            }
        }

        int maxSum = Integer.MIN_VALUE;
        int[] result = new int[3];

        // check every possible position for three subarrays
        for (int i = 0; i < n - k + 1; i++) {
            for (int j = i + k; j < n - k + 1; j++) {
                for (int m = j + k; m < n - k + 1; m++) {
                    int currentSum = sum[1][i] + sum[1][j] + sum[1][m];
                    if (currentSum > maxSum) {
                        maxSum = currentSum;
                        result[0] = i;
                        result[1] = j;
                        result[2] = m;
                    } else if (currentSum == maxSum) {
                        // in case of a tie, choose the lexicographically smallest one
                        int[] temp = {i, j, m};
                        for (int p = 0; p < 3; p++) {
                            if (temp[p] < result[p]) {
                                result[0] = i;
                                result[1] = j;
