// #Hard #Math #Binary_Search #2022_03_22_Time_12_ms_(97.84%)_Space_39.1_MB_(74.34%)
public class Solution {
    public int findKthNumber(int m, int n, int k) {
        int left = 1;
        int right = m * n;

        while (left < right) {
            int mid = left + (right - left) / 2;
            if (!isEnough(mid, m, n, k)) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        return left;
    }

    private boolean isEnough(int target, int m, int n, int k) {
        int count = 0;

        for (int i = 1; i <= m; i++) {
            count += Math.min(target / i, n);
        }

        return count >= k;
    }
}

