public class Solution {
    private static final char[] ops = {'+', '-', '*', '/'};

    public boolean judgePoint24(int[] cards) {
        return dfs(cards, 0);
    }

    private boolean dfs(int[] cards, int start) {
        if (start == 3) {
            return Math.abs(cards[3] - 24.0) < 0.001;
        }

        for (int i = start; i < cards.length - 1; i++) {
            for (int j = i + 1; j < cards.length; j++) {
                int[] next = new int[cards.length];
                System.arraycopy(cards, 0, next, 0, cards.length);

                for (char op : ops) {
                    double result;

                    switch (op) {
                        case '+':
                            result = next[i] + next[j];
                            break;
                        case '-':
                            result = next[i] - next[j];
                            break;
                        case '*':
                            result = next[i] * next[j];
                            break;
                        default:
                            if (next[j] == 0) {
                                continue;
                            }
                            result = next[i] / next[j];
                    }

                    next[start] = (int) result;
                    next[j] = next[cards.length - 1];
                    next[cards.length - 1] = 0;

                    if (dfs(next, start + 1)) {
                        return true;
                    }
                }
            }
        }

