        int[] ans = new int[n];
        int[] heights = new int[positions.length * 2];

        for (int i = 0; i < n; i++) {
            int left = positions[i][0], sideLength = positions[i][1];
            int right = left + sideLength;
            int max_height = 0;

            // find the height of overlapping intervals
            for (int j = 0; j < i; j++) {
                if (positions[j][0] < right && positions[j][0] + positions[j][1] > left) {
                    max_height = Math.max(max_height, heights[j]);
                }
            }

            // update the height of the current interval
            int currHeight = max_height + sideLength;
            for (int j = 0; j < i; j++) {
                if (positions[j][0] < right && positions[j][0] + positions[j][1] > left) {
                    heights[j] = Math.max(heights[j], currHeight);
                }
            }

            // update the height of the current square
            heights[i] = currHeight;

            // calculate the global max
            int globalMax = 0;
            for (int j = 0; j <= i; j++) {
                globalMax = Math.max(globalMax, heights[j]);
            }
            ans[i] = globalMax;
        }

        return ans;
    }
