public class Solution {
    public int[] fallingSquares(int[][] positions) {
        List<Integer> ans = new ArrayList<>();
        Map<Integer, Integer> map = new HashMap<>();

        for (int[] position : positions) {
            int left = position[0];
            int right = position[0] + position[1];
            int newHeight = 0;

            for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
                if (!(right <= entry.getKey() || left >= entry.getKey() + position[1])) {
                    newHeight = Math.max(newHeight, entry.getValue());
                }
            }

            newHeight += position[1];

            int startKey = left;
            while (map.containsKey(startKey)) {
                startKey++;
            }
            map.put(startKey, newHeight);

            for (int i = startKey - 1; i >= left && map.containsKey(i); i--) {
                if (i + position[1] > startKey) {
                    map.remove(i);
                }
            }

            int maxH = Integer.MIN_VALUE;
            for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
                maxH = Math.max(maxH, entry.getValue());
            }

            ans.add(maxH);
        }

        int[] result = new int[ans.size()];
        for (int i = 0; i < ans.size(); i++) {
            result[i] = ans.get(i);
        }
        return result;
