        for (int i = 0; i <= n; i++) {
            dp[i][i] = true;
        }

        int idx = -1;
        for (char c : chars) {
            if (c != '*') {
                idx++;
                for (int j = idx - 1; j >= 0; j--) {
                    if (chars[j] == c) {
                        dp[j][idx] = true;
                    }
                }

                int i = 0, j = 0;
                while (i < n && chars[i] != c) {
                    i++;
                }
                while (j <= idx && !dp[0][j]) {
                    j++;
                }

                for (; i < n; i++) {
                    if (chars[i] == c) {
                        int k = 0;
                        while (k <= j && dp[k][i - 1]) {
                            dp[k][idx] = true;
                            k++;
                        }
                    } else {
                        i--;
                        break;
                    }
                }
            }
        }

        for (int i = n; i >= 0; i--) {
            if (dp[0][i]) {
                return idx - i + 1;
            }
        }

