public class Solution {
    public int flipLights(int n, int presses) {
        if (n == 0 || presses == 0) return 1;
        if (n == 1) return presses > 0 ? 2 : 1;
        if (n == 2) return presses > 1 ? 4 : Math.min(presses + 1, 3);
        if (presses >= 3) return 8;
        int[] status = new int[16];
        for (int i = 0; i < 16; i++) {
            status[i] = -1;
        }
        dfs(status, presses, n, 0);
        int count = 0;
        for (int i : status) {
            if (i != -1) count++;
        }
        return count;
    }

    private void dfs(int[] status, int presses, int n, int curStatus) {
        if (presses == 0) {
            int code = encode(curStatus, n);
            for (int i = 0; i < 16; i++) {
                if (status[i] == -1 || status[i] == code) {
                    status[i] = code;
                    return;
                }
            }
        } else {
            dfs(status, presses - 1, n, curStatus);
            dfs(status, presses - 1, n, flipAll(curStatus));
            dfs(status, presses - 1, n, flipEven(curStatus));
            dfs(status, presses - 1, n, flipOdd(curStatus));
            dfs(status, presses - 1, n, flip3kPlus1(curStatus));
        }
    }

    private int encode(int status, int n) {
        int code = 0;
        for (int i = 0; i < Math.min(4, n); i++) {
            if ((status & (1 << i)) != 0) {
                code |= (1 << i);
            }
        }
        return code;
    }

    private int flipAll(int status) {
        return ~status & ((1 << 16) - 1);
    }

    private int flipEven(int status) {
        return status ^ (2 | 4 | 8);
    }

    private int flipOdd(int status) {
        return status ^ (1 | 5 | 9);
    }

    private int flip3kPlus1(int status) {
        return status ^ (1 | 4 | 7 | 10 | 13);
    }
}

