// #2022_03_22_Time_0_ms_(100.00%)_Space_38.9_MB_(80.85%)
public class Solution {
    public int flipLights(int n, int presses) {
        if (n == 0 || presses == 0) return 1;
        if (n == 1) return Math.min(presses, 2);
        if (n == 2) {
            if (presses >= 3) return 4;
            else return Math.min(presses + 1, 4);
        }
        if (presses >= 4) return 8;
        boolean[][] seen = new boolean[16][16];
        int[] status = new int[n];
        for (int i = 0; i < n; i++) {
            status[i] = 1;
        }
        press(status, presses, seen);
        int count = getUnique(seen);
        return count;
    }

    private void press(int[] status, int presses, boolean[][] seen) {
        if (presses == 0) {
            record(seen, status);
        } else {
            for (int i = 1; i <= 4; i++) {
                flip(status, i);
                press(status, presses - 1, seen);
                flip(status, i); // undo
            }
        }
    }

    private void record(boolean[][] seen, int[] status) {
        int index0 = 0;
        for (int i = 0; i < status.length && i < 6; i++) {
            index0 += status[i] << i;
        }
        int index1 = 0;
        for (int i = status.length - 1; i >= status.length - 6 && i > 5; i--) {
            index1 += status[i] << (status.length - i - 1);
        }
        seen[index0][index1] = true;
    }

    private int getUnique(boolean[][] seen) {
        int count = 0;
        for (boolean[] booleans : seen) {
            for (boolean aBoolean : booleans) {
                if (aBoolean) count++;
            }
        }
        return count;
    }

    private void flip(int[] status, int button) {
        switch (button) {
            case 1:
                for (int i = 0; i < status.length; i++) {
                    status[i] ^= 1;
                }
                break;
            case 2:
                for (int i = 1; i < status.length; i += 2) {
                    status[i] ^= 1;
                }
                break;
            case 3:
                for (int i = 0; i < status.length; i += 2) {
                    status[i] ^= 1;
                }
                break;
            case 4:
                for (int k = 0, j = 3 * k + 1; j < status.length; k++, j = 3 * k + 1) {
                    status[j] ^= 1;
                }
        }
    }
}

