// #2022_03_22_Time_0_ms_(100.00%)_Space_38.9_MB_(80.85%)
public class Solution {
    public int flipLights(int n, int presses) {
        if (n == 0 || presses == 0) return 1;
        if (n == 1) return presses >= 1 ? 2 : 1;
        if (n == 2) return presses >= 2 ? 4 : presses + 1;

        int[] masks = {0, ~0, (~0 / 3 * 2), ~(~0 / 3)};
        Set<Integer> seen = new HashSet<>();
        seen.add(0);

        for (int i = 0; i < presses; i++) {
            Set<Integer> next = new HashSet<>();
            for (Integer x : seen) {
                for (int mask : masks) {
                    int y = x ^ mask;
                    if (y >= 0 && (1 << n) - 1 == ~(~(1 << n) - 1 | y)) next.add(y);
                }
            }
            seen = next;
        }

        return seen.size();
    }
}

