import com_github_leetcode.Employee;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public int getImportance(List<Employee> employees, int id) {
        Map<Integer, Employee> employeeMap = new HashMap<>();

        // Create a map of employee IDs to their corresponding Employee objects
        for (Employee employee : employees) {
            employeeMap.put(employee.id, employee);
        }

        return dfs(id, employeeMap);
    }

    private int dfs(int id, Map<Integer, Employee> employeeMap) {
        Employee currentEmployee = employeeMap.get(id);

        // Base case: if the employee has no subordinates
        int importance = currentEmployee.importance;

        // Recursively calculate the importance of each subordinate
        for (int subordinateId : currentEmployee.subordinates) {
            importance += dfs(subordinateId, employeeMap);
        }

        return importance;
    }
}

