public class Solution {
    public String solveEquation(String equation) {
        int leftX = 0, rightX = 0;
        int leftValue = 0, rightValue = 0;

        boolean leftSide = true;
        int sign = 1;
        StringBuilder numBuilder = new StringBuilder();

        for (int i = 0; i < equation.length(); i++) {
            char c = equation.charAt(i);

            if (Character.isDigit(c)) {
                numBuilder.append(c);
            } else {
                if (numBuilder.length() > 0) {
                    int value = Integer.parseInt(numBuilder.toString());

                    if (!leftSide || equation.charAt(i - 1) == 'x') {
                        leftValue += sign * value;
                    }

                    numBuilder.setLength(0);
                }

                switch (c) {
                    case '+':
                        sign = 1;
                        break;
                    case '-':
                        sign = -1;
                        break;
                    case '=':
                        leftSide = false;
                        sign = 1;
                        break;
                    case 'x':
                        if (!leftSide || equation.charAt(i - 1) == '-') {
                            leftX += sign * (numBuilder.length() > 0 ? -Integer.parseInt(numBuilder.toString()) : -1);
                            numBuilder.setLength(0);
                        } else if (equation.charAt(i - 1) != '+') {
                            leftX += sign;
                        }
                }
            }
        }

        // handle last number
        if (numBuilder.length() > 0 && !leftSide) {
            rightValue = Integer.parseInt(numBuilder.toString()) * sign;
        } else if (!leftSide && equation.charAt(equation.length() - 1) == 'x') {
            rightX += sign * (numBuilder.length() > 0 ? -Integer.parseInt(numBuilder.toString()) : -1);
        }

        // calculate the result
        int xCoeff = leftX;
        int constant = -rightValue + leftValue;

        if (xCoeff == 0) {
            return constant == 0 ? "Infinite solutions" : "No solution";
        } else {
            int x = constant / xCoeff;

            return "x=" + x;
        }
    }
}

