public class Solution {
    public String solveEquation(String equation) {
        int index = equation.indexOf('=');
        String left = equation.substring(0, index), right = equation.substring(index + 1);

        int[] l = parse(left);
        int[] r = parse(right);

        int a = l[0] - r[0];
        int b = r[1] - l[1];

        if (a == 0 && b != 0) return "No solution";
        else if (a == 0 && b == 0) return "Infinite solutions";

        return "x=" + (b / a);
    }

    private int[] parse(String s) {
        boolean hasX = false;
        int sign = 1, coefficient = 0, constant = 0;

        for (int i = 0; i < s.length(); ) {
            if (s.charAt(i) == '-') {
                sign = -1;
                i++;
            } else if (s.charAt(i) == '+') {
                sign = 1;
                i++;
            }

            int start = i;

            hasX = false;
            while (i < s.length() && Character.isDigit(s.charAt(i))) i++;

            if (i < s.length() && s.charAt(i) == 'x') {
                hasX = true;
                i++;
            }

            if (hasX) {
                int c = 0;
                if (start != i - 1) c = Integer.parseInt(s.substring(start, i - 1));
                coefficient += sign * (c == 0 ? 1 : c);
            } else {
                constant += sign * Integer.parseInt(s.substring(start, i));
            }
        }

        return new int[] {coefficient, constant};
    }
}

