                parent[edge[1]] = edge[0];
            } else {
                candidate1 = new int[] {parent[edge[1]], edge[1]};
                candidate2 = new int[] {edge[0], edge[1]};
            }
        }

        // If no node has two parents, the last edge is redundant
        if (candidate1 == null) {
            return edges[n - 1];
        }

        // Build the graph and perform DFS to check for cycles
        int[] graph = new int[n + 1];
        boolean[] visited = new boolean[n + 1];
        for (int i = 0; i < n; i++) {
            if (!candidate2.equals(edges[i])) {
                graph[edges[i][0]] = edges[i][1];
            }
        }

        // Check if removing candidate1 will break the cycle
        int root = -1;
        boolean cycle = false;
        for (int i = 1; i <= n; i++) {
            if (!visited[i]) {
                if (hasCycle(graph, visited, i)) {
                    cycle = true;
                    break;
                }
                if (root == -1) {
                    root = i;
                }
            }
        }

        // If removing candidate1 breaks the cycle, return it
        if (cycle) {
            return candidate1;
        } else {
            return candidate2;
        }
    }

    private boolean hasCycle(int[] graph, boolean[] visited, int node) {
        if (visited[node]) {
            return true;
        }
        if (graph[node] == 0) {
            return false;
        }

        visited[node] = true;
        if (hasCycle(graph, visited, graph[node])) {
            return true;
        }
        visited[node] = false;
        return false;
    }
}

