public class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        int[] parent = new int[n + 1];

        // Find the node with two parents
        for (int i = 0; i < n; i++) {
            if (parent[edges[i][1]] != 0) {
                return findCycle(edges, parent, edges[i][1]);
            }
            parent[edges[i][1]] = edges[i][0];
        }

        // If no node with two parents is found, then there must be a cycle
        for (int i = 0; i < n + 1; i++) {
            parent[i] = i;
        }

        int[] result = null;
        for (int i = 0; i < edges.length; i++) {
            if (!union(edges[i][0], edges[i][1], parent)) {
                result = edges[i];
                break;
            }
        }

        return result != null ? result : new int[2];
    }

    private boolean union(int u, int v, int[] parent) {
        int rootU = find(u, parent);
        int rootV = find(v, parent);

        if (rootU == rootV) {
            return false;
        }

        parent[rootV] = rootU;
        return true;
    }

    private int find(int u, int[] parent) {
        if (parent[u] != u) {
            parent[u] = find(parent[u], parent);
        }
        return parent[u];
    }

    private int[] findCycle(int[][] edges, int[] parent, int nodeWithTwoParents) {
        // Initialize the parents array again
        for (int i = 0; i < edges.length; i++) {
            if (edges[i][1] == nodeWithTwoParents) {
                if (i > 0 && parent[nodeWithTwoParents] != 0) {
                    return edges[i];
                }
                parent[nodeWithTwoParents] = edges[i][0];
            } else {
                parent[edges[i][1]] = edges[i][0];
            }
        }

        // Find the cycle
        for (int i = 0; i < edges.length; i++) {
            if (!union(edges[i][0], edges[i][1], parent)) {
                return edges[i];
            }
        }

        throw new IllegalArgumentException("No cycle found");
    }
}

