public class Solution {
    public int scheduleCourse(int[][] courses) {
        // Sort the courses based on their deadline date.
        Arrays.sort(courses, (a, b) -> a[1] - b[1]);

        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        int total_time = 0;

        for (int[] course : courses) {
            // If adding this course doesn't exceed the limit.
            if (total_time + course[0] <= course[1]) {
                pq.offer(course[0]);
                total_time += course[0];
            } else {
                // If a longer course exists in pq, replace it with the current shorter one.
                if (!pq.isEmpty() && pq.peek() > course[0]) {
                    total_time -= pq.poll();
                    pq.offer(course[0]);
                    total_time += course[0];
                }
            }
        }

        return pq.size();
    }
}

