public class Solution {
    private final int[][] moves = {{-2, -1}, {-2, 1}, {-1, -2}, {-1, 2}, {1, -2}, {1, 2}, {2, -1}, {2, 1}};

    public double knightProbability(int n, int k, int row, int column) {
        double[][][] dp = new double[k + 1][n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                dp[0][i][j] = 1;
            }
        }

        for (int step = 1; step <= k; step++) {
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    double prob = 0.0;

                    for (int[] move : moves) {
                        int prevR = r + move[0];
                        int prevC = c + move[1];

                        if (prevR >= 0 && prevR < n && prevC >= 0 && prevC < n) {
                            prob += dp[step - 1][prevR][prevC] / 8.0;
                        }
                    }

                    dp[step][r][c] = prob;
                }
            }
        }

        return dp[k][row][column];
    }
}

