import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<Double> averageOfLevels(TreeNode root) {
        List<Double> result = new ArrayList<>();
        calculateAverage(root, 0, result);
        return result;
    }

    private void calculateAverage(TreeNode node, int level, List<Double> result) {
        if (node == null) {
            return;
        }

        if (level >= result.size()) {
            result.add((double) node.val);
        } else {
            double sum = result.get(level);
            result.set(level, (sum + node.val));
        }

        calculateAverage(node.left, level + 1, result);
        calculateAverage(node.right, level + 1, result);
    }
}

