// #Medium #Array #Hash_Table #Greedy #Heap_Priority_Queue
// #2022_03_21_Time_4_ms_(95.88%)_Space_72.5_MB_(21.48%)
public class Solution {
    public boolean isPossible(int[] nums) {
        Map<Integer, Integer> frequency = new HashMap<>();
        for (int num : nums) {
            frequency.put(num, frequency.getOrDefault(num, 0) + 1);
        }

        for (int num : nums) {
            if (!frequency.containsKey(num) || frequency.get(num) == 0) continue;
            boolean foundSequence = false;

            // Try to find a sequence of length at least 3 starting with 'num'
            frequency.put(num, frequency.get(num) - 1);
            for (int i = num + 1; !foundSequence && i <= num + 2; i++) {
                if (!frequency.containsKey(i) || frequency.get(i) == 0) continue;
                frequency.put(i, frequency.get(i) - 1);

                // Try to find the next number in sequence
                for (int j = i + 1; !foundSequence && j <= i + 2; j++) {
                    if (!frequency.containsKey(j) || frequency.get(j) == 0) continue;
                    foundSequence = true;
                    frequency.put(j, frequency.get(j) - 1);
                }

                // If we were unable to find the next number in sequence, restore 'i' and break
                if (!foundSequence) {
                    frequency.put(i, frequency.get(i) + 1);
                }
            }

            // If we weren't able to find a sequence starting with 'num', return false
            if (!foundSequence) {
                return false;
            }
        }

        // If we were able to process all numbers and find sequences for each of them, return true
        return true;
    }
}

