// #2022_03_21_Time_4_ms_(95.88%)_Space_72.5_MB_(21.48%)
public class Solution {
    public boolean isPossible(int[] nums) {
        Map<Integer, PriorityQueue<Integer>> map = new HashMap<>();

        for (int num : nums) {
            if (!map.containsKey(num - 1)) {
                map.computeIfAbsent(num, k -> new PriorityQueue<>());
                map.get(num).add(1);
            } else {
                int len = map.get(num - 1).poll();
                if (map.get(num - 1).isEmpty()) {
                    map.remove(num - 1);
                }
                map.computeIfAbsent(num, k -> new PriorityQueue<>());
                map.get(num).add(len + 1);
            }
        }

        for (PriorityQueue<Integer> queue : map.values()) {
            if (!queue.isEmpty() && queue.peek() < 3) {
                return false;
            }
        }

        return true;
    }
}

