import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int findShortestSubArray(int[] nums) {
        Map<Integer, Value> map = new HashMap<>();

        for (int i = 0; i < nums.length; i++) {
            if (!map.containsKey(nums[i])) {
                map.put(nums[i], new Value(1, i, i));
            } else {
                Value value = map.get(nums[i]);
                value.count++;
                value.end = i;
            }
        }

        int degree = 0;
        for (Value v : map.values()) {
            degree = Math.max(degree, v.count);
        }

        int minLen = nums.length;
        for (Value v : map.values()) {
            if (v.count == degree) {
                minLen = Math.min(minLen, v.end - v.start + 1);
            }
        }

        return minLen;
    }

    public static class Value {
        int count;
        int start;
        int end;

        public Value(int c, int s, int e) {
            this.count = c;
            this.start = s;
            this.end = e;
        }
    }
}

