import com_github_leetcode.TreeNode;

public class Solution {
    public String tree2str(TreeNode t) {
        if (t == null) return "";
        StringBuilder sb = new StringBuilder();
        preorder(t, sb);
        return sb.toString();
    }

    private void preorder(TreeNode node, StringBuilder sb) {
        if (node == null) return;

        // Add current node value
        sb.append(node.val);

        // If left child exists
        if (node.left != null) {
            sb.append("(");
            preorder(node.left, sb);
            sb.append(")");
        }

        // If right child exists but not left child, we need to add empty parenthesis for left child
        if (node.right != null) {
            if (node.left == null) {
                sb.append("()");
            }
            sb.append("(");
            preorder(node.right, sb);
            sb.append(")");
        }
    }
}

