// #Hard #Array #Hash_Table #Sorting #Greedy #Heap_Priority_Queue #Sliding_Window
// #2022_03_21_Time_31_ms_(87.39%)_Space_57.6_MB_(18.58%)
import java.util.*;

public class Solution {
    public int[] smallestRange(List<List<Integer>> nums) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        int max = Integer.MIN_VALUE;
        for (int i = 0; i < nums.size(); i++) {
            pq.offer(new int[]{nums.get(i).get(0), i, 0});
            max = Math.max(max, nums.get(i).get(0));
        }

        int range = Integer.MAX_VALUE;
        int start = 0;
        int end = max;
        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            if (end - start < max - curr[0]) {
                range = end - start;
                start = curr[0];
            }

            if (curr[2] + 1 == nums.get(curr[1]).size()) {
                break;
            } else {
                int nextVal = nums.get(curr[1]).get(curr[2] + 1);
                pq.offer(new int[]{nextVal, curr[1], curr[2] + 1});
                max = Math.max(max, nextVal);
            }
        }

        return new int[]{start, start + range};
    }
}

