import java.util.*;

public class Solution {
    public int[] smallestRange(List<List<Integer>> nums) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        for (int i = 0; i < nums.size(); i++) {
            pq.offer(new int[]{nums.get(i).get(0), i, 0});
        }

        int[] ans = {-1000000000, 1000000000};
        int right = -1;
        for (List<Integer> list : nums) {
            if (!list.isEmpty()) {
                right = Math.max(right, list.get(0));
            }
        }

        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            if (right - cur[0] < ans[1] - ans[0]) {
                ans[0] = cur[0];
                ans[1] = right;
            } else if (right - cur[0] == ans[1] - ans[0]) {
                if (cur[0] < ans[0]) {
                    ans[0] = cur[0];
                    ans[1] = right;
                }
            }

            int nextValIndex = cur[2] + 1;
            List<Integer> nextList = nums.get(cur[1]);
            if (nextValIndex < nextList.size()) {
                pq.offer(new int[]{nextList.get(nextValIndex), cur[1], nextValIndex});
                right = Math.max(right, nextList.get(nextValIndex));
            } else {
                break;
            }
        }

        return ans;
    }
}

