        return dfs(nums, new int[k], 0, target, visited);
    }

    private boolean dfs(int[] nums, int[] groups, int index, int target, boolean[] visited) {
        if (index == nums.length) {
            for (int group : groups) {
                if (group != target) {
                    return false;
                }
            }
            return true;
        }

        for (int i = 0; i < groups.length; i++) {
            if (groups[i] + nums[index] <= target && !visited[index]) {
                visited[index] = true;
                groups[i] += nums[index];
                if (dfs(nums, groups, index + 1, target, visited)) {
                    return true;
                }
                groups[i] -= nums[index];
                visited[index] = false;
            }
        }

        return false;
    }
}

