                for (int x = -1; x <= 1; x++) {
                    for (int y = -1; y <= 1; y++) {
                        // Skip the current cell itself
                        if (x == 0 && y == 0) {
                            continue;
                        }

                        int neighborRow = i + x;
                        int neighborCol = j + y;

                        // Check if neighboring cell is within bounds of matrix
                        if (neighborRow >= 0 && neighborRow < rows && neighborCol >= 0 && neighborCol < cols) {
                            sum += matrix[neighborRow][neighborCol];
                            count++;
                        }
                    }
                }

                // Calculate the smoothed value and store it in the new matrix
                smoothedMatrix[i][j] = (int) Math.floor((double) sum / count);
            }
        }

        return smoothedMatrix;
    }
}

