// #Medium #Array #Sorting #Binary_Search #Two_Pointers #Heap_Priority_Queue #Binary_Search_II_Day_2
// #2022_03_21_Time_3_ms_(99.20%)_Space_44.1_MB_(88.25%)

public class Solution {
    public List<Integer> findClosestElements(int[] arr, int k, int x) {
        ArrayList<Integer> result = new ArrayList<>();
        Arrays.sort(arr);

        // Calculate distance of each element from the target
        PriorityQueue<int[]> maxHeap = new PriorityQueue<>((a, b) -> 
            a[0] == b[0] ? a[1] - b[1] : b[0] - a[0]);

        for (int num : arr) {
            int distance = Math.abs(num - x);
            if (maxHeap.size() < k) {
                maxHeap.offer(new int[] {distance, num});
            } else if (maxHeap.peek()[0] > distance) {
                maxHeap.poll();
                maxHeap.offer(new int[] {distance, num});
            }
        }

        // Sort the result in ascending order
        while (!maxHeap.isEmpty()) {
            result.add(maxHeap.poll()[1]);
        }

        Collections.sort(result);
        return result;
    }
}

