public class Solution {
    public int[] findRedundantConnection(int[][] edges) {
        int n = edges.length;
        int[] parent = new int[n + 1];

        // Initialize the parent array where each node is its own parent
        for (int i = 0; i <= n; i++) {
            parent[i] = i;
        }

        // Iterate over the edges and find the first edge that creates a cycle
        for (int[] edge : edges) {
            int rootX = find(parent, edge[0]);
            int rootY = find(parent, edge[1]);

            if (rootX == rootY) {
                return edge;
            }

            // Union the two nodes if they are not in the same cycle
            union(parent, edge[0], edge[1]);
        }

        // If no redundant connection is found, return null
        return null;
    }

    private int find(int[] parent, int x) {
        if (parent[x] != x) {
            parent[x] = find(parent, parent[x]);
        }
        return parent[x];
    }

    private void union(int[] parent, int x, int y) {
        int rootX = find(parent, x);
        int rootY = find(parent, y);

        if (rootX != rootY) {
            parent[rootX] = rootY;
        }
    }
}

