// #2022_03_21_Time_2_ms_(78.93%)_Space_43.8_MB_(35.13%)
import com_github_leetcode.TreeNode;
import java.util.LinkedList;
import java.util.Objects;
import java.util.Queue;

public class Solution {
    public int widthOfBinaryTree(TreeNode root) {
        if (Objects.isNull(root)) return 0;

        Queue<Pair> queue = new LinkedList<>();
        queue.offer(new Pair(root, 0));
        int maxWidth = 1;

        while (!queue.isEmpty()) {
            int size = queue.size();
            int minIndex = queue.peek().idx;
            int maxIndex = minIndex;

            for (int i = 0; i < size; i++) {
                Pair pair = queue.poll();
                TreeNode node = pair.node;
                int index = pair.idx - minIndex; // adjust the index

                if (node.left != null) {
                    queue.offer(new Pair(node.left, 2 * index + 1));
                }
                if (node.right != null) {
                    queue.offer(new Pair(node.right, 2 * index + 2));
                }

                maxIndex = Math.max(maxIndex, index);
            }

            maxWidth = Math.max(maxWidth, maxIndex - minIndex + 1);
        }

        return maxWidth;
    }

    public class Solution {
        TreeNode node;
        int idx;

        public Pair(TreeNode node, int idx) {
            this.node = node;
            this.idx = idx;
        }
    }
}

