        StringBuilder sb = new StringBuilder();

        while (st.hasMoreTokens()) {
            if (!sb.toString().isEmpty()) 
                sb.insert(0, " ");
            sb.insert(0, st.nextToken());
        }

        return sb.toString();
    }
}

