public class Solution {
    public String largestNumber(int[] nums) {
        String[] strNums = new String[nums.length];

        // Convert integers to strings for comparison and concatenation
        for (int i = 0; i < nums.length; i++) {
            strNums[i] = String.valueOf(nums[i]);
        }

        // Sort the string array using a custom comparator
        Arrays.sort(strNums, new Comparator<String>() {
            @Override
            public int compare(String s1, String s2) {
                // Compare concatenated strings to determine larger number
                return (s2 + s1).compareTo(s1 + s2);
            }
        });

        // Handle the case where all numbers are zero
        if (strNums[0].equals("0")) {
            return "0";
        }

        // Concatenate the sorted string array and return as a single string
        StringBuilder sb = new StringBuilder();
        for (String str : strNums) {
            sb.append(str);
        }

        return sb.toString();
    }
}

