public class Solution {
    public int maxProfit(int k, int[] prices) {
        int n = prices.length;
        if (n < 2) return 0;

        // If the number of transactions is more than or equal to half of the days,
        // we can simply consider every peak and valley in the price array.
        if (k >= n / 2) {
            int maxProfit = 0;
            for (int i = 1; i < n; i++) {
                if (prices[i] > prices[i - 1]) {
                    maxProfit += prices[i] - prices[i - 1];
                }
            }
            return maxProfit;
        }

        // Initialize a 2D array to store the maximum profit for each subproblem.
        int[][] dp = new int[k + 1][n];

        // Iterate over each transaction.
        for (int i = 1; i <= k; i++) {
            // Initialize the maximum profit for the first transaction.
            int maxProfitSoFar = -prices[0];

            // Iterate over each day.
            for (int j = 1; j < n; j++) {
                // Update the maximum profit for the current transaction.
                dp[i][j] = Math.max(dp[i][j - 1], prices[j] + maxProfitSoFar);

                // Update the maximum profit so far for the next day.
                maxProfitSoFar = Math.max(maxProfitSoFar, dp[i - 1][j] - prices[j]);
            }
        }

        // Return the maximum profit for the last transaction.
        return dp[k][n - 1];
    }
}

