public class Solution {
    public int maxProfit(int k, int[] prices) {
        int n = prices.length;
        if (n < 2) return 0;

        // If the number of transactions is more than or equal to half the number of days,
        // we can simply consider every peak and valley as a transaction.
        if (k >= n / 2) {
            int maxProfit = 0;
            for (int i = 1; i < n; i++) {
                if (prices[i] > prices[i - 1]) {
                    maxProfit += prices[i] - prices[i - 1];
                }
            }
            return maxProfit;
        }

        // Initialize the dp array to store the maximum profit for each state.
        int[][] dp = new int[n][2 * k + 1];

        // Initialize the base case where we haven't done any transactions yet.
        for (int i = 0; i < n; i++) {
            dp[i][0] = 0;
        }

        // Initialize the maximum profit to negative infinity for the first buy state.
        int minPrice = prices[0];
        for (int i = 1; i < n; i++) {
            dp[i][1] = Math.max(dp[i - 1][1], -prices[i]);
            minPrice = Math.min(minPrice, prices[i]);
        }

        // Iterate over the number of transactions.
        for (int transaction = 2; transaction <= 2 * k; transaction += 2) {
            int maxProfitForPreviousTransaction = Integer.MIN_VALUE;
            if ((transaction / 2 - 1) % 2 == 0) {
                maxProfitForPreviousTransaction = dp[0][transaction - 1];
            }
            for (int i = 1; i < n; i++) {
                // Update the maximum profit for the current state.
                if (transaction % 2 == 1) {
                    dp[i][transaction] = Math.max(dp[i - 1][transaction], maxProfitForPreviousTransaction - prices[i]);
                } else {
                    dp[i][transaction] = Math.max(dp[i - 1][transaction], dp[i - 1][transaction - 1] + prices[i]);
                    maxProfitForPreviousTransaction = Math.max(maxProfitForPreviousTransaction, dp[i - 1][transaction - 1]);
                }
            }
        }

        // The maximum profit is stored in the last state of the dp array.
        return dp[n - 1][2 * k];
    }
}

