        // we can simply consider every peak and valley in the price array.
        if (k >= n / 2) {
            int maxProfit = 0;
            for (int i = 1; i < n; i++) {
                if (prices[i] > prices[i - 1]) {
                    maxProfit += prices[i] - prices[i - 1];
                }
            }
            return maxProfit;
        }

        // Initialize a 2D array to store the maximum profit for each subproblem.
        int[][] dp = new int[n][k + 1];

        // Iterate over each day in the price array.
        for (int i = 1; i < n; i++) {
            // Iterate over each possible number of transactions from 1 to k.
            for (int j = 1; j <= Math.min(i / 2, k); j++) {
                int maxProfitSoFar = 0;
                // Iterate over each previous day to find the maximum profit so far.
                for (int l = 0; l < i; l++) {
                    // Calculate the maximum profit if we buy on day l and sell on day i.
                    maxProfitSoFar = Math.max(maxProfitSoFar, dp[l][j - 1] + prices[i] - prices[l]);
                }
                // Update the maximum profit for the current subproblem.
                dp[i][j] = Math.max(dp[i - 1][j], maxProfitSoFar);
            }
        }

        // The maximum profit is stored in the last cell of the 2D array.
        return dp[n - 1][k];
    }
}

