public class Solution {
    public int maxProfit(int k, int[] prices) {
        int n = prices.length;

        // If k is more than or equal to the number of days, 
        // we can simply consider every peak following a valley to maximize profit.
        if (k >= n / 2) {
            int maxProfit = 0;
            for (int i = 1; i < n; i++) {
                if (prices[i] > prices[i - 1]) {
                    maxProfit += prices[i] - prices[i - 1];
                }
            }
            return maxProfit;
        }

        // Initialize a 2D array to store the maximum profit for each subproblem.
        int[][] dp = new int[n][k + 1];

        // Iterate over each possible number of transactions from 1 to k.
        for (int transaction = 1; transaction <= k; transaction++) {
            // Initialize the maximum profit for the current transaction to negative infinity.
            int maxProfitSoFar = Integer.MIN_VALUE;

            // Iterate over each day from the first day to the last day.
            for (int i = 1; i < n; i++) {
                // Update the maximum profit so far by considering whether we should buy or not on the current day.
                maxProfitSoFar = Math.max(maxProfitSoFar, dp[i - 1][transaction - 1] - prices[i - 1]);

                // Update the maximum profit for the current transaction by considering whether we should sell or not on the current day.
                dp[i][transaction] = Math.max(dp[i - 1][transaction], maxProfitSoFar + prices[i]);
            }
        }

        // Return the maximum profit for k transactions on the last day.
        return dp[n - 1][k];
    }
}

