        if (k >= n / 2) {
            int res = 0;
            for (int i = 1; i < n; i++) {
                // Add all positive profits
                res += Math.max(0, prices[i] - prices[i - 1]);
            }
            return res;
        }

        // Create a 2D array to store the maximum profit after each transaction.
        int[][] dp = new int[k + 1][n];

        for (int i = 1; i <= k; i++) {
            int maxDiff = -prices[0];
            for (int j = 1; j < n; j++) {
                // Update the maximum profit after each transaction.
                dp[i][j] = Math.max(dp[i][j - 1], prices[j] + maxDiff);
                // Update the maximum difference between the current price and the previous minimum price.
                maxDiff = Math.max(maxDiff, dp[i - 1][j] - prices[j]);
