public class Solution {
    public int findPeakElement(int[] nums) {
        return search(nums, 0, nums.length - 1);
    }

    private int search(int[] nums, int left, int right) {
        if (left == right) {
            return left;
        }
        int mid = left + (right - left) / 2;
        if (nums[mid] > nums[mid + 1]) {
            // If the middle element is greater than its next neighbor,
            // then a peak must exist on the left side of the middle.
            return search(nums, left, mid);
        } else {
            // If the middle element is smaller than or equal to its next neighbor,
            // then a peak must exist on the right side of the middle.
            return search(nums, mid + 1, right);
        }
    }
}

