// #Medium #Array #Sorting #Bucket_Sort #Radix_Sort
// #2022_06_25_Time_48_ms_(53.59%)_Space_84.1_MB_(20.66%)
import java.util.Arrays;

public class Solution {
    public int maximumGap(int[] nums) {
        if (nums == null || nums.length < 2) {
            return 0;
        }

        int minVal = Arrays.stream(nums).min().getAsInt();
        int maxVal = Arrays.stream(nums).max().getAsInt();

        // If all numbers are the same, there is no gap
        if (minVal == maxVal) {
            return 0;
        }

        // Initialize bucket size and count
        int bucketSize = (int) Math.ceil((double) (maxVal - minVal) / (nums.length - 1));
        int bucketCount = nums.length;

        // Create buckets with min and max values initialized to Integer.MAX_VALUE and Integer.MIN_VALUE respectively
        Bucket[] buckets = new Bucket[bucketCount];
        for (int i = 0; i < bucketCount; i++) {
            buckets[i] = new Bucket(Integer.MAX_VALUE, Integer.MIN_VALUE);
        }

        // Distribute numbers into buckets
        for (int num : nums) {
            int index = (num - minVal) / bucketSize;
            if (index == bucketCount) {
                index--;
            }
            buckets[index].min = Math.min(buckets[index].min, num);
            buckets[index].max = Math.max(buckets[index].max, num);
        }

        // Find the maximum gap between two successive non-empty buckets
        int maxGap = 0;
        int prevMaxVal = minVal;
        for (Bucket bucket : buckets) {
            if (bucket.min != Integer.MAX_VALUE && bucket.max != Integer.MIN_VALUE) {
                maxGap = Math.max(maxGap, bucket.min - prevMaxVal);
                prevMaxVal = bucket.max;
            }
        }

        return maxGap;
    }

    private class Bucket {
        int min;
        int max;

        public Bucket(int min, int max) {
            this.min = min;
            this.max = max;
        }
    }
}

