        if (nums.length < 2 || Arrays.stream(nums).distinct().count() == 1) {
            return 0;
        }

        int min = Integer.MAX_VALUE, max = Integer.MIN_VALUE;
        for (int num : nums) {
            min = Math.min(min, num);
            max = Math.max(max, num);
        }

        int bucketSize = Math.max(1, (max - min) / (nums.length - 1));
        int[] bucketsMin = new int[nums.length + 1];
        int[] bucketsMax = new int[nums.length + 1];

        Arrays.fill(bucketsMin, Integer.MAX_VALUE);
        Arrays.fill(bucketsMax, Integer.MIN_VALUE);

        for (int num : nums) {
            int index = (num - min) / bucketSize;
            if (index == (max - min) / bucketSize) {
                index--;
            }
            bucketsMin[index] = Math.min(bucketsMin[index], num);
            bucketsMax[index] = Math.max(bucketsMax[index], num);
        }

        int prevBucketMax = bucketsMax[0];
        int maxGap = 0;
        for (int i = 1; i <= nums.length; i++) {
            if (bucketsMin[i] != Integer.MAX_VALUE) {
                maxGap = Math.max(maxGap, bucketsMin[i] - prevBucketMax);
                prevBucketMax = bucketsMax[i];
            }
        }

        return maxGap;
    }
