// #Hard #Top_Interview_Questions #String #Hash_Table #Dynamic_Programming #Backtracking #Trie 
// #Memoization #2022_06_24_Time_1_ms_(99.05%)_Space_42.2_MB_(65.12%)
import java.util.*;

public class Solution {
    public List<String> wordBreak(String s, List<String> wordDict) {
        Set<String> dict = new HashSet<>(wordDict);
        Map<Integer, List<String>> memo = new HashMap<>();
        return dfs(s, 0, dict, memo);
    }

    private List<String> dfs(String s, int index, Set<String> dict, Map<Integer, List<String>> memo) {
        if (memo.containsKey(index)) {
            return memo.get(index);
        }
        List<String> result = new LinkedList<>();
        if (index == s.length()) {
            result.add("");
            return result;
        }
        for (int i = index + 1; i <= s.length(); i++) {
            String substr = s.substring(index, i);
            if (!dict.contains(substr)) {
                continue;
            }
            List<String> nextResult = dfs(s, i, dict, memo);
            for (String res : nextResult) {
                result.add(res.isEmpty() ? substr : substr + " " + res);
            }
        }
        memo.put(index, result);
        return result;
    }
}

