import java.util.*;

public class Solution {
    private Set<String> wordDictSet;

    public List<String> wordBreak(String s, List<String> wordDict) {
        wordDictSet = new HashSet<>(wordDict);
        return backtrack(s, 0);
    }

    private List<String> backtrack(String s, int start) {
        if (start == s.length()) {
            return Collections.singletonList("");
        }

        List<String> result = new LinkedList<>();

        for (int i = start + 1; i <= s.length(); ++i) {
            String prefix = s.substring(start, i);

            if (!wordDictSet.contains(prefix)) {
                continue;
            }

            for (String suffix : backtrack(s, i)) {
                result.add((suffix.isEmpty()) ? prefix : prefix + " " + suffix);
            }
        }

        return result;
    }
}

