// #Graph_Theory_I_Day_12_Breadth_First_Search
// #2022_06_23_Time_37_ms_(94.58%)_Space_54.1_MB_(66.08%)
import java.util.*;

public class Solution {
    public int ladderLength(String beginWord, String endWord, List<String> wordDict) {
        Set<String> dict = new HashSet<>(wordDict);
        if (!dict.contains(endWord)) return 0;

        Queue<String> queue = new LinkedList<>();
        queue.offer(beginWord);

        Map<String, Integer> distance = new HashMap<>();
        distance.put(beginWord, 1);

        while (!queue.isEmpty()) {
            String current = queue.poll();
            int dist = distance.get(current);
            if (current.equals(endWord)) return dist;

            for (int i = 0; i < current.length(); i++) {
                char[] chars = current.toCharArray();
                for (char c = 'a'; c <= 'z'; c++) {
                    chars[i] = c;
                    String next = new String(chars);
                    if (!dict.contains(next)) continue;

                    dict.remove(next);
                    queue.offer(next);
                    distance.put(next, dist + 1);
                }
            }
        }

        return 0;
    }
}

