// #Hard #Top_Interview_Questions #Array #Hash_Table #Math #Geometry #Algorithm_II_Day_21_Others
// #2022_06_24_Time_11_ms_(99.21%)_Space_41.5_MB_(95.53%)
public class Solution {
    public int maxPoints(int[][] points) {
        if (points.length <= 2) return points.length;

        int n = points.length;
        int maxCount = 0;

        for (int i = 0; i < n; i++) {
            Map<Double, Integer> slopeMap = new HashMap<>();
            int samePoint = 1;

            for (int j = i + 1; j < n; j++) {
                if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                    samePoint++;
                    continue;
                }

                double slope = calculateSlope(points[i], points[j]);
                slopeMap.put(slope, slopeMap.getOrDefault(slope, 0) + 1);
            }

            maxCount = Math.max(maxCount, getMaxCountFromMap(slopeMap) + samePoint);
        }

        return maxCount;
    }

    private double calculateSlope(int[] point1, int[] point2) {
        int xDiff = point2[0] - point1[0];
        int yDiff = point2[1] - point1[1];

        if (xDiff == 0) return Double.POSITIVE_INFINITY;

        double slope = (double) yDiff / xDiff;
        return slope;
    }

    private int getMaxCountFromMap(Map<Double, Integer> map) {
        int maxCount = 0;

        for (int count : map.values()) {
            maxCount = Math.max(maxCount, count);
        }

        return maxCount;
    }
}

