public class Solution {
    public int maxPoints(int[][] points) {
        if (points.length <= 2) return points.length;

        int n = points.length;
        int maxPoints = 0;

        for (int i = 0; i < n; i++) {
            Map<Double, Integer> slopeCount = new HashMap<>();
            int samePoint = 1;
            int localMax = 0;

            for (int j = i + 1; j < n; j++) {
                if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                    samePoint++;
                    continue;
                }

                double slope = calculateSlope(points[i], points[j]);
                slopeCount.put(slope, slopeCount.getOrDefault(slope, 0) + 1);
                localMax = Math.max(localMax, slopeCount.get(slope));
            }
            maxPoints = Math.max(maxPoints, localMax + samePoint);
        }

        return maxPoints;
    }

    private double calculateSlope(int[] point1, int[] point2) {
        int dx = point2[0] - point1[0];
