import com_github_leetcode.TreeNode;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public TreeNode buildTree(int[] preorder, int[] inorder) {
        Map<Integer, Integer> inMap = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) {
            inMap.put(inorder[i], i);
        }

        return helper(preorder, inorder, 0, preorder.length - 1, 0, inorder.length - 1, inMap);
    }

    private TreeNode helper(int[] preorder, int[] inorder, int preStart, int preEnd, int inStart, int inEnd, Map<Integer, Integer> inMap) {
        if (preStart > preEnd || inStart > inEnd) return null;

        TreeNode root = new TreeNode(preorder[preStart]);
        int index = inMap.get(root.val);

        int leftSize = index - inStart;

        root.left = helper(preorder, inorder, preStart + 1, preStart + leftSize, inStart, index - 1, inMap);
        root.right = helper(preorder, inorder, preStart + leftSize + 1, preEnd, index + 1, inEnd, inMap);

        return root;
    }
}

