public class Solution {
    public TreeNode buildTree(int[] preorder, int[] inorder) {
        Map<Integer, Integer> inorderIndexMap = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) {
            inorderIndexMap.put(inorder[i], i);
        }
        return buildTreeHelper(preorder, 0, preorder.length - 1, 
                               inorder, 0, inorder.length - 1, inorderIndexMap);
    }

    private TreeNode buildTreeHelper(int[] preorder, int preStart, int preEnd, 
                                     int[] inorder, int inStart, int inEnd, Map<Integer, Integer> inorderIndexMap) {
        if (preStart > preEnd || inStart > inEnd) {
            return null;
        }

        // The first element of the preorder traversal is the root
        TreeNode root = new TreeNode(preorder[preStart]);

        // Find the index of the root in the inorder traversal
        int rootIndexInInorder = inorderIndexMap.get(root.val);

        // Calculate the number of elements to the left and right of the root
        int numLeftElements = rootIndexInInorder - inStart;
        int numRightElements = inEnd - rootIndexInInorder;

        // Recursively construct the left subtree
        root.left = buildTreeHelper(preorder, preStart + 1, preStart + numLeftElements, 
                                    inorder, inStart, rootIndexInInorder - 1, inorderIndexMap);

        // Recursively construct the right subtree
        root.right = buildTreeHelper(preorder, preEnd - numRightElements + 1, preEnd, 
                                     inorder, rootIndexInInorder + 1, inEnd, inorderIndexMap);

        return root;
    }
}

