        if (numRows == 0) {
            return triangle;
        }

        // Add the first row of Pascal's triangle
        List<Integer> firstRow = new ArrayList<>();
        firstRow.add(1);
        triangle.add(firstRow);

        // Generate each subsequent row in Pascal's triangle
        for (int i = 1; i < numRows; i++) {
            List<Integer> row = new ArrayList<>();

            // The first element of each row is always 1
            row.add(1);

            // Calculate the middle elements as the sum of the two numbers directly above it
            List<Integer> prevRow = triangle.get(i - 1);
            for (int j = 1; j < i; j++) {
                row.add(prevRow.get(j - 1) + prevRow.get(j));
            }

            // The last element of each row is always 1
            row.add(1);

            triangle.add(row);
        }

        return triangle;
    }
}

