// #Medium #Array #Hash_Table #Tree #Binary_Tree #Divide_and_Conquer 
// #2022_06_22_Time_1_ms_(100.00%)_Space_44.7_MB_(28.54%)
import com_github_leetcode.TreeNode;

public class Solution {
    public TreeNode buildTree(int[] inorder, int[] postorder) {
        return helper(inorder, 0, inorder.length - 1, postorder, 0, postorder.length - 1);
    }

    private TreeNode helper(int[] inorder, int inStart, int inEnd, int[] postorder, int postStart, int postEnd) {
        if (postStart > postEnd || inStart > inEnd) {
            return null;
        }

        // Find the root node
        int rootVal = postorder[postEnd];
        TreeNode root = new TreeNode(rootVal);

        // Find the index of the root node in inorder array
        int inIndex = find(inorder, inStart, inEnd, rootVal);

        // Calculate the length of left subtree and right subtree
        int leftLen = inIndex - inStart;

        // Recursively build left subtree and right subtree
        root.left = helper(inorder, inStart, inIndex - 1, postorder, postStart, postStart + leftLen - 1);
        root.right = helper(inorder, inIndex + 1, inEnd, postorder, postStart + leftLen, postEnd - 1);

        return root;
    }

    private int find(int[] arr, int start, int end, int target) {
        for (int i = start; i <= end; i++) {
            if (arr[i] == target) {
                return i;
            }
        }
        return -1;
    }
}

