import com_github_leetcode.TreeNode;
import java.util.*;

public class Solution {
    List<List<Integer>> result = new ArrayList<>();

    public List<List<Integer>> levelOrderBottom(TreeNode root) {
        if (root == null) return result;

        Queue<TreeNode> queue = new LinkedList<>();
        queue.add(root);

        while (!queue.isEmpty()) {
            int size = queue.size();
            List<Integer> currentLevel = new ArrayList<>();

            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();
                currentLevel.add(node.val);

                if (node.left != null) {
                    queue.add(node.left);
                }
                if (node.right != null) {
                    queue.add(node.right);
                }
            }
            result.add(0, currentLevel); // add to the beginning of the list
        }

        return result;
    }

    public void getOrder(TreeNode root, int level) {
        // This method seems unnecessary for this problem.
        // But if you still want to use recursion with DFS,
        // here's how it would look:
        if (root == null) return;

        if (level >= result.size()) {
            result.add(0, new ArrayList<>()); // add a new level
        }

        getOrder(root.left, level + 1);
        getOrder(root.right, level + 1);
        result.get(result.size() - level - 1).add(root.val); // This line would make sense if you used DFS with recursion.
    }
}

