// #Easy #Top_100_Liked_Questions #Top_Interview_Questions #Hash_Table #Two_Pointers #Linked_List
// #Data_Structure_II_Day_11_Linked_List #Udemy_Linked_List #Big_O_Time_O(M+N)_Space_O(1)
// #2022_06_25_Time_1_ms_(99.68%)_Space_55.1_MB_(63.42%)
import com_github_leetcode.ListNode;

public class Solution {
    public ListNode getIntersectionNode(ListNode headA, ListNode headB) {
        int lengthA = 0;
        int lengthB = 0;

        // Calculate the length of list A
        ListNode tempA = headA;
        while (tempA != null) {
            lengthA++;
            tempA = tempA.next;
        }

        // Calculate the length of list B
        ListNode tempB = headB;
        while (tempB != null) {
            lengthB++;
            tempB = tempB.next;
        }

        // Move the longer list forward by the difference in lengths
        if (lengthA > lengthB) {
            for (int i = 0; i < lengthA - lengthB; i++) {
                headA = headA.next;
            }
        } else {
            for (int i = 0; i < lengthB - lengthA; i++) {
                headB = headB.next;
            }
        }

        // Move both lists forward in tandem
        while (headA != null && headB != null) {
            if (headA == headB) {
                return headA;
            }
            headA = headA.next;
            headB = headB.next;
        }

        return null;
    }
}

