// #2022_06_22_Time_0_ms_(100.00%)_Space_43.9_MB_(32.26%)
import com_github_leetcode.TreeNode;

public class Solution {
    public TreeNode sortedArrayToBST(int[] num) {
        return helper(num, 0, num.length - 1);
    }

    private TreeNode helper(int[] num, int left, int right) {
        if (left > right) {
            return null;
        }

        // find the middle element
        int mid = left + (right - left) / 2;

        // make the middle element as root
        TreeNode root = new TreeNode(num[mid]);

        // construct the left and right subtrees
        root.left = helper(num, left, mid - 1);
        root.right = helper(num, mid + 1, right);

        return root;
    }
}

