        if (!dict.contains(endWord)) return new ArrayList<>();

        Map<String, List<String>> graph = new HashMap<>();
        buildGraph(beginWord, dict, graph);

        Queue<List<String>> queue = new LinkedList<>();
        queue.offer(new ArrayList<>(Arrays.asList(beginWord)));

        Set<String> visited = new HashSet<>();
        boolean found = false;
        int levelSize = 1;

        while (!queue.isEmpty()) {
            List<String> currentPath = queue.poll();
            String node = currentPath.get(currentPath.size() - 1);
            if (node.equals(endWord)) {
                found = true;
                levelSize--;
                graph.put(node, new ArrayList<>());
                graph.get(node).addAll(getNeighbors(node, dict));
            }

            for (String neighbor : getNeighbors(node, dict)) {
                currentPath.add(neighbor);
                queue.offer(new ArrayList<>(currentPath));
                visited.add(neighbor);
                currentPath.remove(currentPath.size() - 1);
            }
            levelSize--;
            if (levelSize == 0) {
                if (!found) break;
                else return constructPaths(beginWord, endWord, graph);
            }
        }

        return new ArrayList<>();
    }

    private void buildGraph(String beginWord, Set<String> dict, Map<String, List<String>> graph) {
        Queue<List<String>> queue = new LinkedList<>();
        queue.offer(new ArrayList<>(Arrays.asList(beginWord)));

        Set<String> visited = new HashSet<>();
        boolean found = false;
        int levelSize = 1;

        while (!queue.isEmpty()) {
            List<String> currentPath = queue.poll();
            String node = currentPath.get(currentPath.size() - 1);
            if (node.equals(endWord)) {
                found = true;
                graph.put(node, new ArrayList<>());
                graph.get(node).addAll(getNeighbors(node, dict));
            }

            for (String neighbor : getNeighbors(node, dict)) {
                currentPath.add(neighbor);
                queue.offer(new ArrayList<>(currentPath));
                visited.add(neighbor);
                currentPath.remove(currentPath.size() - 1);
            }
            levelSize--;
            if (levelSize == 0) {
                if (!found) break;
                else return;
            }
        }
    }

    private List<String> getNeighbors(String node, Set<String> dict) {
        List<String> neighbors = new ArrayList<>();

        for (char c = 'a'; c <= 'z'; c++) {
            for (int i = 0; i < node.length(); i++) {
                String neighbor = node.substring(0, i) + c + node.substring(i + 1);
                if (!neighbor.equals(node) && dict.contains(neighbor)) neighbors.add(neighbor);
            }
        }

        return neighbors;
    }

    private List<List<String>> constructPaths(String beginWord, String endWord, Map<String, List<String>> graph) {
        Set<String> visited = new HashSet<>();
        List<List<String>> result = new ArrayList<>();

        dfs(beginWord, endWord, graph, new ArrayList<>(), result);

        return result;
    }

    private void dfs(String currentWord, String endWord, Map<String, List<String>> graph, List<String> path, List<List<String>> result) {
        path.add(currentWord);

        if (currentWord.equals(endWord)) {
            result.add(new ArrayList<>(path));
            path.remove(path.size() - 1);
            return;
        }

        for (String neighbor : graph.get(currentWord)) {
            dfs(neighbor, endWord, graph, path, result);
        }
        path.remove(path.size() - 1);
    }
}

