import java.util.*;

public class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> dict = new HashSet<>(wordList);
        if (!dict.contains(endWord)) return new ArrayList<>();

        Map<String, List<String>> graph = new HashMap<>();
        bfs(graph, beginWord, endWord, dict);

        List<List<String>> res = new ArrayList<>();
        dfs(res, new ArrayList<>(), beginWord, endWord, graph);
        return res;
    }

    private void bfs(Map<String, List<String>> graph, String beginWord, String endWord, Set<String> dict) {
        Queue<String> queue = new LinkedList<>();
        queue.offer(beginWord);
        boolean found = false;

        while (!queue.isEmpty()) {
            int size = queue.size();
            Set<String> level = new HashSet<>();

            for (int i = 0; i < size; i++) {
                String word = queue.poll();

                if (word.equals(endWord)) found = true;

                for (String next : getNextWords(word, dict)) {
                    graph.computeIfAbsent(next, k -> new ArrayList<>()).add(word);
                    level.add(next);
                }
            }

            if (found) break;
            queue.addAll(level);
        }
    }

    private List<String> getNextWords(String word, Set<String> dict) {
        List<String> next = new ArrayList<>();
        char[] chars = word.toCharArray();

        for (int i = 0; i < chars.length; i++) {
            char c = chars[i];
            for (char j = 'a'; j <= 'z'; j++) {
                if (j == c) continue;
                chars[i] = j;
                String newWord = new String(chars);

                if (dict.contains(newWord)) next.add(newWord);
            }
            chars[i] = c;
        }

        return next;
    }

    private void dfs(List<List<String>> res, List<String> path, String word, String endWord, Map<String, List<String>> graph) {
        path.add(word);

        if (word.equals(endWord)) {
            res.add(new ArrayList<>(path));
            return;
        }

        if (!graph.containsKey(word)) return;

        for (String next : graph.get(word)) {
            dfs(res, path, next, endWord, graph);
        }

        path.remove(path.size() - 1);
    }
}

