public class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> wordSet = new HashSet<>(wordList);
        if (!wordSet.contains(endWord)) return new ArrayList<>();

        Map<String, List<String>> graph = new HashMap<>();
        boolean found = false;
        Queue<String> queue = new LinkedList<>();
        queue.offer(beginWord);

        while (!queue.isEmpty() && !found) {
            int size = queue.size();
            Set<String> currentLayer = new LinkedHashSet<>(size);
            for (int i = 0; i < size; i++) {
                String word = queue.poll();
                char[] chs = word.toCharArray();

                for (int j = 0; j < chs.length; j++) {
                    char originalChar = chs[j];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (chs[j] == c) continue;
                        chs[j] = c;

                        String nextWord = new String(chs);
                        if (!wordSet.contains(nextWord)) continue;

                        graph.computeIfAbsent(word, k -> new ArrayList<>()).add(nextWord);
                        currentLayer.add(nextWord);

                        if (nextWord.equals(endWord)) found = true;
                    }
                    chs[j] = originalChar;
                }
            }

            for (String word : currentLayer) {
                queue.offer(word);
                wordSet.remove(word);
            }
        }

        List<List<String>> ans = new ArrayList<>();
        dfs(ans, graph, beginWord, endWord, new LinkedList<>());
        return ans;
    }

    private void dfs(List<List<String>> ans, Map<String, List<String>> graph, String start, String end, List<String> path) {
        path.add(start);
        if (start.equals(end)) {
            ans.add(new ArrayList<>(path));
        } else {
            if (graph.containsKey(start)) {
                for (String next : graph.get(start)) {
                    dfs(ans, graph, next, end, path);
                }
            }
        }
        path.remove(path.size() - 1);
    }
}

