import java.util.*;

public class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> wordSet = new HashSet<>(wordList);
        Map<String, List<String>> reverseGraph = new HashMap<>();
        Queue<String> queue = new LinkedList<>();
        boolean findEndWord = false;
        int levelSize;

        // Initialize the queue with beginWord
        queue.offer(beginWord);
        wordSet.remove(beginWord);

        while (!queue.isEmpty()) {
            levelSize = queue.size();

            for (int i = 0; i < levelSize; i++) {
                String currentWord = queue.poll();

                for (String nextWord : getNeighbors(currentWord, wordSet)) {
                    if (!reverseGraph.containsKey(nextWord)) {
                        reverseGraph.put(nextWord, new ArrayList<>());
                    }
                    reverseGraph.get(nextWord).add(currentWord);

                    // If we've found the endWord, stop exploring
                    if (nextWord.equals(endWord)) {
                        findEndWord = true;
                    } else {
                        queue.offer(nextWord);
                    }
                }
            }

            // Remove all next layer nodes in wordSet
            for (String word : new ArrayList<>(wordSet)) {
                if (!queue.contains(word) && !reverseGraph.containsKey(word)) {
                    wordSet.remove(word);
                }
            }

            // If we've found the endWord, stop exploring
            if (findEndWord) {
                break;
            }
        }

        List<List<String>> ans = new ArrayList<>();

        // If can't reach endWord from startWord, then return ans.
        if (!findEndWord) {
            return ans;
        }

        dfs(ans, endWord, beginWord, reverseGraph);

        return ans;
    }

    private void dfs(List<List<String>> ans, String currentWord, String target, Map<String, List<String>> reverseGraph) {
        if (currentWord.equals(target)) {
            List<String> path = new ArrayList<>();
            path.add(currentWord);

            for (List<String> existingPath : ans) {
                if (!existingPath.isEmpty() && existingPath.size() > 1) {
                    return;
                }
            }

            ans.add(new ArrayList<>(path));
        } else if (reverseGraph.containsKey(currentWord)) {
            List<String> path = new ArrayList<>();

            for (List<String> existingPath : ans) {
                if (!existingPath.isEmpty()) {
                    path.addAll(existingPath);
                    break;
                }
            }

            path.add(0, currentWord);

            for (String nextWord : reverseGraph.get(currentWord)) {
                dfs(ans, nextWord, target, reverseGraph);

                if (ans.size() > 0 && !ans.isEmpty()) {
                    return;
                } else {
                    path.remove(path.indexOf(nextWord));
                }
            }
        }
    }

    private List<String> getNeighbors(String word, Set<String> wordSet) {
        List<String> neighbors = new ArrayList<>();

        for (char c = 'a'; c <= 'z'; c++) {
            for (int i = 0; i < word.length(); i++) {
                String nextWord = word.substring(0, i) + c + word.substring(i + 1);

                if (wordSet.contains(nextWord)) {
                    neighbors.add(nextWord);
                }
            }
        }

        return neighbors;
    }
}

