import java.util.HashMap;
import java.util.Map;

public class Solution {
    public String fractionToDecimal(int numerator, int denominator) {
        // Check for division by zero
        if (denominator == 0) {
            throw new ArithmeticException("Cannot divide by zero");
        }

        if (numerator == 0) {
            return "0";
        }

        StringBuilder result = new StringBuilder();

        // Handle negative cases
        if ((numerator < 0 && denominator > 0) || (numerator > 0 && denominator < 0)) {
            result.append("-");
        }

        long num = Math.abs((long) numerator);
        long denom = Math.abs((long) denominator);

        // Calculate the integer part of the fraction
        long quotient = num / denom;
        result.append(quotient);

        // If there's no remainder, return the integer part as a string
        long remainder = num % denom;
        if (remainder == 0) {
            return result.toString();
        }

        result.append(".");

        // Store the remainders and their indices in a hashmap to detect recurring decimals
        Map<Long, Integer> remainderMap = new HashMap<>();

        StringBuilder decimalPart = new StringBuilder();

        while (remainder != 0 && !remainderMap.containsKey(remainder)) {
            remainderMap.put(remainder, decimalPart.length());
            remainder *= 10;
            decimalPart.append(remainder / denom);
            remainder %= denom;
        }

        // If the remainder is recurring, enclose it in parentheses
        if (remainder != 0) {
            int index = remainderMap.get(remainder);
            return result.toString() + decimalPart.substring(0, index) + "(" + decimalPart.substring(index) + ")";
        } else {
            return result.toString() + decimalPart.toString();
        }
    }
}

