import java.util.Arrays;
public class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        Arrays.sort(arr2);
        return dfs(arr1, 0, -1, new Integer[arr1.length], arr2);
    }

    private int dfs(int[] arr1, int i, int prev, Integer[] memo, int[] arr2) {
        if (i == arr1.length) return 0;

        if (memo[i] != null && memo[i] >= 0) return memo[i];

        int res = Integer.MAX_VALUE;

        // try to keep the current element
        if (prev < arr1[i]) {
            int next = dfs(arr1, i + 1, arr1[i], memo, arr2);
            if (next != -1) res = Math.min(res, next);
        }

        // try to replace the current element
        int j = binarySearch(arr2, prev + 1);
        if (j < arr2.length) {
            int next = dfs(arr1, i + 1, arr2[j], memo, arr2);
            if (next != -1) res = Math.min(res, next + 1);
        }

        memo[i] = res == Integer.MAX_VALUE ? -1 : res;
        return memo[i];
    }

    private int binarySearch(int[] nums, int target) {
        int left = 0, right = nums.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

