import java.util.Arrays;

public class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        Arrays.sort(arr2);
        return dfs(0, -1, new Integer[arr1.length], arr1, arr2);
    }

    private int dfs(int index, int prevValue, Integer[] memo, int[] arr1, int[] arr2) {
        if (index == arr1.length) {
            return 0;
        }

        if (memo[index] != null && memo[index] != -1) {
            return memo[index];
        }

        int result = Integer.MAX_VALUE;

        // Try replacing the current element with each element in arr2
        int pos = binarySearch(arr2, prevValue + 1);
        for (int i = pos; i < arr2.length; i++) {
            if (arr2[i] > prevValue && (index == arr1.length - 1 || arr2[i] < arr1[index])) {
                int temp = dfs(index + 1, arr2[i], memo, arr1, arr2);
                if (temp != -1) {
                    result = Math.min(result, 1 + temp);
                }
            } else {
                break;
            }
        }

        // Try leaving the current element as it is
        if (prevValue < arr1[index] && (index == arr1.length - 1 || arr1[index] < arr1[index + 1])) {
            result = Math.min(result, dfs(index + 1, arr1[index], memo, arr1, arr2));
        }

        // If no valid operation is found
        if (result == Integer.MAX_VALUE) {
            return -1;
        } else {
            memo[index] = result;
            return result;
        }
    }

    private int binarySearch(int[] arr, int target) {
        int left = 0;
        int right = arr.length - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (arr[mid] >= target) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        return left;
    }
}

