import java.util.Arrays;

public class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        Arrays.sort(arr2);
        int n = arr1.length;
        Integer[][] memo = new Integer[n][arr2.length];

        return dp(0, -1, arr1, arr2, memo);
    }

    private int dp(int i, int prev, int[] arr1, int[] arr2, Integer[][] memo) {
        if (i == arr1.length) return 0;

        if (memo[i][prev + 1] != null) return memo[i][prev + 1];

        int res = -1;

        // try with current element
        if (prev == -1 || arr1[i] > prev) {
            res = dp(i + 1, arr1[i], arr1, arr2, memo);
        }

        // try with arr2 elements that are greater than prev and smaller than next element in arr1
        int j = binarySearch(arr2, prev + 1);
        if (j < arr2.length && (i == arr1.length - 1 || arr2[j] < arr1[i + 1])) {
            if (res == -1) res = 1 + dp(i + 1, arr2[j], arr1, arr2, memo);
            else res = Math.min(res, 1 + dp(i + 1, arr2[j], arr1, arr2, memo));
        }

        memo[i][prev + 1] = res;
        return res;
    }

    private int binarySearch(int[] arr2, int target) {
        int left = 0, right = arr2.length - 1;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (arr2[mid] >= target) right = mid - 1;
            else left = mid + 1;
        }
        return left == arr2.length ? left : left;
    }
}

