import java.util.Arrays;
public class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        Arrays.sort(arr2);
        return dp(0, -1, arr1, arr2, new Integer[arr1.length][arr2.length]);
    }

    private int dp(int i, int prevUsedIndex, int[] arr1, int[] arr2, Integer[][] memo) {
        if (i == arr1.length) return 0;

        if (memo[i][prevUsedIndex + 1] != null) return memo[i][prevUsedIndex + 1];

        int min = i > 0 ? Math.max(arr1[i - 1], prevUsedIndex >= 0 ? arr2[prevUsedIndex] : Integer.MIN_VALUE) + 1 : Integer.MIN_VALUE + 1;

        // If we can make the current element larger than the previous one without using arr2, then do so
        int op = i > 0 && min <= arr1[i] ? dp(i + 1, prevUsedIndex, arr1, arr2, memo) : Integer.MAX_VALUE;

        // Find the first number in arr2 that is larger than the minimum required value
        int j = findFirstLarger(arr2, min);

        if (j < arr2.length) {
            op = Math.min(op, 1 + dp(i + 1, j, arr1, arr2, memo));
        }

        return memo[i][prevUsedIndex + 1] = op;
    }

    private int findFirstLarger(int[] arr, int target) {
        int left = -1, right = arr.length;
        while (left < right - 1) {
            int mid = (left + right) / 2;
            if (arr[mid] <= target) left = mid;
            else right = mid;
        }
        return right == arr.length ? -1 : right;
    }
}

