public class Solution {
    char c;
    int count;

    public Pair(char c, int count) {
        this.c = c;
        this.count = count;
    }
}

public class Solution {
    private Map<Character, Integer> totalCharCount = new HashMap<>();

    public int maxRepOpt1(String text) {
        // collect counts for each char-block
        List<Pair> blockCounts = getBlockCounts(text);

        // case 1: swap 1 item to the boundary of a consecutive cha-block to achieve possible max length
        int maxLength = getMaxSwapLength(blockCounts, totalCharCount, text.length());

        return maxLength;
    }

    private List<Pair> getBlockCounts(String text) {
        List<Pair> blockCounts = new ArrayList<>();
        char c = text.charAt(0);
        int count = 1;

        for (int i = 1; i < text.length(); i++) {
            if (text.charAt(i) == c) {
                count++;
            } else {
                blockCounts.add(new Pair(c, count));
                c = text.charAt(i);
                count = 1;
            }
            totalCharCount.put(text.charAt(i), totalCharCount.getOrDefault(text.charAt(i), 0) + 1);
        }

        blockCounts.add(new Pair(c, count));

        return blockCounts;
    }

    private int getMaxSwapLength(List<Pair> blockCounts, Map<Character, Integer> totalCharCount, int n) {
        // case 1: swap 1 item to the boundary of a consecutive cha-block to achieve possible max length
        int maxLength = 0;

        for (int i = 0; i < blockCounts.size(); i++) {
            Pair pair = blockCounts.get(i);
            if (i > 0 && blockCounts.get(i - 1).c == pair.c) {
                continue;
            }

            // case 2: find xxxxYxxxxx pattern
            int leftIdx = i > 0 ? i - 1 : -1;
            int rightIdx = i < blockCounts.size() - 1 ? i + 1 : blockCounts.size();

            if (leftIdx >= 0 && rightIdx < blockCounts.size() &&
                    pair.c == blockCounts.get(leftIdx).c &&
                    totalCharCount.get(pair.c) > pair.count) {
                maxLength = Math.max(maxLength, pair.count + 1);
            }
        }

        // case 2: find xxxxYxxxxx pattern
        for (int i = 0; i < blockCounts.size(); i++) {
            Pair pair = blockCounts.get(i);

            if (i > 0 && i < blockCounts.size() - 1 &&
                    blockCounts.get(i - 1).c == blockCounts.get(i + 1).c &&
                    totalCharCount.get(blockCounts.get(i - 1).c) > blockCounts.get(i - 1).count) {
                maxLength = Math.max(maxLength, blockCounts.get(i - 1).count + blockCounts.get(i + 1).count + (pair.count == 1 ? 1 : 0));
            }
        }

        // no swap
        for (Pair pair : blockCounts) {
            maxLength = Math.max(maxLength, pair.count);
        }

        return maxLength;
    }
}

