import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int maxRepOpt1(String text) {
        char[] chars = text.toCharArray();
        Map<Character, Integer> countMap = new HashMap<>();

        // Count the occurrences of each character in the string.
        for (char c : chars) {
            countMap.put(c, countMap.getOrDefault(c, 0) + 1);
        }

        int maxLen = 0;
        int left = 0, right = 0;
        while (right < chars.length) {
            char curChar = chars[right];
            // Expand the window to the right as long as we have consecutive repeated characters.
            while (right + 1 < chars.length && chars[right + 1] == curChar) {
                right++;
            }

            // Calculate the maximum length of the substring with repeated characters
            // after swapping one character at most.
            maxLen = Math.max(maxLen, getMaxLengthWithSwap(chars, left, right, countMap));

            // Move the window to the next segment of consecutive repeated characters.
            left = ++right;
        }

        return maxLen;
    }

    private int getMaxLengthWithSwap(char[] chars, int left, int right, Map<Character, Integer> countMap) {
        char curChar = chars[left];
        int sameCount = 0;
        for (int i = left; i <= right; i++) {
            if (chars[i] == curChar) {
                sameCount++;
            }
        }

        // Case 1: Swap one character to the boundary of a consecutive char block.
        int maxLengthWithSwapToBoundary = Math.min(sameCount + 1, countMap.get(curChar));

        // Case 2: Find 'xxxxYxxxxx' pattern and swap the middle character 'Y'.
        for (char c : countMap.keySet()) {
            if (c != curChar && countMap.get(c) > 0) {
                int maxLengthWithSwapInPattern = Math.min(sameCount + 1, countMap.get(curChar)) + 
                                                (countMap.get(c) > 1 ? 1 : 0);
                maxLengthWithSwapToBoundary = Math.max(maxLengthWithSwapToBoundary, maxLengthWithSwapInPattern);
            }
        }

        return maxLengthWithSwapToBoundary;
    }

    public static class Pair {
        private char c;
        private int count;

        public Pair(char c, int count) {
            this.c = c;
            this.count = count;
        }

        public char getC() {
            return c;
        }

        public void setC(char c) {
            this.c = c;
        }

        public int getCount() {
            return count;
        }

        public void setCount(int count) {
            this.count = count;
        }
    }
}

