public class Solution {
    public int maxRepOpt1(String text) {
        Map<Character, Integer> totalCountMap = new HashMap<>();
        for (char c : text.toCharArray()) {
            totalCountMap.put(c, totalCountMap.getOrDefault(c, 0) + 1);
        }

        int n = text.length();
        char[] chs = text.toCharArray();

        List<Pair> pairs = new ArrayList<>();
        char lastChar = chs[0];
        int count = 1;
        for (int i = 1; i < n; i++) {
            if (chs[i] == lastChar) {
                count++;
            } else {
                pairs.add(new Pair(lastChar, count));
                lastChar = chs[i];
                count = 1;
            }
        }
        pairs.add(new Pair(lastChar, count));

        int maxLen = 0;

        // case 1: swap one item to the boundary of a consecutive char block
        for (int i = 0; i < pairs.size(); i++) {
            if (i > 0 && pairs.get(i - 1).c == pairs.get(i).c) {
                int mergeCount = pairs.get(i - 1).count + pairs.get(i).count;
                if (i + 1 < pairs.size() && pairs.get(i + 1).c == pairs.get(i).c) {
                    mergeCount += pairs.get(i + 1).count;
                } else if (totalCountMap.get(pairs.get(i).c) > mergeCount) {
                    // we can swap one character to make it a consecutive block
                    maxLen = Math.max(maxLen, mergeCount + 1);
                }
            } else if (i < pairs.size() - 1 && pairs.get(i).count == 1 && pairs.get(i - 1).c == pairs.get(i + 1).c) {
                // case 2: find xxxxYxxxxx pattern
                maxLen = Math.max(maxLen, pairs.get(i - 1).count + pairs.get(i + 1).count + (totalCountMap.get(pairs.get(i - 1).c) > pairs.get(i - 1).count + pairs.get(i + 1).count ? 1 : 0));
            }

            // update maxLen
            int sameCount = totalCountMap.get(pairs.get(i).c);
            maxLen = Math.max(maxLen, Math.min(sameCount, pairs.get(i).count + 1));
        }

        return maxLen;
    }
}

