public class Solution {
    public int maximumSum(int[] arr) {
        int n = arr.length;

        // Handle edge case where array has only one element
        if (n == 1) return arr[0];

        // Initialize variables to store the maximum sum of subarrays with and without deletion
        int forward[] = new int[n], backward[] = new int[n];
        for (int i = 0; i < n; i++) {
            forward[i] = Integer.MIN_VALUE;
            backward[i] = Integer.MIN_VALUE;
        }

        // Calculate the maximum sum of subarrays without deletion
        int maxSumWithoutDeletion = arr[0], currentSum = arr[0];
        for (int i = 1; i < n; i++) {
            currentSum = Math.max(arr[i], currentSum + arr[i]);
            maxSumWithoutDeletion = Math.max(maxSumWithoutDeletion, currentSum);
        }

        // Calculate the maximum sum of subarrays with deletion
        int maxSumWithDeletion = Integer.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            int sumWithoutLastElement = 0, sumWithoutFirstElement = 0;
            currentSum = arr[i];
            forward[i] = arr[i]; // maximum sum ending at index i
            backward[i] = arr[n - 1 - i]; // maximum sum starting from the end at index n-1-i

            for (int j = i + 1; j < n; j++) {
                currentSum += arr[j];
                forward[j] = Math.max(currentSum, forward[j - 1]);
            }

            currentSum = arr[n - 1 - i];
            for (int j = n - 2 - i; j >= 0; j--) {
                currentSum += arr[n - 1 - j];
                backward[n - 1 - j] = Math.max(currentSum, backward[n - j]);
            }

            // Calculate the maximum sum with one deletion
            for (int k = i + 1; k < n; k++) {
                maxSumWithDeletion = Math.max(maxSumWithDeletion, forward[k - 1] + backward[k + 1]);
                if (k > i + 1) {
                    maxSumWithDeletion = Math.max(maxSumWithDeletion, sumWithoutLastElement + backward[k + 1]);
                }
            }
        }

        return Math.max(maxSumWithoutDeletion, maxSumWithDeletion);
    }
}

