public class Solution {
    public int maximumSum(int[] arr) {
        if (arr == null || arr.length == 0) return 0;

        int n = arr.length;
        int[][] dp = new int[n][2];

        // Initialize first row of dp
        dp[0][0] = arr[0]; // without delete
        dp[0][1] = Integer.MIN_VALUE; // with delete

        int res = arr[0];

        for (int i = 1; i < n; i++) {
            dp[i][0] = Math.max(dp[i-1][0], 0) + arr[i]; // without delete
            dp[i][1] = Math.max(dp[i-1][0], dp[i-1][1]) + arr[i]; // with delete

            if (i > 0) {
                dp[i][1] = Math.max(dp[i][1], dp[i-1][0]); 
            }

            res = Math.max(res, Math.max(dp[i][0], dp[i][1]));
        }

        return res;
    }
