public class Solution {
    public int maximumSum(int[] arr) {
        int n = arr.length;

        if (n == 1) return arr[0];

        int forward[] = new int[n];
        int backward[] = new int[n];

        // Calculate the max sum from left with optional delete
        forward[0] = arr[0];
        for (int i = 1; i < n; i++) {
            int include = forward[i - 1] + arr[i];
            int exclude = arr[i];
            forward[i] = Math.max(include, exclude);
        }

        // Calculate the max sum from right with optional delete
        backward[n - 1] = arr[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            int include = backward[i + 1] + arr[i];
            int exclude = arr[i];
            backward[i] = Math.max(include, exclude);
        }

        // The result will be the maximum of 
        // forward and backward arrays with optional delete in between
        int maxSum = Integer.MIN_VALUE;
        for (int i = 0; i < n - 1; i++) {
            int sum = forward[i] + backward[i + 1];
            maxSum = Math.max(maxSum, sum);
        }

        // Also consider the case where we don't delete any element
        maxSum = Math.max(maxSum, findMaxSubarray(arr));

        return maxSum;
    }

    public int findMaxSubarray(int[] nums) {
        if (nums == null || nums.length == 0) {
            throw new IllegalArgumentException("Input array cannot be empty");
        }

        int currentSum = nums[0];
        int maxSum = nums[0];

        for (int i = 1; i < nums.length; i++) {
            currentSum = Math.max(nums[i], currentSum + nums[i]);
            maxSum = Math.max(maxSum, currentSum);
        }

        return maxSum;
    }
}

