public class Solution {
    public int maximumSum(int[] arr) {
        int forward[] = new int[arr.length];
        int backward[] = new int[arr.length];

        // Kadane's algorithm for subarray with no deletion
        int maxSoFar = arr[0], maxEndingHere = arr[0];
        forward[0] = arr[0];
        for (int i = 1; i < arr.length; ++i) {
            maxEndingHere = Math.max(arr[i], maxEndingHere + arr[i]);
            maxSoFar = Math.max(maxSoFar, maxEndingHere);
            forward[i] = maxSoFar;
        }

        // Kadane's algorithm for subarray with no deletion in reverse order
        maxSoFar = arr[arr.length - 1];
        maxEndingHere = arr[arr.length - 1];
        backward[backward.length - 1] = arr[arr.length - 1];
        for (int i = backward.length - 2; i >= 0; --i) {
            maxEndingHere = Math.max(arr[i], maxEndingHere + arr[i]);
            maxSoFar = Math.max(maxSoFar, maxEndingHere);
            backward[i] = maxSoFar;
        }

        int result = Integer.MIN_VALUE;
        // Check all possible subarrays with one deletion
        for (int i = 0; i < arr.length - 1; ++i) {
            result = Math.max(result, forward[i] + backward[i + 1]);
        }

        return result == Integer.MIN_VALUE ? arr[0] : result;
    }
}

