import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public int maxDistance(int[][] grid) {
        int n = grid.length;
        Queue<int[]> queue = new LinkedList<>();

        // count the total number of land cells and water cells
        int landCount = 0, waterCount = 0;
        for (int[] row : grid) {
            for (int cell : row) {
                if (cell == 1) {
                    queue.offer(new int[] {landCount++, 0});
                } else if (cell == 0) {
                    waterCount++;
                }
            }
        }

        // if there is no land or water, return -1
        if (landCount == 0 || waterCount == 0) {
            return -1;
        }

        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        int maxDistance = 0;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            for (int[] direction : directions) {
                int x = current[0] / n + direction[0];
                int y = current[0] % n + direction[1];

                // check if the new position is within the grid and is a water cell
                if (x >= 0 && x < n && y >= 0 && y < n && grid[x][y] == 0) {
                    queue.offer(new int[] {x * n + y, current[1] + 1});
                    maxDistance = Math.max(maxDistance, current[1] + 1);
                    grid[x][y] = 2; // mark the cell as visited
                }
            }
        }

        return maxDistance;
    }
}

