public class Solution {
    public List<TreeNode> delNodes(TreeNode root, int[] to_delete) {
        Set<Integer> set = new HashSet<>();
        for (int num : to_delete) {
            set.add(num);
        }

        List<TreeNode> res = new ArrayList<>();
        solve(root, set, res, true);
        return res;
    }

    private TreeNode solve(TreeNode node, Set<Integer> set, List<TreeNode> res, boolean isRoot) {
        if (node == null) {
            return null;
        }

        boolean shouldDelete = set.contains(node.val);
        if (isRoot && !shouldDelete) {
            res.add(node);
        }

        node.left = solve(node.left, set, res, shouldDelete);
        node.right = solve(node.right, set, res, shouldDelete);

        return shouldDelete ? null : node;
    }
}

