public class Solution {
    public int movesToMakeZigzag(int[] nums) {
        return Math.min(moves(nums, 0), moves(nums, 1));
    }

    private int moves(int[] nums, int parity) {
        int moves = 0;
        for (int i = 0; i < nums.length; i++) {
            if ((i % 2 == parity && (!isLocalMax(nums, i))) || 
                (i % 2 != parity && (!isLocalMin(nums, i)))) {
                int max = getMaxAdjacent(nums, i);
                moves += nums[i] - max + 1;
            }
        }
        return moves;
    }

    private boolean isLocalMax(int[] nums, int index) {
        if (index == 0 || index == nums.length - 1) {
            return true;
        }
        return nums[index] > nums[index - 1] && nums[index] > nums[index + 1];
    }

    private boolean isLocalMin(int[] nums, int index) {
        if (index == 0 || index == nums.length - 1) {
            return true;
        }
        return nums[index] < nums[index - 1] && nums[index] < nums[index + 1];
    }

    private int getMaxAdjacent(int[] nums, int index) {
        int left = Integer.MAX_VALUE;
        if (index > 0) {
            left = nums[index - 1];
        }
        int right = Integer.MAX_VALUE;
        if (index < nums.length - 1) {
            right = nums[index + 1];
        }
        return Math.min(left, right);
    }
}

