import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<Boolean> canMakePaliQueries(String s, int[][] queries) {
        List<Boolean> result = new ArrayList<>();

        for (int[] query : queries) {
            String substring = s.substring(query[0], query[1] + 1);
            int[] charCount = new int[26];

            // Count the frequency of each character in the substring
            for (char c : substring.toCharArray()) {
                charCount[c - 'a']++;
            }

            int oddCount = 0;
            for (int count : charCount) {
                if (count % 2 != 0) {
                    oddCount++;
                }
            }

            // A string can be a palindrome if at most one character has an odd count
            // We can replace up to k characters, so we need to check if the number of 
            // characters with odd counts minus 1 (for the middle character in case of 
            // an odd length string) is less than or equal to k
            result.add(oddCount - 1 <= query[2]);
        }

        return result;
    }
}

