        return stoneGameIIHelper(piles, suffixSum, 0, 1, memo);
    }

    private int stoneGameIIHelper(int[] piles, int[] suffixSum, int i, int m, Integer[][] memo) {
        if (i + 2 * m >= piles.length)
            return suffixSum[i];

        if (memo[i][m] != null)
            return memo[i][m];

        int maxStones = Integer.MIN_VALUE;
        for (int x = 1; x <= 2 * m; ++x) {
            int stones = suffixSum[i] - stoneGameIIHelper(piles, suffixSum, i + x, Math.max(m, x), memo);
            maxStones = Math.max(maxStones, stones);
        }
        return memo[i][m] = maxStones;
    }
