import java.util.Arrays;
public class Solution {
    public int stoneGameII(int[] piles) {
        int n = piles.length;
        int[][] memo = new int[n][n + 1];
        for (int i = 0; i < n; i++) {
            Arrays.fill(memo[i], -1);
        }

        int suffixSum = 0;
        for (int i = n - 1; i >= 0; i--) {
            suffixSum += piles[i];
            memo[i][1] = suffixSum;
        }

        return helper(piles, memo, 0, 1);
    }

    private int helper(int[] piles, int[][] memo, int i, int m) {
        if (i + 2 * m >= piles.length) {
            return suffixSum(piles, i);
        }

        if (memo[i][m] != -1) {
            return memo[i][m];
        }

        int maxStones = Integer.MIN_VALUE;
        for (int x = 1; x <= 2 * m; x++) {
            int stones = suffixSum(piles, i);
            int bobStones = helper(piles, memo, i + x, Math.max(m, x));
            maxStones = Math.max(maxStones, stones - bobStones);
        }

        memo[i][m] = maxStones;
        return maxStones;
    }

    private int suffixSum(int[] piles, int i) {
        int sum = 0;
        for (int j = i; j < piles.length; j++) {
            sum += piles[j];
        }
        return sum;
    }
}

