import java.util.Arrays;
public class Solution {
    public int stoneGameII(int[] piles) {
        int n = piles.length;
        int[][] dp = new int[n][n + 1];

        // Reverse the piles array to make it easier to calculate
        for (int i = n - 1; i >= 0; i--) {
            int suffixSum = 0;
            for (int j = i; j < n; j++) {
                suffixSum += piles[j];

                // For each possible M from 1 to j - i + 1
                for (int m = 1; m <= j - i + 1; m++) {
                    if (j + 2 * m >= n) {
                        dp[i][m] = Math.max(dp[i][m], suffixSum);
                    } else {
                        dp[i][m] = Math.max(dp[i][m], suffixSum - dp[j + 2 * m][Math.max(m, 2)]);
                    }
                }
            }
        }

        // Calculate Alice's maximum stones
        int aliceMaxStones = dp[0][1];

        return aliceMaxStones;
    }

}

