        int n = req_skills.length;
        int[] dp = new int[1 << n];
        Arrays.fill(dp, Integer.MAX_VALUE);

        dp[0] = 0;

        for (int mask = 1; mask < (1 << n); mask++) {
            dp[mask] = -1;
            for (List<String> person : people) {
                int curMask = 0;
                for (String skill : person) {
                    if (skillToIndex.containsKey(skill)) {
                        int index = skillToIndex.get(skill);
                        curMask |= (1 << index);
                    }
                }

                int newMask = mask & (~curMask);
                if (newMask == 0 || dp[mask] < dp[newMask] + 1) continue;

                dp[mask] = dp[newMask] + 1;
            }
        }

        List<Integer> result = new ArrayList<>();
        int mask = (1 << n) - 1;
        for (int i = people.size() - 1; i >= 0 && mask > 0; i--) {
            if (dp[mask & ~getPersonMask(skillToIndex, req_skills.length, people.get(i))] == dp[mask] - 1) {
                result.add(i);
                mask &= ~getPersonMask(skillToIndex, req_skills.length, people.get(i));
            }
        }

        int[] res = new int[result.size()];
        for (int i = 0; i < result.size(); i++) {
            res[i] = result.get(result.size() - 1 - i);
        }

        return res;
    }

    private int getPersonMask(Map<String, Integer> skillToIndex, int n, List<String> person) {
