public class Solution {
    public int maxLevelSum(TreeNode root) {
        if (root == null) return 0;

        int level = 0, maxSum = Integer.MIN_VALUE, resultLevel = 0;
        List<List<Integer>> levels = new ArrayList<>();

        traverse(root, 0, levels);

        for (List<Integer> list : levels) {
            level++;
            int sum = 0;
            for (int num : list) {
                sum += num;
            }
            if (sum > maxSum) {
                maxSum = sum;
                resultLevel = level;
            }
        }

        return resultLevel;
    }

    private void traverse(TreeNode node, int depth, List<List<Integer>> levels) {
        if (node == null) return;

        if (depth >= levels.size()) {
            levels.add(new ArrayList<>());
        }

        levels.get(depth).add(node.val);

        traverse(node.left, depth + 1, levels);
        traverse(node.right, depth + 1, levels);
    }
}

