                for (boolean b : list) {
                    if (!b) {
                        stack.push(false);
                        break;
                    }
                }
                if (stack.isEmpty() || !stack.isEmpty() && stack.peek() == null) {
                    stack.push(true);
                }
            } else if (c == '|') {
                List<Boolean> list = new ArrayList<>();
                while (!stack.isEmpty() && stack.peek() != null) {
                    list.add(stack.pop());
                }
                stack.pop(); // remove the operator
                for (boolean b : list) {
                    if (b) {
                        stack.push(true);
                        break;
                    }
                }
                if (stack.isEmpty() || !stack.isEmpty() && stack.peek() == null) {
                    stack.push(false);
                }
            } else if (c == '(') {
                stack.push(null); // push a dummy value to mark the start of an expression
            } else if (c == ')') {
                List<Boolean> list = new ArrayList<>();
                while (!stack.isEmpty() && stack.peek() != null) {
                    list.add(stack.pop());
                }
                stack.pop(); // remove the dummy value
                boolean result = true;
                for (boolean b : list) {
                    result &= b;
                }
                stack.push(result);
            }
        }

        return stack.pop();
    }
