import java.util.ArrayList;
import java.util.List;

public class Solution {
    public boolean parseBoolExpr(String expression) {
        return new Object() {
            int pos = -1, len = expression.length();
            boolean parseBoolean() {
                ++pos; char ch = nextChar();
                if (ch == 't') return true;
                else if (ch == 'f') return false;
                else if (ch == '!') {
                    ++pos; 
                    boolean v = !parseBoolean();
                    expect(',');
                    skipBlanks();
                    expect(')');
                    return v;
                } else if (ch == '&') {
                    ++pos; 
                    List<Boolean> vs = new ArrayList<>();
                    vs.add(parseBoolean());
                    while (hasNext()) {
                        expect(',');
                        skipBlanks(); 
                        vs.add(parseBoolean());
                    }
                    expect(')'); 
                    for (boolean v : vs) if (!v) return false;
                    return true;
                } else if (ch == '|') {
                    ++pos; 
                    List<Boolean> vs = new ArrayList<>();
                    vs.add(parseBoolean());
                    while (hasNext()) {
                        expect(',');
                        skipBlanks();
                        vs.add(parseBoolean());
                    }
                    expect(')');
                    for (boolean v : vs) if (v) return true;
                    return false;
                } else throw new RuntimeException("Unexpected: " + ch);
            }

            boolean hasNext() { 
                while (pos < len && expression.charAt(pos) == ' ') pos++;
                return pos < len; 
            }
            char nextChar() {
                while (hasNext()) {
                    char ch = expression.charAt(++pos); 
                    if (ch != ' ') return ch;
                } 
                throw new RuntimeException("Unexpected end of input"); 
            }
            void expect(char ch) { 
                if (!hasNext() || expression.charAt(pos++) != ch)
                    throw new RuntimeException("Expected '" + ch + "' but got: " + (hasNext() ? expression.charAt(pos - 1) : "<end>"));
            }

            void skipBlanks() {
                while (pos < len && expression.charAt(pos) == ' ') pos++;
            }
        }.parseBoolean();
    }
}

