import java.util.Stack;

public class Solution {
    public boolean parseBoolExpr(String expression) {
        Stack<Boolean> stack = new Stack<>();

        for (char c : expression.toCharArray()) {
            if (c == ',') continue;
            if (c != ')') {
                if (Character.isLetter(c)) {
                    stack.push(c == 't');
                } else {
                    stack.push(null); // operator
                }
                continue;
            }

            List<Boolean> list = new ArrayList<>();
            while (stack.peek() != null) list.add(0, stack.pop());
            boolean op = stack.pop();
            if (!op) { // |
                boolean result = false;
                for (boolean b : list) {
                    result |= b;
                }
                stack.push(result);
            } else { // &
                boolean result = true;
                for (boolean b : list) {
                    result &= b;
                }
                stack.push(result);
            }
        }

        return stack.pop();
    }

    private void evaluateExpression(char operator, Stack<Boolean> stack) {
        if (operator == '!') {
            boolean value = stack.pop();
            stack.push(!value);
        } else if (operator == '&') {
            List<Boolean> values = new ArrayList<>();
            while (!stack.isEmpty() && stack.peek() != null) {
                values.add(0, stack.pop());
            }
            for (boolean b : values) {
                if (!b) {
                    stack.push(false);
                    return;
                }
            }
            stack.push(true);
        } else if (operator == '|') {
            List<Boolean> values = new ArrayList<>();
            while (!stack.isEmpty() && stack.peek() != null) {
                values.add(0, stack.pop());
            }
            for (boolean b : values) {
                if (b) {
                    stack.push(true);
                    return;
                }
            }
            stack.push(false);
        }
    }
}

