public class Solution {
    public String lastSubstring(String s) {
        int n = s.length();
        int maxLen = 0;
        String result = "";

        for (int i = 0; i < n; i++) {
            boolean isGreater = false;

            for (int j = i + 1; j <= n - maxLen; j++) {
                if (s.charAt(i) > s.charAt(j)) {
                    isGreater = true;
                    break;
                } else if (s.charAt(i) < s.charAt(j)) {
                    break;
                }
            }

            if (isGreater || i + maxLen >= n) {
                continue;
            }

            int len = 0;
            while (i + len < n && j + len <= n) {
                if (j + len == n || s.charAt(i + len) > s.charAt(j + len)) {
                    isGreater = true;
                    break;
                } else if (s.charAt(i + len) < s.charAt(j + len)) {
                    break;
                }

                len++;
            }

            if (isGreater && len > maxLen) {
                maxLen = len;
                result = s.substring(i, i + maxLen);
            }
        }

        return result;
    }
}

