import java.util.Arrays;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numRollsToTarget(int n, int k, int target) {
        Integer[][] memo = new Integer[n + 1][target + 1];

        return dp(n, k, target, memo);
    }

    private int dp(int diceLeft, int faces, int totalSum, Integer[][] memo) {
        if (diceLeft == 0 && totalSum == 0) {
            return 1;
        }

        if (diceLeft == 0 || totalSum < 0) {
            return 0;
        }

        if (memo[diceLeft][totalSum] != null) {
            return memo[diceLeft][totalSum];
        }

        int ways = 0;

        for (int i = 1; i <= faces; i++) {
            ways += dp(diceLeft - 1, faces, totalSum - i, memo);
            ways %= MOD;
        }

        return memo[diceLeft][totalSum] = ways;
    }
}

