public class Solution {
    private static final int MOD = 1000000007;

    public int kConcatenationMaxSum(int[] arr, int k) {
        // Base case for k equals 1
        if (k == 1) {
            return Kadane(arr);
        }

        long sum = getArraySum(arr);

        if (sum <= 0) {
            // If the total sum is negative or zero, just calculate Kadane of arr * 2
            int[] tempArr = new int[arr.length * 2];
            for (int i = 0; i < arr.length; i++) {
                tempArr[i] = arr[i];
                tempArr[i + arr.length] = arr[i];
            }
            return Math.max(Kadane(tempArr), 0);
        } else {
            // If the total sum is positive, calculate Kadane of arr * 2 plus (k-2) times the total sum
            int[] tempArr = new int[arr.length * 2];
            for (int i = 0; i < arr.length; i++) {
                tempArr[i] = arr[i];
                tempArr[i + arr.length] = arr[i];
            }
            return (Kadane(tempArr) + (int) ((sum % MOD) * ((k - 2) % MOD)) % MOD) % MOD;
        }
    }

    private int Kadane(int[] nums) {
        // Implementing the Kadane algorithm
        int maxSoFar = Integer.MIN_VALUE, maxEndingHere = 0;

        for (int num : nums) {
            maxEndingHere += num;
            if (maxSoFar < maxEndingHere) {
                maxSoFar = maxEndingHere;
            }
            if (maxEndingHere < 0) {
                maxEndingHere = 0;
            }
        }

        // If the maximum sum is negative, return 0
        return Math.max(maxSoFar, 0);
    }

    private long getArraySum(int[] nums) {
        long sum = 0;
        for (int num : nums) {
            sum += num;
        }
        return sum % MOD;
    }
}

