public class Solution {
    public String[] invalidTransactions(String[] transactions) {
        int n = transactions.length;
        boolean[] invalid = new boolean[n];

        // Parse each transaction
        Map<String, List<Integer>> seen = new HashMap<>();
        for (int i = 0; i < n; i++) {
            String[] parts = transactions[i].split(",");
            if (Integer.parseInt(parts[2]) > 1000) {
                invalid[i] = true;
            }

            String name = parts[0];
            int time = Integer.parseInt(parts[1]);
            String city = parts[3];

            // Check for conflicts
            List<Integer> indices = seen.getOrDefault(name, new ArrayList<>());
            for (int j : indices) {
                String[] otherParts = transactions[j].split(",");
                if (!otherParts[3].equals(city) && Math.abs(time - Integer.parseInt(otherParts[1])) <= 60) {
                    invalid[i] = true;
                    invalid[j] = true;
                }
            }

            // Update seen
            indices.add(i);
            seen.put(name, indices);
        }

        // Collect invalid transactions
        List<String> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (invalid[i]) {
                result.add(transactions[i]);
            }
        }

        return result.toArray(new String[result.size()]);
    }
