import java.util.LinkedList;
import java.util.List;

public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        List<Integer> result = new LinkedList<>();
        int level = 0;
        while ((1 << level) - 1 < label) {
            level++;
        }

        while (level >= 0) {
            if (level % 2 == 0) {
                result.add(0, label);
            } else {
                int start = (1 << (level - 1)) - 1;
                int end = (1 << level) - 1;
                int reversedLabel = start + end - label;
                result.add(0, reversedLabel);
            }

            if (label == 1) break;
            label /= 2;
            level--;
        }

        return result;
    }
}

