import java.util.List;

public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        int row = 1, num = 1;
        while (num < label) {
            num *= 2;
            row++;
        }

        List<Integer> res = new LinkedList<>();
        while (label > 0) {
            res.add(0, label);
            row--;
            int totalNodesInRow = 1 << (row - 1); // equivalent to Math.pow(2, row - 1)
            int maxLabelInRow = (1 << row) - 1; // equivalent to Math.pow(2, row) - 1
            label = maxLabelInRow - (label - totalNodesInRow);
        }
        return res;
    }
}

