import java.util.LinkedList;
import java.util.List;

public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        List<Integer> result = new LinkedList<>();
        int level = 0, nodes = 1;

        // find the current level of the node
        while (nodes < label) {
            nodes *= 2;
            level++;
        }

        // traverse from the given label to the root
        for (; level >= 0; level--) {
            int numNodesInLevel = (int)Math.pow(2, level);
            int leftMostNode = (int)Math.pow(2, level) - 1;
            int rightMostNode = (int)(Math.pow(2, level + 1) - 2);

            // for even rows, calculate the mirrored node
            if ((level & 1) == 0) {
                result.add(0, label);
            } else {
                int parentLabel = leftMostNode + rightMostNode - label;
                result.add(0, parentLabel);
            }

            label /= 2; // move to the parent node
        }

        return result;
    }
}

