import java.util.List;

public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        int level = 0, nodeNum = 1;
        while (nodeNum < label) {
            level++;
            nodeNum *= 2;
        }

        List<Integer> ans = new LinkedList<>();
        while (level >= 0) {
            ans.add(0, label);
            int totalNodesOnLevel = (int) Math.pow(2, level);
            int nodesInPreviousLevels = (totalNodesOnLevel - 1) * 2;
            if ((level & 1) == 1) {
                label = nodesInPreviousLevels + (totalNodesOnLevel - (label - nodesInPreviousLevels)) - 1;
            } else {
                label = nodesInPreviousLevels + totalNodesOnLevel - (label - nodesInPreviousLevels);
            }
            level--;
        }

        return ans;
    }
}

