        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        // Build the graph
        for (int[] edge : redEdges) {
            graph.get(edge[0]).add(new int[]{edge[1], 0});
        }

        for (int[] edge : blueEdges) {
            graph.get(edge[0]).add(new int[]{edge[1], 1});
        }

        // Initialize the result array and queue
        int[][] distances = new int[n][2];
        for (int i = 1; i < n; i++) {
            Arrays.fill(distances[i], -1);
        }

        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{0, 0});
        queue.offer(new int[]{0, 1});
        distances[0][0] = distances[0][1] = 0;

        // Perform BFS
        int step = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int[] node = queue.poll();
                int x = node[0];
                int color = node[1];

                // Iterate over all neighbors of the current node
                for (int[] neighbor : graph.get(x)) {
                    if (neighbor[1] != color && (distances[neighbor[0]][neighbor[1]] == -1 || distances[neighbor[0]][neighbor[1]] > step + 1)) {
                        queue.offer(new int[]{neighbor[0], neighbor[1]});
                        distances[neighbor[0]][neighbor[1]] = step + 1;
                    }
                }
            }

            // Move on to the next step
            step++;
        }

        // Handle nodes where no path exists
        int[] answer = new int[n];
        for (int i = 0; i < n; i++) {
            if (distances[i][0] == -1 && distances[i][1] == -1) {
                answer[i] = -1;
            } else if (distances[i][0] == -1 || distances[i][1] == -1) {
                answer[i] = Math.max(distances[i][0], distances[i][1]);
            } else {
                answer[i] = Math.min(distances[i][0], distances[i][1]);
            }
        }

        return answer;
    }
}

