        int[][] board = new int[26][2];
        char c = 'a';
        for (int i = 0; i < 6; i++) {
            if (i == 5) {
                board[c - 'a'][0] = i;
                board[c - 'a'][1] = 0;
                c++;
            } else {
                for (int j = 0; j < 5; j++) {
