            int code = ch - 'a';
            int newX = board[code][0];
            int newY = board[code][1];

            if (newY < y) {
                for (int i = 0; i < y - newY; i++) sb.append("L");
            }
            if (newX < x) {
                for (int i = 0; i < x - newX; i++) sb.append("U");
            }
            if (newX > x) {
                for (int i = 0; i < newX - x; i++) sb.append("D");
            }
            if (newY > y) {
                for (int i = 0; i < newY - y; i++) sb.append("R");
