        for (char ch : target.toCharArray()) {
            int targetIndex = ch - 'a';
            int targetRow = BOARD[targetIndex][0];
            int targetCol = BOARD[targetIndex][1];

            if (targetCol < currentCol) result.append(repeat('L', currentCol - targetCol));
            if (targetRow < currentRow) result.append(repeat('U', currentRow - targetRow));
            if (targetRow > currentRow) result.append(repeat('D', targetRow - currentRow));
            if (targetCol > currentCol) result.append(repeat('R', targetCol - currentCol));

            result.append('!');

            currentRow = targetRow;
            currentCol = targetCol;
        }

        return result.toString();
    }

    private String repeat(char ch, int count) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < count; i++) {
            sb.append(ch);
        }
        return sb.toString();
    }
}

