public class Solution {
    private static final int[][] BOARD = new int[26][2];
    static {
        int index = 0;
        for (int i = 0; i < 6; i++) {
            for (int j = 0; j < 5; j++) {
                if (index >= 26) break;
                BOARD[index][0] = i;
                BOARD[index][1] = j;
                index++;
            }
        }
    }

    public String alphabetBoardPath(String target) {
        StringBuilder path = new StringBuilder();
        int prevRow = 0, prevCol = 0;
        for (char c : target.toCharArray()) {
            int currIndex = c - 'a';
            int currRow = BOARD[currIndex][0];
            int currCol = BOARD[currIndex][1];

            if (currRow == 5 && currCol == 0) {
                path.append("U");
                prevRow--;
            }

            int rowDiff = Math.abs(currRow - prevRow);
            for (int i = 0; i < rowDiff; i++) {
                if (currRow > prevRow) path.append('D');
                else path.append('U');
            }

            int colDiff = Math.abs(currCol - prevCol);
            for (int i = 0; i < colDiff; i++) {
                if (currCol > prevCol) path.append('R');
                else path.append('L');
            }

            path.append('!');
            prevRow = currRow;
            prevCol = currCol;

            if (prevRow == 5 && prevCol == 0) {
                prevRow++;
                path.deleteCharAt(path.length() - 2);
            }
        }
        return path.toString();
    }
}

