import java.util.Arrays;

public class Solution {
    public int[] numSmallerByFrequency(String[] queries, String[] words) {
        int n = words.length;
        int[] wordFreqs = new int[n];

        for (int i = 0; i < n; i++) {
            wordFreqs[i] = getMinCharFrequency(words[i]);
        }

        Arrays.sort(wordFreqs);

        int m = queries.length;
        int[] result = new int[m];

        for (int i = 0; i < m; i++) {
            int queryFreq = getMinCharFrequency(queries[i]);

            // Find the number of words with frequency greater than query frequency
            int count = n - binarySearch(wordFreqs, queryFreq);

            result[i] = count;
        }

        return result;
    }

    private int getMinCharFrequency(String s) {
        char minChar = 'z';
        for (char c : s.toCharArray()) {
            if (c < minChar) {
                minChar = c;
            }
        }

        int frequency = 0;
        for (char c : s.toCharArray()) {
            if (c == minChar) {
                frequency++;
            }
        }

        return frequency;
    }

    private int binarySearch(int[] arr, int target) {
        int left = 0;
        int right = arr.length - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (arr[mid] > target) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        return left;
    }
}

