import java.util.Arrays;

public class Solution {
    public int[] numSmallerByFrequency(String[] queries, String[] words) {
        int n = words.length;
        int[] wordFrequencies = new int[n];

        // Calculate the frequency of lexicographically smallest character for each word
        for (int i = 0; i < n; i++) {
            wordFrequencies[i] = getFrequency(words[i]);
        }

        Arrays.sort(wordFrequencies);

        int m = queries.length;
        int[] result = new int[m];

        // For each query, count the number of words with a higher frequency
        for (int i = 0; i < m; i++) {
            int queryFrequency = getFrequency(queries[i]);
            int idx = binarySearch(wordFrequencies, queryFrequency);
            result[i] = n - idx;
        }

        return result;
    }

    // Binary search to find the index of the first element greater than or equal to the target
    private int binarySearch(int[] arr, int target) {
        int left = 0, right = arr.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] <= target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }

    // Calculate the frequency of lexicographically smallest character in a string
    private int getFrequency(String s) {
        char minChar = s.charAt(0);
        for (char c : s.toCharArray()) {
            if (c < minChar) {
                minChar = c;
            }
        }
        int count = 0;
        for (char c : s.toCharArray()) {
            if (c == minChar) {
                count++;
            }
        }
        return count;
    }
}

