public class Solution {
    public List<List<Integer>> criticalConnections(int n, int[][] connections) {
        // build graph
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int[] connection : connections) {
            graph.get(connection[0]).add(connection[1]);
            graph.get(connection[1]).add(connection[0]);
        }

        // rank[] records the each node's smallest rank(min (it's natural rank, neighbors's smallest rank))
        int[] rank = new int[n];
        Arrays.fill(rank, -1);

        List<List<Integer>> result = new ArrayList<>();
        dfs(graph, 0, -1, rank, result, connections);
        return result;
    }

    private void dfs(List<List<Integer>> graph, int node, int parent, int[] rank, List<List<Integer>> result, int[][] connections) {
        // record the current natural rank for current node
        if (rank[node] != -1) {
            return;
        }
        rank[node] = graph.size();
        for (int nei : graph.get(node)) {
            // skip the parent, since this is undirected graph
            if (nei == parent) {
                continue;
            }

            // step1 : run dfs to get the rank of this nei, if it is visited before, it will reach base case immediately
            if (rank[nei] == -1) {
                dfs(graph, nei, node, rank, result, connections);
            }
            // if neiTime is strictly larger than current node's rank, there is no cycle, 
            // connections between node and nei is a critically connection.
            for (int[] connection : connections) {
                if ((connection[0] == node && connection[1] == nei) || (connection[0] == nei && connection[1] == node)) {
                    if (rank[nei] > rank[node]) {
                        result.add(Arrays.asList(connection[0], connection[1]));
                    }
                }
            }

            // keep updating current node's rank with nei's smaller ranks
            rank[node] = Math.min(rank[node], rank[nei]);
        }
