            // Step1: Run dfs to get the rank of this nei
            if (rank[neighbor] == 0) {
                dfs(graph, connections, criticalConnections, rank, neighbor, current, currentTime + 1);
            }

            // Update current node's rank with nei's smaller ranks
            rank[current] = Math.min(rank[current], rank[neighbor]);

            // If neiTime is strictly larger than current node's rank, there is no cycle,
            // connections between node and nei is a critically connection
            if (rank[neighbor] > currentTime + 1) {
                for (int[] connection : connections) {
                    if ((connection[0] == current && connection[1] == neighbor) || 
                        (connection[0] == neighbor && connection[1] == current)) {
                        criticalConnections.add(Arrays.asList(connection[0], connection[1]));
                    }
                }
            }
        }
    }
}

