// #Hard #Depth_First_Search #Graph #Biconnected_Component
// #2022_03_03_Time_127_ms_(89.39%)_Space_262.1_MB_(59.13%)
import java.util.*;

public class Solution {
    int time = 0;
    public List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {
        // build graph
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (List<Integer> connection : connections) {
            if (!graph.containsKey(connection.get(0))) {
                graph.put(connection.get(0), new ArrayList<>());
            }
            if (!graph.containsKey(connection.get(1))) {
                graph.put(connection.get(1), new ArrayList<>());
            }
            graph.get(connection.get(0)).add(connection.get(1));
            graph.get(connection.get(1)).add(connection.get(0));
        }

        // record rank
        int[] rank = new int[n];
        Arrays.fill(rank, -1);

        // store result
        List<List<Integer>> result = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            if (rank[i] == -1) {
                dfs(i, graph, rank, result, -1);
            }
        }

        return result;
    }

    private int dfs(int node, Map<Integer, List<Integer>> graph, int[] rank, List<List<Integer>> result, int parent) {
        // record the current natural rank for current node
        time++;
        if (rank[node] != -1) {
            return rank[node];
        }
        rank[node] = time;

        // skip the parent, since this is undirected graph
        for (int nei : graph.get(node)) {
            if (nei == parent) {
                continue;
            }

            // step1 : run dfs to get the rank of this nei, if it is visited before, it will reach base case immediately
            int neiTime = dfs(nei, graph, rank, result, node);

            // if neiTime is strictly larger than current node's rank, there is no cycle,
            // connections between node and nei is a critically connection.
            if (neiTime > rank[node]) {
                result.add(Arrays.asList(node, nei));
            }

            // keep updating current node's rank with nei's smaller ranks
            rank[node] = Math.min(rank[node], neiTime);
        }

        // return current node's rank to caller
        return rank[node];
    }
}

