import java.util.Arrays;

public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        Arrays.sort(sums);
        int[] ans = new int[n];

        for (int i = 0; i < n; i++) {
            boolean[] seen = new boolean[sums.length];

            int[] subsetSums = new int[1 << n];
            subsetSums[0] = 0;

            int maxSubsetSumIndex = 0;

            for (int j = 1; j < (1 << n); j++) {
                subsetSums[j] = -1;

                for (int k = 0; k < n; k++) {
                    if ((j & (1 << k)) != 0) {
                        int prevSubsetSumIndex = j ^ (1 << k);

                        if (subsetSums[prevSubsetSumIndex] == -1) continue;

                        subsetSums[j] = subsetSums[prevSubsetSumIndex] + ans[k];
                    }
                }
            }

            boolean isValid = true;

            for (int sum : sums) {
                int subsetSumIndex = -1;

                for (int j = 0; j < (1 << n); j++) {
                    if (!seen[j] && subsetSums[j] == sum) {
                        seen[j] = true;
                        subsetSumIndex = j;
                        break;
                    }
                }

                if (subsetSumIndex == -1) {
                    isValid = false;
                    break;
                }
            }

            if (!isValid) continue;

            ans[i] = sums[sums.length - 1] - sums[0];
        }

        return ans;
    }
}

