import java.util.Arrays;

public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        Arrays.sort(sums);
        int[] ans = new int[n];

        for (int i = 0; i < n; i++) {
            int maxSum = sums[sums.length - 1];
            boolean[] exist = new boolean[sums.length];

            ans[i] = maxSum - sums[sums.length - 2];
            exist[exist.length - 1] = true;

            for (int j = sums.length - 2; j >= 0; j--) {
                if (!exist[j]) {
                    int diff = maxSum - sums[j];

                    boolean found = false;
                    for (int k = sums.length - 1; k >= 0; k--) {
                        if (!exist[k] && sums[k] == sums[j] + diff) {
                            exist[k] = true;
                            found = true;
                            break;
                        }
                    }

                    if (!found) {
                        exist[exist.length - 1] = false;
                        ans[i] = maxSum - sums[j];
                        j++;
                        break;
                    }
                }
            }

            int[] newSums = new int[sums.length];
            int index = 0;
            for (int k = 0; k < exist.length; k++) {
                if (!exist[k]) {
                    newSums[index++] = sums[k];
                }
            }

            sums = Arrays.copyOfRange(newSums, 0, index);
        }

        return ans;
    }
}

