public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numberOfUniqueGoodSubsequences(String binary) {
        long hasZero = 0, hasOne = 0, noLeadingZeros = 0;

        for (char c : binary.toCharArray()) {
            if (c == '0') {
                noLeadingZeros = (noLeadingZeros + hasOne) % MOD;
                hasZero = (hasZero + noLeadingZeros + hasOne) % MOD;
            } else {
                noLeadingZeros = (noLeadingZeros * 2) % MOD;
                hasOne = (hasOne + noLeadingZeros) % MOD;
            }
        }

        long result = (hasZero + hasOne) % MOD;
        if (binary.contains("0")) {
            result++;
        }
        return (int) result;
    }
