    public int numberOfUniqueGoodSubsequences(String binary) {
        long endsWithOne = 0, endsWithZero = 0, hasZero = 0;

        for (char c : binary.toCharArray()) {
            if (c == '1') {
                endsWithOne = (endsWithOne * 2 + 1) % MOD;
                endsWithZero = (endsWithZero * 2) % MOD;
            } else {
                hasZero = 1;
                endsWithZero = (endsWithOne + endsWithZero * 2) % MOD;
                endsWithOne = endsWithOne * 2 % MOD;
            }
        }

        long result = (endsWithOne + endsWithZero) % MOD;
        if (hasZero == 1) {
            result += 1; // for "0"
        }

        return (int) result;
    }
