public class Solution {
    public int[] longestObstacleCourseAtEachPosition(int[] obstacles) {
        int n = obstacles.length;
        int[] dp = new int[n];
        int[] tails = new int[n + 1];
        int len = 0;

        for (int i = 0; i < n; i++) {
            int newLen = binarySearch(tails, len, obstacles[i]);
            dp[i] = newLen + 1;
            if (newLen == len) {
                tails[++len] = i;
            } else {
                tails[newLen] = i;
            }
        }

        return dp;
    }

    private int binarySearch(int[] tails, int len, int val) {
        int l = 0, r = len - 1;
        if (obstacles[tails[len]] <= val) {
            return len;
        }

        while (l < r) {
            int mid = l + (r - l) / 2;
            if (obstacles[tails[mid]] > val) {
                l = mid + 1;
            } else {
                r = mid;
            }
        }

        return l;
    }
}

