        int len = 0;
        tails[0] = Integer.MIN_VALUE;

        for (int i = 0; i < n; i++) {
            int left = 0, right = len;
            while (left < right) {
                int mid = (left + right) / 2;
                if (tails[mid] <= obstacles[i]) {
                    left = mid + 1;
                } else {
                    right = mid;
                }
            }

            result[i] = left + 1;
            tails[left + 1] = obstacles[i];
            len = Math.max(len, left + 1);
        }

        return result;
    }
}

