            boolean leftGreater = mid - 1 >= 0 && mat[maxRow][mid - 1] > mat[maxRow][mid];
            boolean rightGreater = mid + 1 < n && mat[maxRow][mid + 1] > mat[maxRow][mid];

            if (!leftGreater && !rightGreater) {
                return new int[] {maxRow, mid};
            } else if (leftGreater) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        throw new RuntimeException("No peak element found");
    }
}

