public class Solution {
    public int[] findPeakGrid(int[][] mat) {
        int m = mat.length, n = mat[0].length;
        int left = 0, right = n - 1;

        while (left <= right) {
            int col = left + (right - left) / 2;

            // Find the maximum value in this column
            int maxRow = findMaxRow(mat, m, col);

            // Check if this is a peak element
            if ((col == 0 || mat[maxRow][col] > mat[maxRow][col - 1]) && 
                (col == n - 1 || mat[maxRow][col] > mat[maxRow][col + 1])) {

                // Check top and bottom neighbors
                if ((maxRow == 0 || mat[maxRow][col] > mat[maxRow - 1][col]) && 
                    (maxRow == m - 1 || mat[maxRow][col] > mat[maxRow + 1][col])) {
                        return new int[] { maxRow, col };
                }
            }

            // If not a peak element, move to the left or right half
            if (col > 0 && mat[maxRow][col - 1] > mat[maxRow][col]) {
                right = col - 1;
            } else {
                left = col + 1;
            }
        }

        return new int[] { };
    }

    private int findMaxRow(int[][] mat, int m, int col) {
        int maxRow = 0;
        for (int i = 1; i < m; i++) {
            if (mat[i][col] > mat[maxRow][col]) {
                maxRow = i;
            }
        }
        return maxRow;
    }
}

